import { app, BrowserWindow, ipcMain } from "electron";
import path from "path";
import http from "http";
import https from "https";
const net = require("net");

// Disable GPU early to avoid Windows GPU cache issues
try {
  app.commandLine.appendSwitch("disable-gpu");
} catch (e) {
  // ignore
}

// In dev, disable hardware acceleration to avoid GPU cache permission issues on Windows
if (process.env.NODE_ENV !== "production") {
  try {
    app.disableHardwareAcceleration();
  } catch (e) {
    // ignore
  }
  try {
    const userDataPath = path.join(process.cwd(), ".user-data");
    app.setPath("userData", userDataPath);
  } catch (e) {
    // ignore
  }
}

let mainWindow: BrowserWindow | null = null;

async function waitForServer(url: string, timeoutMs = 15000) {
  const start = Date.now();
  const parsed = new URL(url);
  const isHttps = parsed.protocol === "https:";

  function checkOnce(): Promise<boolean> {
    return new Promise((resolve) => {
      const req = (isHttps ? https : http).request(
        {
          method: "GET",
          host: parsed.hostname,
          port: parsed.port || (isHttps ? 443 : 80),
          path: parsed.pathname + (parsed.search || ""),
          timeout: 2000,
        },
        (res) => {
          const ok = res.statusCode && res.statusCode < 500;
          res.resume();
          resolve(!!ok);
        },
      );
      req.on("error", () => resolve(false));
      req.on("timeout", () => {
        req.destroy();
        resolve(false);
      });
      req.end();
    });
  }

  while (Date.now() - start < timeoutMs) {
     
    const ok = await checkOnce();
    if (ok) {
return true;
}
     
    await new Promise((r) => setTimeout(r, 500));
  }
  return false;
}

async function createWindow() {
  mainWindow = new BrowserWindow({
    width: 1280,
    height: 800,
    webPreferences: {
      // Always use the JS shim for preload. The shim will register ts-node and require preload.ts during dev.
      preload: path.join(__dirname, "preload.js"),
      contextIsolation: true,
      nodeIntegration: false,
    },
  });

  // Install React DevTools in dev (best-effort) ΓÇö opt-in via INSTALL_REACT_DEVTOOLS env var
  if (process.env.NODE_ENV !== "production") {
    try {
      if (process.env.INSTALL_REACT_DEVTOOLS === "1") {
         
        const installer = require("electron-devtools-installer");
         
        await installer
          .default(installer.REACT_DEVELOPER_TOOLS)
          .then((name: any) => console.log("Added Extension:", name))
          .catch((e: any) => console.warn("DevTools install failed", e));
      }
    } catch (e) {
      // ignore devtools install errors
    }
  }

  // Try common Vite dev ports if default 5173 is taken - expand range to cover up to 5180
  const candidatePorts = [5173, 5174, 5175, 5176, 5177, 5178, 5179, 5180];
  let loaded = false;
  for (const port of candidatePorts) {
    const devUrl = `http://localhost:${port}`;
    // wait briefly for server
     
    const ready = await waitForServer(devUrl, 2000);
    if (ready) {
      mainWindow.loadURL(devUrl);
      // Open DevTools in development for easier debugging
      try {
        mainWindow.webContents.openDevTools({ mode: "right" });
      } catch (e) {
        // ignore if webContents not ready
      }
      loaded = true;
      break;
    }
  }

  if (!loaded) {
    // fallback: load a small local waiting page
    mainWindow.loadURL(
      "data:text/html,<h2>Renderer not ready</h2><p>Please start the renderer (vite) and ensure it is running on a dev port.</p>",
    );
  }

  mainWindow.on("closed", () => {
    mainWindow = null;
  });
}

app.whenReady().then(() => {
  createWindow();
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") {
app.quit();
}
});

async function getPrinterConfig() {
  try {
    return {
      usbPrinterName: process.env.KITCHEN_PRINTER_USB_NAME || "POS-80C",
    };
  } catch (e) {
    return {
      usbPrinterName: "POS-80C",
    };
  }
}

function getUsbDeviceDiagnostics() {
  try {
     
    const usb = require("usb");
    const devices = usb.getDeviceList().map((device: any) => {
      try {
        const info = {
          vendorId: device.deviceDescriptor?.idVendor,
          productId: device.deviceDescriptor?.idProduct,
          manufacturer: device.deviceDescriptor?.iManufacturer,
          product: device.deviceDescriptor?.iProduct,
        };
        return info;
      } catch (d) {
        return { error: String(d) };
      }
    });
    return { count: devices.length, devices };
  } catch (err: any) {
    return {
      error: "usb module unavailable",
      detail: (err && err.message) || String(err),
    };
  }
}

/**
 * printViaWindowsRaw ΓÇö sends raw ESC/POS bytes to the printer using the
 * Windows `copy /b` command.
 *
 * WHY `copy /b` and not Out-Printer / plain text:
 *   Out-Printer sends content through the Windows GDI renderer (a document
 *   pipeline), which adds page margins, uses a system font, and completely
 *   ignores ESC/POS control bytes ΓÇö that is why text printed light, off-center,
 *   and from the middle of the page.
 *   `copy /b` sends the raw binary file directly to the printer port via the
 *   Windows spooler with no transformation ΓÇö ESC/POS commands reach the
 *   firmware as-is, giving bold text, correct alignment and a proper cut.
 *
 * REQUIREMENT: the printer must be installed in Windows
 *   (visible in Settings ΓåÆ Printers & Scanners).
 *   No driver replacement or Zadig needed.
 *
 * LOG GUIDANCE ΓÇö watch the Electron console for:
 *   [WIN-RAW] Listed printers: [...]  ΓåÆ all installed Windows printer names.
 *                                       If your printer is missing, install it first.
 *   [WIN-RAW] WARNING: not found      ΓåÆ name mismatch. Set KITCHEN_PRINTER_USB_NAME
 *                                       to the exact name shown in the list above.
 *   [WIN-RAW] printer confirmed       ΓåÆ name matched, proceeding.
 *   [WIN-RAW] copy /b succeeded       ΓåÆ bytes delivered to firmware Γ£à
 *   [WIN-RAW] FAILED                  ΓåÆ copy command rejected ΓÇö check printer name/port.
 */
// Helpers to emit text / CRLF as bytes
function pushStr(cmds: number[], s: string) {
  for (const c of s) {
cmds.push(c.charCodeAt(0));
}
}
function pushLine(cmds: number[], s: string) {
  pushStr(cmds, s);
  cmds.push(0x0a); // LF
}

function buildEscPosBuffer(
  type: string,
  text: string,
  lines?: string[],
): Buffer {
  const ESC = 0x1b;
  const GS = 0x1d;
  const LF = 0x0a;
  const cmds: number[] = [];

  cmds.push(ESC, 0x40); // ESC @ ΓÇö initialize printer

  if (type === "kot") {
    // ΓöÇΓöÇ KOT: if structured directives provided, use same pipeline as receipt ΓöÇΓöÇ
    if (lines && lines.length > 0) {
      // Re-use the receipt directive parser ΓÇö identical ESC/POS handling
      const SEP_A = "------------------------------------------"; // 42 dashes ΓÇö full Font A line
      cmds.push(ESC, 0x40); // re-init
      cmds.push(ESC, 0x4d, 0x00); // Font A throughout

      for (const directive of lines) {
        if (directive === "SEP" || directive === "SEPB") {
          cmds.push(ESC, 0x4d, 0x00);
          cmds.push(ESC, 0x61, 0x00);
          pushLine(cmds, SEP_A);
        } else if (directive === "BLANK") {
          cmds.push(LF);
        } else if (directive === "CUT") {
          cmds.push(LF, LF);
          cmds.push(GS, 0x56, 0x41, 0x00);
        } else if (directive.startsWith("BIGBOLD:")) {
          cmds.push(ESC, 0x4d, 0x00);
          cmds.push(ESC, 0x61, 0x01); // center
          cmds.push(GS, 0x21, 0x01); // double height
          cmds.push(ESC, 0x45, 0x01); // bold on
          pushLine(cmds, directive.slice(8));
          cmds.push(ESC, 0x45, 0x00);
          cmds.push(GS, 0x21, 0x00);
        } else if (directive.startsWith("SUBHEADER:")) {
          cmds.push(ESC, 0x4d, 0x00);
          cmds.push(ESC, 0x61, 0x01); // center
          cmds.push(ESC, 0x45, 0x01); // bold on
          pushLine(cmds, directive.slice(10));
          cmds.push(ESC, 0x45, 0x00);
        } else if (directive.startsWith("CENTER:")) {
          cmds.push(ESC, 0x4d, 0x00);
          cmds.push(ESC, 0x61, 0x01);
          pushLine(cmds, directive.slice(7));
        } else if (directive.startsWith("LEFTDH:")) {
          // LEFT double-height (bold) for KOT items ΓÇö slightly smaller than hotel name
          cmds.push(ESC, 0x4d, 0x00); // Font A
          cmds.push(ESC, 0x61, 0x00); // left
          cmds.push(GS, 0x21, 0x01); // double height only (same level as BIGBOLD, no width doubling)
          cmds.push(ESC, 0x45, 0x01); // bold on for readability
          pushLine(cmds, directive.slice(7));
          cmds.push(ESC, 0x45, 0x00); // bold off
          cmds.push(GS, 0x21, 0x00); // normal size
        } else if (
          directive.startsWith("LEFT:") ||
          directive.startsWith("LEFTB:")
        ) {
          cmds.push(ESC, 0x4d, 0x00);
          cmds.push(ESC, 0x61, 0x00);
          const content = directive.startsWith("LEFT:")
            ? directive.slice(5)
            : directive.slice(6);
          pushLine(cmds, content);
        } else if (directive.startsWith("BOLDLEFT:")) {
          cmds.push(ESC, 0x4d, 0x00);
          cmds.push(ESC, 0x61, 0x00);
          cmds.push(ESC, 0x45, 0x01);
          pushLine(cmds, directive.slice(9));
          cmds.push(ESC, 0x45, 0x00);
        } else {
          cmds.push(ESC, 0x4d, 0x00);
          cmds.push(ESC, 0x61, 0x00);
          pushLine(cmds, directive);
        }
      }
    } else {
      // ΓöÇΓöÇ KOT fallback: plain text body ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      cmds.push(ESC, 0x4d, 0x00); // Font A
      cmds.push(ESC, 0x61, 0x01); // center
      cmds.push(GS, 0x21, 0x01); // double height
      cmds.push(ESC, 0x45, 0x01); // bold on
      pushLine(cmds, "HOTEL GURUKRUPA");
      cmds.push(ESC, 0x45, 0x00);
      cmds.push(GS, 0x21, 0x00);
      cmds.push(ESC, 0x45, 0x01);
      pushLine(cmds, "------ KOT ------");
      cmds.push(ESC, 0x45, 0x00);
      cmds.push(ESC, 0x61, 0x00); // left align
      for (const line of text.split(/\r?\n/)) {
        pushLine(cmds, line);
      }
      cmds.push(LF, LF);
      cmds.push(GS, 0x56, 0x41, 0x00);
    }
  } else if (type === "receipt" && lines && lines.length > 0) {
    // ΓöÇΓöÇ Structured receipt using pre-built ESC/POS line directives ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    // Directives:
    //   BIGBOLD:<t>   ΓåÆ Font A, double-height, bold, centered  (hotel name ~18-24pt)
    //   SUBHEADER:<t> ΓåÆ Font A, bold, centered                 (DINE-IN label ~12-14pt)
    //   CENTER:<t>    ΓåÆ Font A, normal, centered               (mob/email lines ~10-12pt)
    //   LEFT:<t>      ΓåÆ Font A, normal, left                   (order meta ~10-12pt)
    //   LEFTB:<t>     ΓåÆ Font B, normal, left                   (item rows/totals ~7-9pt)
    //   CENTERB:<t>   ΓåÆ Font B, normal, centered               (footer centered lines)
    //   BOLDLEFT:<t>  ΓåÆ Font A, bold, left                     (grand total bold)
    //   SEPB          ΓåÆ Font B separator (42 dashes)
    //   SEP           ΓåÆ Font A separator (48 dashes)
    //   BLANK         ΓåÆ single blank line
    //   CUT           ΓåÆ 2 feed lines + full cut

    // 80mm paper character widths (measured at standard print density):
    //   Font A (12├ù24 dots) Γëê 42 chars/line
    //   Font B (9├ù17 dots)  Γëê 56 chars/line
    // We use Font A for everything (bigger, easier to read) and pad content
    // with 1 space on each side so it isn't flush against the paper edge.
    // Separators use 42 dashes = full Font A line width.
    const SEP_A = "------------------------------------------"; // 42 dashes ΓÇö full Font A line

    cmds.push(ESC, 0x40); // ESC @ ΓÇö re-init
    cmds.push(ESC, 0x4d, 0x00); // Font A throughout

    for (const directive of lines) {
      if (directive === "SEP" || directive === "SEPB") {
        // Full-width separator in Font A
        cmds.push(ESC, 0x4d, 0x00); // Font A
        cmds.push(ESC, 0x61, 0x00); // left
        pushLine(cmds, SEP_A);
      } else if (directive === "BLANK") {
        cmds.push(LF);
      } else if (directive === "CUT") {
        cmds.push(LF, LF);
        cmds.push(GS, 0x56, 0x41, 0x00); // full cut
      } else if (directive.startsWith("BIGBOLD:")) {
        // Hotel name: Font A, double-height bold, centered (~18-24pt feel)
        cmds.push(ESC, 0x4d, 0x00); // Font A
        cmds.push(ESC, 0x61, 0x01); // center
        cmds.push(GS, 0x21, 0x01); // double height only (keeps 42-char width)
        cmds.push(ESC, 0x45, 0x01); // bold on
        pushLine(cmds, directive.slice(8));
        cmds.push(ESC, 0x45, 0x00); // bold off
        cmds.push(GS, 0x21, 0x00); // normal size
      } else if (directive.startsWith("SUBHEADER:")) {
        // DINE-IN / TAKEAWAY / DELIVERY: Font A bold centered (~12-14pt)
        cmds.push(ESC, 0x4d, 0x00); // Font A
        cmds.push(ESC, 0x61, 0x01); // center
        cmds.push(ESC, 0x45, 0x01); // bold on
        pushLine(cmds, directive.slice(10));
        cmds.push(ESC, 0x45, 0x00); // bold off
      } else if (directive.startsWith("CENTER:")) {
        // Font A normal centered (mob, email, table no)
        cmds.push(ESC, 0x4d, 0x00); // Font A
        cmds.push(ESC, 0x61, 0x01); // center
        pushLine(cmds, directive.slice(7));
      } else if (directive.startsWith("LEFT:")) {
        // Font A normal left (order meta, column header, item rows, totals, footer)
        cmds.push(ESC, 0x4d, 0x00); // Font A
        cmds.push(ESC, 0x61, 0x00); // left
        pushLine(cmds, directive.slice(5));
      } else if (directive.startsWith("LEFTDH:")) {
        // LEFT double-height bold for KOT items ΓÇö slightly smaller than hotel name (no width doubling)
        cmds.push(ESC, 0x4d, 0x00);
        cmds.push(ESC, 0x61, 0x00);
        cmds.push(GS, 0x21, 0x01); // double height only
        cmds.push(ESC, 0x45, 0x01); // bold on
        pushLine(cmds, directive.slice(7));
        cmds.push(ESC, 0x45, 0x00); // bold off
        cmds.push(GS, 0x21, 0x00); // normal size
      } else if (directive.startsWith("LEFTB:")) {
        // Treated same as LEFT ΓÇö Font A left (font "B" distinction removed, size bumped up)
        cmds.push(ESC, 0x4d, 0x00); // Font A
        cmds.push(ESC, 0x61, 0x00); // left
        pushLine(cmds, directive.slice(6));
      } else if (directive.startsWith("CENTERB:")) {
        // Treated same as CENTER ΓÇö Font A centered
        cmds.push(ESC, 0x4d, 0x00); // Font A
        cmds.push(ESC, 0x61, 0x01); // center
        pushLine(cmds, directive.slice(8));
      } else if (directive.startsWith("BOLDLEFT:")) {
        // Font A bold left (grand total)
        cmds.push(ESC, 0x4d, 0x00); // Font A
        cmds.push(ESC, 0x61, 0x00); // left
        cmds.push(ESC, 0x45, 0x01); // bold on
        pushLine(cmds, directive.slice(9));
        cmds.push(ESC, 0x45, 0x00); // bold off
      } else if (directive.startsWith("BOLD:")) {
        // Font A bold centered
        cmds.push(ESC, 0x4d, 0x00); // Font A
        cmds.push(ESC, 0x61, 0x01); // center
        cmds.push(ESC, 0x45, 0x01); // bold on
        pushLine(cmds, directive.slice(5));
        cmds.push(ESC, 0x45, 0x00); // bold off
      } else {
        // plain fallback: Font A left
        cmds.push(ESC, 0x4d, 0x00);
        cmds.push(ESC, 0x61, 0x00);
        pushLine(cmds, directive);
      }
    }
  } else {
    // ΓöÇΓöÇ Fallback plain receipt ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    cmds.push(ESC, 0x61, 0x01); // center
    cmds.push(GS, 0x21, 0x11); // double width + height
    cmds.push(ESC, 0x45, 0x01); // bold on
    pushLine(cmds, "HOTEL GURUKRUPA");
    cmds.push(GS, 0x21, 0x00); // normal size
    cmds.push(ESC, 0x45, 0x00); // bold off
    pushLine(cmds, "RECEIPT");
    pushLine(cmds, "------------------------");
    cmds.push(ESC, 0x61, 0x00);
    for (const line of text.split(/\r?\n/)) {
      pushLine(cmds, line);
    }
    cmds.push(LF, LF, LF);
    cmds.push(GS, 0x56, 0x41, 0x00);
  }

  return Buffer.from(cmds);
}

function printViaWindowsRaw(
  printerName: string,
  escPosBuffer: Buffer,
): Promise<void> {
  return new Promise<void>((resolve, reject) => {
    const { exec } = require("child_process");
    const fs = require("fs");
    const os = require("os");
    const pathMod = require("path");

    // Step 1 ΓÇö list installed printers so we can confirm the name is correct.
    const listCmd = `powershell -NoProfile -Command "Get-Printer | Select-Object -ExpandProperty Name | ConvertTo-Json -Compress"`;
    console.log("[WIN-RAW] Listing installed Windows printers...");

    exec(listCmd, { timeout: 10000 }, (listErr: any, listStdout: string) => {
      if (listErr) {
        console.warn("[WIN-RAW] Could not list printers:", listErr.message);
      } else {
        try {
          const parsed = JSON.parse(listStdout.trim());
          const names: string[] = Array.isArray(parsed) ? parsed : [parsed];
          console.log("[WIN-RAW] Listed printers:", names);
          const match = names.find(
            (n) => n.toLowerCase() === printerName.toLowerCase(),
          );
          if (!match) {
            console.warn(
              `[WIN-RAW] WARNING: printer "${printerName}" not found in list. ` +
                `Available: ${names.join(", ")}. ` +
                `Set KITCHEN_PRINTER_USB_NAME env var to the exact name shown above.`,
            );
          } else {
            console.log(
              `[WIN-RAW] Printer "${match}" confirmed in Windows printer list.`,
            );
          }
        } catch (_e) {
          console.warn(
            "[WIN-RAW] Could not parse printer list:",
            listStdout.trim(),
          );
        }
      }

      // Step 2 ΓÇö write the ESC/POS bytes to a temp binary file.
      const tempFile = pathMod.join(os.tmpdir(), `pos_raw_${Date.now()}.bin`);
      try {
        fs.writeFileSync(tempFile, escPosBuffer);
        console.log(
          `[WIN-RAW] ESC/POS buffer written: ${tempFile} (${escPosBuffer.length} bytes)`,
        );
      } catch (writeErr: any) {
        console.error("[WIN-RAW] Failed to write temp file:", writeErr.message);
        return reject(writeErr);
      }

      // Step 3 ΓÇö send via `copy /b`.
      // This is the simplest raw-bytes-to-spooler method on Windows.
      // If printerName is not already a UNC path, route it through localhost.
      const makeWindowsPrinterPath = (name: string) => {
        const p = name.trim().replace(/^"|"$/g, "");
        if (p.startsWith("\\\\")) {
return p;
}
        if (/^(PRN|LPT[1-9]|COM[1-9])$/i.test(p)) {
return p;
}
        return `\\\\127.0.0.1\\${p}`;
      };
      const printerPath = makeWindowsPrinterPath(printerName);
      console.log(`[WIN-RAW] Target printer path: ${printerPath}`);
      const cmd = `copy /b "${tempFile}" "${printerPath}"`;
      console.log(`[WIN-RAW] Running: ${cmd}`);

      exec(
        cmd,
        { timeout: 15000 },
        (err: any, stdout: string, stderr: string) => {
          try {
            fs.unlinkSync(tempFile);
          } catch (_e) {
            /* ignore cleanup */
          }

          if (err) {
            console.error(`[WIN-RAW] FAILED: ${err.message}`);
            if (stderr) {
console.error(`[WIN-RAW] stderr: ${stderr.trim()}`);
}
            return reject(
              new Error(`Windows RAW print failed: ${err.message}`),
            );
          }

          console.log(
            `[WIN-RAW] copy /b succeeded. stdout: "${stdout.trim()}" Γ£à`,
          );
          resolve();
        },
      );
    });
  });
}

function writeBufferWithTimeout(socket: any, buffer: Buffer, timeoutMs = 5000) {
  return new Promise<void>((resolve, reject) => {
    let timedOut = false;
    const to = setTimeout(() => {
      timedOut = true;
      try {
        socket.destroy();
      } catch (e) {}
      reject(new Error("write-timeout"));
    }, timeoutMs);

    socket.write(buffer, (err: any) => {
      clearTimeout(to);
      if (timedOut) {
return;
} // already rejected
      if (err) {
return reject(err);
}
      resolve();
    });
  });
}

// Printer IPC: use ESC/POS (USB) for POS-80C
//
// LOG GUIDANCE ΓÇö open Electron DevTools (or run with --enable-logging) and watch for:
//
//  [PRINT] payload received         ΓåÆ confirms IPC call reached main process
//  [PRINT] attempting ESC/POS USB   ΓåÆ libusb path starting
//  [USB]   usb module loaded        ΓåÆ usb native module is available
//  [USB]   EventEmitter patched     ΓåÆ usb module needed the EventEmitter shim
//  [USB]   escpos-usb loaded        ΓåÆ escpos-usb module is available
//  [USB]   findPrinter found N      ΓåÆ N = number of USB printers seen by libusb
//                                     If 0 ΓåÆ printer not visible to libusb
//                                       ΓåÆ either needs Zadig WinUSB driver, OR
//                                       ΓåÆ use the Windows RAW path below instead
//  [USB]   VID / PID logged         ΓåÆ confirms which device was picked
//  [USB]   device.open() OK         ΓåÆ libusb successfully claimed the USB interface
//  [USB]   ESC/POS bytes sent       ΓåÆ print job delivered via libusb
//  [USB]   FAILED: ...              ΓåÆ libusb path failed, see error detail
//    LIBUSB_ERROR_NOT_SUPPORTED      ΓåÆ device driver is not WinUSB/libusb compatible
//                                     Option A: use Zadig to replace driver with WinUSB
//                                     Option B: rely on [WIN-RAW] path (no driver change)
//    LIBUSB_ERROR_ACCESS             ΓåÆ driver present but access denied (run as admin?)
//
//  [WIN-RAW] Listed printers: [..] ΓåÆ shows all Windows printer names
//                                    Use the exact name shown here as KITCHEN_PRINTER_USB_NAME
//  [WIN-RAW] printer confirmed      ΓåÆ name matched ΓÇö RAW path should succeed
//  [WIN-RAW] WARNING: not found     ΓåÆ printer name mismatch ΓÇö update env var
//  [WIN-RAW] Sending raw ESC/POS    ΓåÆ RAW winspool path starting
//  [WIN-RAW] Raw print succeeded    ΓåÆ ESC/POS bytes accepted by spooler Γ£à
//  [WIN-RAW] FAILED: ...            ΓåÆ spooler rejected ΓÇö check printer name / port
//
ipcMain.handle("printer:print", async (event, payload) => {
  console.log(
    "[PRINT] printer:print IPC received. payload type:",
    payload?.type,
    "| printer:",
    payload?.printer,
  );

  try {
    const { type, data } = payload || {};
    const cfg = await getPrinterConfig();
    const printerName = payload?.printer || cfg.usbPrinterName || "POS-80C";
    const text = data?.text || (type === "kot" ? "KOT Print" : "Receipt Print");
    // structured receipt lines (array of directive strings like "CENTER:...", "LEFT:...", etc.)
    const receiptLines: string[] | undefined = data?.lines;

    console.log(
      `[PRINT] printerName="${printerName}", type="${type}", text length=${text.length}`,
    );

    // ΓöÇΓöÇ Path 1: ESC/POS via libusb (escpos-usb) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    console.log("[PRINT] attempting ESC/POS USB path (libusb / escpos-usb)...");
    try {
       
      const escpos = require("escpos");
      console.log("[USB] escpos module loaded");

      // Patch usb module with EventEmitter BEFORE requiring escpos-usb,
      // so escpos-usb detach listeners don't throw "usb.on is not a function".
       
      const usbModule = require("usb");
      console.log(
        "[USB] usb module loaded. Has .on:",
        typeof usbModule.on === "function",
      );

      if (typeof usbModule.on !== "function") {
        const EventEmitter = require("events");
        const usbEvents = new EventEmitter();
        usbModule.on = usbEvents.on.bind(usbEvents);
        usbModule.once = usbEvents.once.bind(usbEvents);
        usbModule.emit = usbEvents.emit.bind(usbEvents);
        usbModule.removeAllListeners =
          usbEvents.removeAllListeners.bind(usbEvents);
        usbModule.removeListener = usbEvents.removeListener.bind(usbEvents);
        console.log("[USB] EventEmitter shim applied to usb module");
      }

       
      const escposUsb = require("escpos-usb");
      console.log("[USB] escpos-usb module loaded");
      escpos.USB = escposUsb;

      const available = escposUsb.findPrinter();
      console.log(
        `[USB] findPrinter() found ${available?.length ?? 0} device(s)`,
      );

      if (!available || available.length === 0) {
        const usbDiag = getUsbDeviceDiagnostics();
        console.warn(
          "[USB] No ESC/POS printers found via libusb. Full USB device list:",
          JSON.stringify(usbDiag, null, 2),
        );
        console.warn(
          "[USB] ΓåÆ If your printer appears in the USB list above but not here,",
        );
        console.warn("[USB]   its driver is not libusb-compatible. Either:");
        console.warn(
          "[USB]   A) Replace driver with WinUSB via Zadig (https://zadig.akeo.ie)",
        );
        console.warn(
          "[USB]   B) Skip this path ΓÇö the Windows RAW path will handle it.",
        );
        throw new Error("escpos-usb findPrinter returned empty");
      }

      const rawDevice: any = available[0];
      const vid: number | undefined = rawDevice?.deviceDescriptor?.idVendor;
      const pid: number | undefined = rawDevice?.deviceDescriptor?.idProduct;
      console.log(
        `[USB] Using device ΓÇö VID: 0x${vid?.toString(
          16,
        )}, PID: 0x${pid?.toString(16)}`,
      );

      const device = vid && pid ? new escpos.USB(vid, pid) : new escpos.USB();
      const printer = new escpos.Printer(device);

      await new Promise<void>((resolve, reject) => {
        device.open((err: any) => {
          if (err) {
            console.error("[USB] device.open() FAILED:", err.message ?? err);
            if (
              err.errno === -12 ||
              (err.message &&
                err.message.includes("LIBUSB_ERROR_NOT_SUPPORTED"))
            ) {
              console.error(
                "[USB] LIBUSB_ERROR_NOT_SUPPORTED: Windows driver is not WinUSB/libusb compatible.",
              );
              console.error(
                "[USB] ΓåÆ Option A: run Zadig, select POS-80C, install WinUSB driver.",
              );
              console.error(
                "[USB] ΓåÆ Option B: use Windows RAW path (no driver change needed).",
              );
            }
            return reject(err);
          }
          console.log("[USB] device.open() OK ΓÇö sending ESC/POS bytes...");
          try {
            if (type === "kot" && receiptLines && receiptLines.length > 0) {
              // KOT: structured directives ΓÇö same raw-buffer path as receipt
              try {
                const buf = buildEscPosBuffer("kot", text, receiptLines);
                printer.raw(buf).close(() => {
                  console.log("[USB] KOT sent via raw buffer. Γ£à");
                  resolve();
                });
                return;
              } catch (apiErr: any) {
                console.warn(
                  "[USB] escpos.Printer.raw failed for KOT:",
                  apiErr && apiErr.message ? apiErr.message : String(apiErr),
                );
                return reject(apiErr);
              }
            } else if (
              type === "receipt" &&
              receiptLines &&
              receiptLines.length > 0
            ) {
              // Structured receipt ΓÇö prefer using escpos.Printer API (same as KOT)
              // escpos-usb Printer uses chainable API; font switching done via raw bytes
              // injected with .raw() or by falling back to buildEscPosBuffer.
              // We use the raw-buffer path here for reliable font/size control.
              try {
                const buf = buildEscPosBuffer("receipt", text, receiptLines);
                // printer.raw(buffer, cb) sends pre-built ESC/POS bytes, then close device
                printer.raw(buf).close(() => {
                  console.log(
                    "[USB] Structured receipt sent via raw buffer. Γ£à",
                  );
                  resolve();
                });
                return;
              } catch (apiErr: any) {
                console.warn(
                  "[USB] escpos.Printer API failed for structured receipt:",
                  apiErr && apiErr.message ? apiErr.message : String(apiErr),
                );
                // fallback: try raw buffer transfer as last resort
                try {
                  const buf = buildEscPosBuffer("receipt", text, receiptLines);
                  device._device.open();
                  const iface = device._device.interfaces[0];
                  iface.claim();
                  const endpoint = iface.endpoints.find(
                    (ep: any) => ep.direction === "out",
                  );
                  if (!endpoint) {
throw new Error("no-out-endpoint");
}
                  endpoint.transfer(buf, (err2: any) => {
                    try {
                      iface.release(true, () => {});
                    } catch (_) {}
                    try {
                      device._device.close();
                    } catch (_) {}
                    if (err2) {
return reject(err2);
}
                    console.log(
                      "[USB] Structured receipt sent via raw transfer. Γ£à",
                    );
                    resolve();
                  });
                  return;
                } catch (rawErr: any) {
                  console.error(
                    "[USB] Raw transfer fallback failed:",
                    rawErr && rawErr.message ? rawErr.message : String(rawErr),
                  );
                  return reject(rawErr);
                }
              }
            } else {
              // Fallback plain receipt via printer API
              printer
                .align("CT")
                .style("B")
                .size(1, 1)
                .text("HOTEL GURUKRUPA")
                .style("NORMAL")
                .text("RECEIPT")
                .text("------------------------")
                .align("LT")
                .text(text)
                .feed(3)
                .cut()
                .close(() => {
                  console.log("[USB] ESC/POS bytes sent and device closed. Γ£à");
                  resolve();
                });
            }
          } catch (e) {
            reject(e);
          }
        });
      });

      console.log("[PRINT] ESC/POS USB path succeeded.");
      return { ok: true };
    } catch (usbErr: any) {
      console.warn(
        `[PRINT] ESC/POS USB path failed: ${usbErr.message ?? usbErr}`,
      );
      console.warn("[PRINT] Falling back to Windows RAW spooler path...");

      // ΓöÇΓöÇ Path 2: Windows RAW spooler (winspool + P/Invoke) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      // This path uses the manufacturer's installed driver via the Windows print
      // spooler with RAW datatype ΓÇö ESC/POS bytes go straight to the firmware.
      // No Zadig or driver replacement needed. Works as long as the printer is
      // installed in Windows (visible in Settings ΓåÆ Printers & Scanners).
      try {
        const escPosBuffer = buildEscPosBuffer(type, text, receiptLines);
        console.log(
          `[PRINT] Built ESC/POS buffer: ${escPosBuffer.length} bytes`,
        );
        await printViaWindowsRaw(printerName, escPosBuffer);
        console.log("[PRINT] Windows RAW path succeeded. Γ£à");
        return { ok: true };
      } catch (rawErr: any) {
        console.error(
          `[PRINT] Windows RAW path also failed: ${rawErr.message ?? rawErr}`,
        );
        return {
          ok: false,
          error:
            `Both print paths failed.\n` +
            `ESC/POS USB: ${usbErr.message}\n` +
            `Windows RAW: ${rawErr.message}\n\n` +
            `Check the Electron console for [USB] and [WIN-RAW] log lines to diagnose.`,
        };
      }
    }
  } catch (err: any) {
    console.error("[PRINT] Unexpected error in print handler:", err);
    return { ok: false, error: (err && err.message) || String(err) };
  }
});

