import { verifyUser, getUserByUsername } from "../db/pouch";

export type Session = {
  username: string;
  role: "admin" | "cashier";
  displayName?: string;
  sessionStart: number;
};

const SESSION_KEY = "pos-session";
const INACTIVITY_MS = 30 * 60 * 1000; // 30 minutes

export function setSession(sess: Session) {
  try {
    window.localStorage.setItem(SESSION_KEY, JSON.stringify(sess));
  } catch (e) {}
}

export function clearSession() {
  try {
    window.localStorage.removeItem(SESSION_KEY);
  } catch (e) {}
}

export function getSession(): Session | null {
  try {
    const raw = window.localStorage.getItem(SESSION_KEY);
    if (!raw) {
return null;
}
    const parsed = JSON.parse(raw) as Session;
    // simple inactivity check
    if (Date.now() - (parsed.sessionStart || 0) > INACTIVITY_MS) {
      clearSession();
      return null;
    }
    return parsed;
  } catch (e) {
    return null;
  }
}

export async function login(
  username: string,
  password: string,
): Promise<{
  ok: boolean;
  user?: { username: string; role: string; displayName?: string };
}> {
  const res = await verifyUser(username, password);
  if (!res.ok || !res.user) {
return { ok: false };
}
  const user = res.user;
  const sess: Session = {
    username: user.username,
    role: user.role,
    displayName: user.displayName,
    sessionStart: Date.now(),
  };
  setSession(sess);
  return {
    ok: true,
    user: {
      username: user.username,
      role: user.role,
      displayName: user.displayName,
    },
  };
}

export function logout() {
  clearSession();
}

export async function refreshSession() {
  // Reload session from storage and verify user still exists/active
  const s = getSession();
  if (!s) {
return null;
}
  const u = await getUserByUsername(s.username);
  if (!u || !u.active) {
    clearSession();
    return null;
  }
  // extend sessionStart to now (activity)
  const newSess: Session = { ...s, sessionStart: Date.now() };
  setSession(newSess);
  return newSess;
}

// @ts-ignore
import PouchDB from "pouchdb-browser";
// @ts-ignore
import pouchdbAdapterIdb from "pouchdb-adapter-idb";
// @ts-ignore
import pouchdbFind from "pouchdb-find";
// @ts-ignore
import { v4 as uuidv4 } from "uuid";
import { Logger } from "../utils/logger";
import { OrderValidator } from "../utils/validators";
import { handleError, DatabaseError } from "../utils/errors";

const logger = new Logger("PouchDB");

PouchDB.plugin(pouchdbAdapterIdb as any);
PouchDB.plugin(pouchdbFind as any);

export const db = new PouchDB("restaurant-db");

// simple wrapper examples
export async function putDoc(doc: any) {
  return db.put(doc);
}

export async function getDoc(id: string) {
  return db.get(id);
}

// --- Table & Order helpers ---
export type TableDoc = {
  _id: string; // e.g. table:1
  type: "table";
  id: number;
  seats: number;
  name?: string;
  order?: number; // explicit ordering for UI
};

export type OrderLine = { id: string; name: string; qty: number; rate: number };
/* Replaced OrderDoc with expanded schema to include orderType, kotPrinted, meta, discounts and createdBy. */
export type OrderDoc = {
  _id: string; // e.g. order:uuid
  type: "order";
  orderType: "table" | "takeaway" | "delivery";
  tableId: number | null;
  items: OrderLine[];
  status: "open" | "held" | "ready" | "assigned" | "paid" | "cancelled";
  meta?: {
    platform?: string | null;
    code?: string | null;
    customerName?: string | null;
    rider?: { name?: string | null; phone?: string | null } | null;
  };
  kotSent?: boolean;
  kotPrinted?: boolean;
  payments?: any[];
  discountPercent?: number;
  createdAt: number;
  updatedAt: number;
  createdBy?: string;
};

export async function seedTables(count: number = 12) {
  // check if tables exist
  const all = await db.allDocs({ include_docs: true });
  const found = all.rows.some((r: any) => r.doc && (r.doc as any).type === "table");
  if (found) {
return;
}

  const docs: TableDoc[] = Array.from({ length: count }).map((_, i) => ({
    _id: `table:${i + 1}`,
    type: "table",
    id: i + 1,
    seats: i % 4 === 0 ? 6 : 4,
    name: `Table ${i + 1}`,
    order: i + 1,
  }));

  await db.bulkDocs(docs as any);
}

export async function getTables(): Promise<TableDoc[]> {
  const all = await db.allDocs({ include_docs: true });
  const tables = all.rows
    .map((r: any) => r.doc as TableDoc | undefined)
    .filter((d: TableDoc | undefined): d is TableDoc => !!d && (d as any).type === "table");
  // sort by explicit order, fall back to id
  tables.sort((a: TableDoc, b: TableDoc) => (a.order ?? a.id) - (b.order ?? b.id));
  return tables;
}

export async function createOrderForTable(tableId: number | null): Promise<OrderDoc> {
  try {
    const id = `order:${uuidv4()}`;
    const now = Date.now();
    const orderType: OrderDoc["orderType"] = tableId !== null ? "table" : "takeaway";
    const order: OrderDoc = {
      _id: id,
      type: "order",
      orderType,
      tableId,
      items: [],
      status: "open",
      createdAt: now,
      updatedAt: now,
      payments: [],
      kotSent: false,
      kotPrinted: false,
      discountPercent: 0,
      createdBy: "cashier",
    };

    // Validate order before saving
    const validationErrors = OrderValidator.validate(order);
    if (validationErrors.length > 0) {
      logger.error("Order validation failed", { errors: validationErrors, order });
      throw new Error(
        `Order validation failed: ${validationErrors.map((e: any) => e.error).join(", ")}`,
      );
    }

    await db.put(order as any);
    const fresh = (await db.get(order._id)) as OrderDoc;
    logger.info("Order created", { orderId: fresh._id, orderType, tableId });

    // audit
    try {
      await createAudit("order.created", fresh._id, fresh.createdBy || null, {
        orderType: fresh.orderType,
        tableId: fresh.tableId,
      });
    } catch (e) {}
    return fresh;
  } catch (error) {
    const dbError = new DatabaseError("Failed to create order", { tableId }, error as Error);
    handleError(dbError);
    throw dbError;
  }
}

export async function getOpenOrderForTable(tableId: number): Promise<OrderDoc | null> {
  const all = await db.allDocs({ include_docs: true });
  const orders = all.rows
    .map((r: any) => r.doc)
    .filter((d: any): d is OrderDoc => !!d && (d as any).type === "order")
    .filter((d: any) => {
      // normalize types: tableId may be stored as number or string in older docs
      const tid = (d as any).tableId;
      if (tid === undefined || tid === null) {
return false;
}
      if (String(tid) !== String(tableId)) {
return false;
}
      return (d as any).status === "open";
    });
  return orders.length ? orders[0] : null;
}

export async function getOpenOrders(): Promise<OrderDoc[]> {
  const all = await db.allDocs({ include_docs: true });
  const orders = all.rows
    .map((r: any) => r.doc)
    .filter(
      (d: any): d is OrderDoc => !!d && (d as any).type === "order" && (d as any).status === "open",
    );
  return orders as OrderDoc[];
}

export async function getOrderById(id: string): Promise<OrderDoc | null> {
  try {
    const d = await db.get(id);
    return d as OrderDoc;
  } catch (e) {
    return null;
  }
}

export async function getOrCreateOrderForTable(tableId: number) {
  let order = await getOpenOrderForTable(tableId);
  if (order) {
return order;
}
  order = await createOrderForTable(tableId);
  return order;
}

export async function addItemToOrder(
  orderId: string,
  item: { name: string; qty: number; rate: number },
) {
  try {
    const order = (await getOrderById(orderId)) as OrderDoc | null;
    if (!order) {
      logger.warn("Order not found for item addition", { orderId });
      throw new Error("order-not-found");
    }

    const line = {
      id: uuidv4(),
      name: item.name,
      qty: item.qty,
      rate: item.rate,
    };
    order.items.push(line);
    order.updatedAt = Date.now();

    // Validate updated order
    const validationErrors = OrderValidator.validate(order);
    if (validationErrors.length > 0) {
      logger.error("Order validation failed after item addition", { errors: validationErrors });
      throw new Error("Order validation failed");
    }

    await db.put(order as any);
    // return fresh copy with updated _rev
    const fresh = (await db.get(order._id)) as OrderDoc;
    logger.info("Item added to order", { orderId, itemName: line.name, quantity: line.qty });

    try {
      await createAudit("item.added", fresh._id, fresh.createdBy || null, {
        item: line,
      });
    } catch (e) {}
    return fresh;
  } catch (error) {
    const dbError = new DatabaseError(
      "Failed to add item to order",
      { orderId, item },
      error as Error,
    );
    handleError(dbError);
    throw dbError;
  }
}

export async function updateOrder(order: OrderDoc) {
  try {
    order.updatedAt = Date.now();

    // Validate order before updating
    const validationErrors = OrderValidator.validate(order);
    if (validationErrors.length > 0) {
      logger.error("Order validation failed before update", {
        orderId: order._id,
        errors: validationErrors,
      });
      throw new Error("Order validation failed");
    }

    await db.put(order as any);
    const fresh = (await db.get(order._id)) as OrderDoc;
    logger.info("Order updated", { orderId: fresh._id, status: fresh.status });
    return fresh;
  } catch (error) {
    const dbError = new DatabaseError(
      "Failed to update order",
      { orderId: order._id },
      error as Error,
    );
    handleError(dbError);
    throw dbError;
  }
}

export async function setOrderPaid(orderId: string, payment: any) {
  try {
    const order = (await getOrderById(orderId)) as OrderDoc | null;
    if (!order) {
      logger.warn("Order not found for payment", { orderId });
      throw new Error("order-not-found");
    }

    order.status = "paid";
    order.payments = order.payments || [];
    order.payments.push({ ...payment, receivedAt: Date.now() });
    order.updatedAt = Date.now();

    // Validate order before marking as paid
    const validationErrors = OrderValidator.validate(order);
    if (validationErrors.length > 0) {
      logger.error("Order validation failed before payment", { errors: validationErrors });
      throw new Error("Order validation failed");
    }

    await db.put(order as any);
    const fresh = (await db.get(order._id)) as OrderDoc;
    logger.info("Order marked as paid", {
      orderId,
      amount: payment.amount,
      method: payment.method,
    });

    try {
      await createAudit("order.paid", fresh._id, fresh.createdBy || null, {
        payment,
      });
    } catch (e) {}
    return fresh;
  } catch (error) {
    const dbError = new DatabaseError(
      "Failed to mark order as paid",
      { orderId, payment },
      error as Error,
    );
    handleError(dbError);
    throw dbError;
  }
}

export async function cancelOrder(orderId: string) {
  try {
    const order = (await getOrderById(orderId)) as OrderDoc | null;
    if (!order) {
      logger.warn("Order not found for cancellation", { orderId });
      throw new Error("order-not-found");
    }

    order.status = "held";
    // mark cancelled for auditing
    (order as any).cancelled = true;
    order.updatedAt = Date.now();

    await db.put(order as any);
    const fresh = (await db.get(order._id)) as OrderDoc;
    logger.info("Order cancelled", { orderId });

    try {
      await createAudit("order.cancelled", fresh._id, fresh.createdBy || null, {});
    } catch (e) {}
    return fresh;
  } catch (error) {
    const dbError = new DatabaseError("Failed to cancel order", { orderId }, error as Error);
    handleError(dbError);
    throw dbError;
  }
}

// --- Item (Menu) helpers ---
export type ItemDoc = {
  _id: string; // e.g. item:burger
  type: "item";
  sku?: string; // optional id or SKU
  name: string;
  price: number;
  category?: string;
