/* ----------------------- User / Auth helpers (PBKDF2) ----------------------- */
export type UserDoc = {
  _id: string; // user:username
  type: "user";
  username: string;
  displayName: string;
  role: "admin" | "cashier";
  passwordHash: string; // hex
  salt: string; // hex
  hashAlgo: string; // PBKDF2-SHA256-100000
  createdAt: number;
  active?: boolean;
};

function bufferToHex(buf: ArrayBuffer | Uint8Array) {
  const bytes = new Uint8Array(buf as any);
  return Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

function hexToBuffer(hex: string) {
  const len = hex.length / 2;
  const arr = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    arr[i] = parseInt(hex.substr(i * 2, 2), 16);
  }
  return arr.buffer;
}

export async function pbkdf2Hash(password: string, saltHex: string) {
  const salt = hexToBuffer(saltHex);
  const enc = new TextEncoder();
  const keyMaterial = await (crypto as any).subtle.importKey(
    "raw",
    enc.encode(password),
    { name: "PBKDF2" },
    false,
    ["deriveBits"],
  );
  const derived = await (crypto as any).subtle.deriveBits(
    {
      name: "PBKDF2",
      salt: salt,
      iterations: 100000,
      hash: "SHA-256",
    },
    keyMaterial,
    256,
  );
  return bufferToHex(derived);
}

export async function generateSaltHex(): Promise<string> {
  const a = crypto.getRandomValues(new Uint8Array(16));
  return bufferToHex(a);
}

export async function createUser(
  username: string,
  password: string,
  role: "admin" | "cashier" = "cashier",
  displayName?: string,
): Promise<UserDoc> {
  const salt = await generateSaltHex();
  const hash = await pbkdf2Hash(password, salt);
  const doc: UserDoc = {
    _id: `user:${username}`,
    type: "user",
    username,
    displayName: displayName || username,
    role,
    passwordHash: hash,
    salt,
    hashAlgo: "PBKDF2-SHA256-100000",
    createdAt: Date.now(),
    active: true,
  };
  await db.put(doc as any);
  return (await db.get(doc._id)) as UserDoc;
}

