export async function verifyUser(
  username: string,
  password: string,
): Promise<{ ok: boolean; user?: UserDoc }> {
  const user = await getUserByUsername(username);
  if (!user) {
return { ok: false };
}
  const hash = await pbkdf2Hash(password, user.salt);
  if (hash === user.passwordHash) {
return { ok: true, user };
}
  return { ok: false };
}

