// --- Backup / Import / Reporting helpers ---

/**
 * Export the entire database (all docs with included docs) as a JSON string.
 * The caller can save this string to a file for backup.
 */
export async function exportBackup(): Promise<string> {
  const all = await db.allDocs({ include_docs: true });
  return JSON.stringify(all);
}

/**
 * Import a backup JSON (the same shape produced by exportBackup).
 * If `overwrite` is true, the function will first delete all existing docs
 * before inserting the provided docs. Imported docs will have any existing
 * `_rev` removed to let PouchDB create fresh revisions.
 *
 * NOTE: This is a best-effort restore. If you need an atomic/transactional
 * restore consider exporting to a new DB and swapping or using replication.
 */
export async function importBackup(
  json: string,
  opts: { overwrite?: boolean } = { overwrite: false },
) {
  const parsed = JSON.parse(json);
  // Support either the shape returned by allDocs (has .rows) or a raw array of docs
  const docs: any[] = Array.isArray(parsed)
    ? parsed
    : parsed && Array.isArray(parsed.rows)
    ? parsed.rows.map((r: any) => r.doc).filter(Boolean)
    : [];

  if (!docs.length) {
    throw new Error("no-docs-to-import");
  }

  if (opts.overwrite) {
    // delete all existing docs by marking them _deleted via bulkDocs
    const existing = await db.allDocs();
    if (existing.rows.length) {
      const deletions = existing.rows.map((r: any) => ({
        _id: r.id,
        _rev: r.value.rev,
        _deleted: true,
      }));
      await db.bulkDocs(deletions as any);
    }
  }

  // Remove any _rev fields from incoming docs to avoid revision conflicts
  const toInsert = docs.map((d: any) => {
    const copy = { ...d };
    delete copy._rev;
    return copy;
  });

  const res = await db.bulkDocs(toInsert as any);
  return res;
}

/**
 * Compute sales summary (total amount and number of paid orders) for a time range.
 * If no range is provided, defaults to today (local timezone).
 * It looks at `payments` pushed when orders were paid. It is permissive about
 * payment shape and will look for `amount`, `total` or `value` fields on payments.
 */
export async function getSalesSummary(opts?: {
  from?: number;
  to?: number;
}): Promise<{ total: number; orders: number; payments: number }> {
  const now = Date.now();
  // default to start of today -> end of today
  const startOfDay = new Date();
  startOfDay.setHours(0, 0, 0, 0);
  const endOfDay = new Date();
  endOfDay.setHours(23, 59, 59, 999);

  const from = opts?.from ?? startOfDay.getTime();
  const to = opts?.to ?? endOfDay.getTime();

  const all = await db.allDocs({ include_docs: true });
  const paidOrders = all.rows
    .map((r: any) => r.doc)
    .filter(
      (d: any) => !!d && d.type === "order" && (d.status === "paid" || d.status === "held"),
    ) as OrderDoc[];

  let total = 0;
  let ordersCount = 0;
  let paymentsCount = 0;

  for (const o of paidOrders) {
    // prefer payments' receivedAt, fall back to order.updatedAt
    const matches = (o.payments || []).filter((p: any) => {
      const t = p && (p.receivedAt || p.received_at || p.timestamp || o.updatedAt);
      return t >= from && t <= to;
    });

    if (matches.length) {
      ordersCount += 1;
      for (const p of matches) {
        paymentsCount += 1;
        const amt = (p && (p.amount ?? p.total ?? p.value)) || 0;
        total += Number(amt) || 0;
      }
    }
  }

  return { total, orders: ordersCount, payments: paymentsCount };
}

// Get payment breakdown by method (cash, upi, etc)
export async function getPaymentBreakdown(opts?: {
  from?: number;
  to?: number;
}): Promise<{ [method: string]: number }> {
  const startOfDay = new Date();
  startOfDay.setHours(0, 0, 0, 0);
  const endOfDay = new Date();
  endOfDay.setHours(23, 59, 59, 999);

  const from = opts?.from ?? startOfDay.getTime();
  const to = opts?.to ?? endOfDay.getTime();

  const all = await db.allDocs({ include_docs: true });
  const paidOrders = all.rows
    .map((r: any) => r.doc)
    .filter(
      (d: any) => !!d && d.type === "order" && (d.status === "paid" || d.status === "held"),
    ) as OrderDoc[];

  const breakdown: { [method: string]: number } = {};

  for (const o of paidOrders) {
    const matches = (o.payments || []).filter((p: any) => {
      const t = p && (p.receivedAt || p.received_at || p.timestamp || o.updatedAt);
      return t >= from && t <= to;
    });

    for (const p of matches) {
      const method = (p && p.method) || "other";
      const amt = (p && (p.amount ?? p.total ?? p.value)) || 0;
      breakdown[method] = (breakdown[method] || 0) + Number(amt);
    }
  }

  return breakdown;
}

