export async function getAudits(opts: { from?: number; to?: number; limit?: number } = {}) {
  const { from, to, limit = 10000 } = opts;
  // Ensure an index exists for the fields we query/sort on. createIndex is idempotent.
  try {
    await (db as any).createIndex({
      index: { fields: ["type", "timestamp", "action", "orderId", "user"] },
    });
  } catch (e) {
    // ignore index creation errors (best-effort)
  }

  const selector: any = { type: "audit" };
  const ts: any = {};
  if (from !== undefined) {
ts.$gte = from;
}
  if (to !== undefined) {
ts.$lte = to;
}
  if (Object.keys(ts).length) {
selector.timestamp = ts;
}

  const res = await (db as any).find({
    selector,
    sort: [{ timestamp: "desc" }],
    limit,
  });
  return (res.docs || []) as any[];
}

