/**
 * Audit Log Archival System
 * Archive and manage long-term audit history
 */

import { db as pouchDb } from "../db/pouch";
import { logger } from "../utils/logger";

export interface AuditArchive {
  _id: string;
  type: "audit-archive";
  startDate: number;
  endDate: number;
  count: number;
  archivedAt: number;
  compressed: boolean;
  fileSize: number;
}

const ARCHIVE_INDEX_DOC = "archive:index";
const RETENTION_DAYS = 90; // Archive logs older than 90 days

export class AuditArchiver {
  /**
   * Archive old audit logs
   */
  static async archiveOldLogs(retentionDays: number = RETENTION_DAYS) {
    try {
      const cutoffDate = Date.now() - retentionDays * 24 * 60 * 60 * 1000;

      logger.info("Starting audit log archival", { retentionDays, cutoffDate });

      // Get all audit logs older than cutoff
      const all = await (pouchDb as any).allDocs({ include_docs: true });
      const oldAudits = (all.rows || [])
        .map((r: any) => r.doc)
        .filter((d: any) => d && d.type === "audit" && (d.timestamp || d.createdAt) < cutoffDate);

      if (oldAudits.length === 0) {
        logger.info("No old audit logs to archive");
        return;
      }

      // Create archive record
      const archiveId = `archive:${Date.now()}`;
      const archive: AuditArchive = {
        _id: archiveId,
        type: "audit-archive",
        startDate: cutoffDate - 30 * 24 * 60 * 60 * 1000, // 30 days before cutoff
        endDate: cutoffDate,
        count: oldAudits.length,
        archivedAt: Date.now(),
        compressed: false,
        fileSize: JSON.stringify(oldAudits).length,
      };

      // Store archive reference
      await (pouchDb as any).put(archive);

      // Mark old audits as archived (add _archived flag)
      for (const audit of oldAudits) {
        audit._archived = true;
        audit.archiveId = archiveId;
        await (pouchDb as any).put(audit);
      }

      logger.info("Audit log archival completed", {
        archivedCount: oldAudits.length,
        archiveId,
      });

      return archive;
    } catch (e) {
      logger.error("Audit log archival failed", e as Error);
      throw e;
    }
  }

  /**
   * Export archived logs as JSON
   */
  static async exportArchive(archiveId: string): Promise<{ data: any[]; metadata: AuditArchive }> {
    try {
      const archive = await (pouchDb as any).get(archiveId);
      if (!archive || archive.type !== "audit-archive") {
        throw new Error(`Archive ${archiveId} not found`);
      }

      // Get all audits for this archive
      const all = await (pouchDb as any).allDocs({ include_docs: true });
      const archivedDocs = (all.rows || [])
        .map((r: any) => r.doc)
        .filter((d: any) => d && d.type === "audit" && d.archiveId === archiveId);

      logger.info("Exported archive", {
        archiveId,
        count: archivedDocs.length,
      });

      return {
        data: archivedDocs,
        metadata: archive as AuditArchive,
      };
    } catch (e) {
      logger.error("Archive export failed", e as Error);
      throw e;
    }
  }

  /**
   * Export archive as CSV for external analysis
   */
  static async exportArchiveAsCSV(archiveId: string): Promise<string> {
    try {
      const { data } = await this.exportArchive(archiveId);

      if (data.length === 0) {
        return "timestamp,action,userId,orderId,details\n";
      }

      const headers = ["timestamp", "action", "userId", "orderId", "details"];
      const rows = data.map((log: any) => [
        new Date(log.timestamp).toISOString(),
        log.action,
        log.userId || "",
        log.orderId || "",
        `"${(log.details || "").replace(/"/g, '""')}"`,
      ]);

      return [headers.join(","), ...rows.map((r) => r.join(","))].join("\n");
    } catch (e) {
      logger.error("CSV export failed", e as Error);
      throw e;
    }
  }

  /**
   * Get all archives
   */
  static async getArchives(): Promise<AuditArchive[]> {
    try {
      const all = await (pouchDb as any).allDocs({ include_docs: true });
      const archives = (all.rows || [])
        .map((r: any) => r.doc)
        .filter((d: any) => d && d.type === "audit-archive");

      return archives;
    } catch (e) {
      logger.error("Failed to get archives", e as Error);
      return [];
    }
  }

  /**
   * Get archive statistics
   */
  static async getArchiveStats(): Promise<{
    totalArchives: number;
    totalArchivedLogs: number;
    oldestArchive: number | null;
    newestArchive: number | null;
    totalSize: number;
  }> {
    try {
      const archives = await this.getArchives();

      return {
        totalArchives: archives.length,
        totalArchivedLogs: archives.reduce((sum, a) => sum + a.count, 0),
        oldestArchive: archives.length > 0 ? Math.min(...archives.map((a) => a.startDate)) : null,
        newestArchive: archives.length > 0 ? Math.max(...archives.map((a) => a.endDate)) : null,
        totalSize: archives.reduce((sum, a) => sum + a.fileSize, 0),
      };
    } catch (e) {
      logger.error("Failed to get archive stats", e as Error);
      return {
        totalArchives: 0,
        totalArchivedLogs: 0,
        oldestArchive: null,
        newestArchive: null,
        totalSize: 0,
      };
    }
  }

  /**
   * Cleanup old archives (older than 1 year)
   */
  static async cleanupOldArchives(ageMonths: number = 12) {
    try {
      const cutoffDate = Date.now() - ageMonths * 30 * 24 * 60 * 60 * 1000;
      const archives = await this.getArchives();

      const toDelete = archives.filter((a) => a.archivedAt < cutoffDate);

      for (const archive of toDelete) {
        await (pouchDb as any).remove(archive);
      }

      logger.info("Archive cleanup completed", {
        deletedCount: toDelete.length,
      });

      return toDelete.length;
    } catch (e) {
      logger.error("Archive cleanup failed", e as Error);
      throw e;
    }
  }
}

export default AuditArchiver;

/**
 * Crash Recovery System
 * Recovers unsaved cart state after unexpected app crashes
 */

interface CrashRecoveryState {
  currentOrderId?: string;
  currentTable?: number;
  cartItems: Array<{
    name: string;
    qty: number;
    rate: number;
  }>;
  timestamp: number;
  discountPercent: number;
  recovered: boolean;
}

const RECOVERY_KEY = "pos_crash_recovery";
const RECOVERY_VERSION = 1;

export class CrashRecovery {
  /**
   * Save current cart state before risky operations
   */
  static saveState(state: Omit<CrashRecoveryState, "timestamp" | "recovered">) {
    try {
      const recoveryState: CrashRecoveryState = {
        ...state,
        timestamp: Date.now(),
        recovered: false,
      };

      localStorage.setItem(RECOVERY_KEY, JSON.stringify(recoveryState));
    } catch (e) {
      console.warn("Failed to save crash recovery state", e);
    }
  }

  /**
   * Check if there's recoverable state after crash
   */
  static hasRecoverableState(): boolean {
    try {
      const stored = localStorage.getItem(RECOVERY_KEY);
      if (!stored) {
return false;
}

      const state = JSON.parse(stored) as CrashRecoveryState;
      // Only consider state recoverable if it's less than 1 hour old
      const ageMs = Date.now() - state.timestamp;
      const oneHourMs = 60 * 60 * 1000;

      return ageMs < oneHourMs && state.cartItems.length > 0;
    } catch (e) {
      return false;
    }
  }

  /**
   * Retrieve crash recovery state
   */
  static getRecoveryState(): CrashRecoveryState | null {
    try {
      const stored = localStorage.getItem(RECOVERY_KEY);
      if (!stored) {
return null;
}

      const state = JSON.parse(stored) as CrashRecoveryState;
      state.recovered = true;
      return state;
    } catch (e) {
      console.warn("Failed to retrieve crash recovery state", e);
      return null;
    }
  }

  /**
   * Clear recovery state (call after successful restoration)
   */
  static clearRecoveryState() {
    try {
      localStorage.removeItem(RECOVERY_KEY);
    } catch (e) {
      console.warn("Failed to clear crash recovery state", e);
    }
  }

  /**
   * Get recovery state age in seconds
   */
  static getRecoveryAge(): number | null {
    try {
      const stored = localStorage.getItem(RECOVERY_KEY);
      if (!stored) {
return null;
}

      const state = JSON.parse(stored) as CrashRecoveryState;
      const ageMs = Date.now() - state.timestamp;
      return Math.round(ageMs / 1000);
    } catch (e) {
      return null;
    }
  }

  /**
   * Export recovery state for support/debugging
   */
  static exportRecoveryState(): string {
    const state = this.getRecoveryState();
    if (!state) {
return "No recovery state available";
}

    return JSON.stringify(state, null, 2);
  }
}

export default CrashRecovery;

/**
 * Custom Error Classes for Production Error Handling
 */

export class PosError extends Error {
  code: string;
  severity: "low" | "medium" | "high" | "critical";
  recoverable: boolean;
  context: Record<string, any>;

  constructor(
    message: string,
    code: string,
    severity: "low" | "medium" | "high" | "critical" = "medium",
    recoverable: boolean = false,
    context: Record<string, any> = {},
  ) {
    super(message);
    this.name = "PosError";
    this.code = code;
    this.severity = severity;
    this.recoverable = recoverable;
    this.context = context;

    Object.setPrototypeOf(this, PosError.prototype);
  }

  toJSON() {
    return {
      name: this.name,
      message: this.message,
      code: this.code,
      severity: this.severity,
      recoverable: this.recoverable,
      context: this.context,
      stack: this.stack,
    };
  }
}

export class DatabaseError extends PosError {
  constructor(message: string, context: Record<string, any> = {}) {
    super(message, "DB_ERROR", "high", true, context);
    this.name = "DatabaseError";
    Object.setPrototypeOf(this, DatabaseError.prototype);
  }
}

export class PrinterError extends PosError {
  constructor(message: string, recoverable: boolean = true, context: Record<string, any> = {}) {
    super(message, "PRINTER_ERROR", "high", recoverable, context);
    this.name = "PrinterError";
    Object.setPrototypeOf(this, PrinterError.prototype);
  }
}

export class ValidationError extends PosError {
  constructor(message: string, context: Record<string, any> = {}) {
    super(message, "VALIDATION_ERROR", "low", false, context);
    this.name = "ValidationError";
    Object.setPrototypeOf(this, ValidationError.prototype);
  }
}

export class AuthenticationError extends PosError {
  constructor(message: string, context: Record<string, any> = {}) {
    super(message, "AUTH_ERROR", "high", false, context);
    this.name = "AuthenticationError";
    Object.setPrototypeOf(this, AuthenticationError.prototype);
  }
}

export class NetworkError extends PosError {
  constructor(message: string, recoverable: boolean = true, context: Record<string, any> = {}) {
    super(message, "NETWORK_ERROR", "medium", recoverable, context);
    this.name = "NetworkError";
    Object.setPrototypeOf(this, NetworkError.prototype);
  }
}

/**
 * Global error handler
 */
export function handleError(error: unknown): PosError {
  if (error instanceof PosError) {
    return error;
  }

  if (error instanceof Error) {
    return new PosError(error.message, "UNKNOWN_ERROR", "medium", true, {
      originalStack: error.stack,
    });
  }

  return new PosError(String(error), "UNKNOWN_ERROR", "medium", true);
}

/**
 * Error reporter for production
 */
export class ErrorReporter {
  private errors: PosError[] = [];
  private readonly maxCrashReports = 100;

  addError(error: PosError) {
    this.errors.push(error);

    if (this.errors.length > this.maxCrashReports) {
      this.errors = this.errors.slice(-this.maxCrashReports);
    }
  }

  getCriticalErrors(): PosError[] {
    return this.errors.filter((e) => e.severity === "critical" || e.severity === "high");
  }

  getErrors(): PosError[] {
    return [...this.errors];
  }

  exportErrors(): string {
    return JSON.stringify(this.errors, null, 2);
  }

  clear() {
    this.errors = [];
  }
}

export const errorReporter = new ErrorReporter();

/**
 * Production Logging System for Restaurant POS
 * Structured logging with file persistence for audit trail
 */

interface LogEntry {
  timestamp: string;
  level: "info" | "warn" | "error" | "debug";
  message: string;
  context?: Record<string, any>;
  stack?: string;
}

class Logger {
  private logs: LogEntry[] = [];
  private readonly MAX_MEMORY_LOGS = 1000;
  private readonly LOG_LEVEL_WEIGHT: Record<LogEntry["level"], number> = {
    debug: 0,
    info: 1,
    warn: 2,
    error: 3,
  };

  private currentLevel: LogEntry["level"] = "info";

  constructor(level: LogEntry["level"] = "info") {
    this.currentLevel = level;
  }

  /**
   * Log info message
   */
  info(message: string, context?: Record<string, any>) {
    this.log("info", message, context);
  }

  /**
   * Log warning message
   */
  warn(message: string, context?: Record<string, any>) {
    this.log("warn", message, context);
  }

  /**
   * Log error with stack trace
   */
  error(
    message: string,
    error?: Error | string,
    context?: Record<string, any>,
  ) {
    const stack = error instanceof Error ? error.stack : undefined;
    const errorMsg = error instanceof Error ? error.message : String(error);
    this.log("error", message, { ...context, errorMsg }, stack);
    console.error(`[ERROR] ${message}`, error);
  }

  /**
   * Log debug message
   */
  debug(message: string, context?: Record<string, any>) {
    this.log("debug", message, context);
  }

  /**
   * Internal log method
   */
  private log(
    level: LogEntry["level"],
    message: string,
    context?: Record<string, any>,
    stack?: string,
  ) {
    const entry: LogEntry = {
      timestamp: new Date().toISOString(),
      level,
      message,
      context: context || {},
      ...(stack && { stack }),
    };

    this.logs.push(entry);

    // Keep only recent logs in memory
    if (this.logs.length > this.MAX_MEMORY_LOGS) {
      this.logs = this.logs.slice(-this.MAX_MEMORY_LOGS);
    }

    // Also log to console in development if level meets threshold
    if (
      process.env.NODE_ENV !== "production" &&
      this.LOG_LEVEL_WEIGHT[level] >= this.LOG_LEVEL_WEIGHT[this.currentLevel]
    ) {
      const prefix = `[${level.toUpperCase()}]`;
      console.log(`${prefix} ${message}`, context || "");
    }
  }

  /**
   * Get recent logs with optional filtering
   */
  getRecentLogs(count: number = 50): LogEntry[] {
    return this.logs.slice(-count);
  }

  /**
   * Get logs by level
   */
  getLogsByLevel(level: LogEntry["level"]): LogEntry[] {
    return this.logs.filter((log) => log.level === level);
  }

  /**
   * Export logs as JSON
   */
  exportJSON(): string {
    return JSON.stringify(this.logs, null, 2);
  }

  /**
   * Export logs as CSV
   */
  exportCSV(): string {
    if (this.logs.length === 0) {
return "timestamp,level,message\n";
}

    const headers = ["timestamp", "level", "message", "context"];
    const rows = this.logs.map((log) => [
      log.timestamp,
      log.level,
      `"${log.message.replace(/"/g, '""')}"`,
      log.context ? `"${JSON.stringify(log.context).replace(/"/g, '""')}"` : "",
    ]);

    return [headers.join(","), ...rows.map((r) => r.join(","))].join("\n");
  }

  /**
   * Clear all logs
   */
  clear() {
    this.logs = [];
  }

  /**
   * Get log count
   */
  getCount(): number {
    return this.logs.length;
  }
}

// Export singleton instance
export const logger = new Logger(
  (process.env.LOG_LEVEL as LogEntry["level"]) || "info",
);

export default logger;
export type { LogEntry };

/**
 * Database Migration System for PouchDB
 * Handles schema versioning and migrations
 */

import { db as pouchDb } from "../db/pouch";
import { logger } from "../utils/logger";

export interface DBMigration {
  version: number;
  name: string;
  up: () => Promise<void>;
  down?: () => Promise<void>;
}

const MIGRATION_DOC_ID = "meta:db_version";

export class MigrationManager {
  private migrations: Map<number, DBMigration> = new Map();
  private currentVersion: number = 1;

  /**
   * Register a migration
   */
  registerMigration(migration: DBMigration) {
    this.migrations.set(migration.version, migration);
    if (migration.version > this.currentVersion) {
      this.currentVersion = migration.version;
    }
  }

  /**
   * Get current database version
   */
  async getCurrentVersion(): Promise<number> {
    try {
      const doc = await (pouchDb as any).get(MIGRATION_DOC_ID);
      return (doc as any).version || 1;
    } catch (e: any) {
      if (e.status === 404) {
return 1;
}
      throw e;
    }
  }

  /**
   * Save database version
   */
  private async setCurrentVersion(version: number) {
    try {
      const doc: any = { _id: MIGRATION_DOC_ID, version, updatedAt: Date.now() };
      try {
        const existing = await (pouchDb as any).get(MIGRATION_DOC_ID);
        doc._rev = existing._rev;
      } catch (e: any) {
        if (e.status !== 404) {
throw e;
}
      }
      await (pouchDb as any).put(doc);
    } catch (e) {
      logger.error("Failed to save DB version", e as Error);
      throw e;
    }
  }

  /**
   * Run pending migrations
   */
  async migrate() {
    try {
      const currentVersion = await this.getCurrentVersion();
      logger.info("Database migration started", {
        currentVersion,
        targetVersion: this.currentVersion,
      });

      if (currentVersion === this.currentVersion) {
        logger.info("Database is up to date");
        return;
      }

      if (currentVersion > this.currentVersion) {
        throw new Error(
          `Database version (${currentVersion}) is newer than app version (${this.currentVersion})`,
        );
      }

      // Run migrations in order
      for (let v = currentVersion + 1; v <= this.currentVersion; v++) {
        const migration = this.migrations.get(v);
        if (!migration) {
          logger.warn(`Migration ${v} not found, skipping`);
          continue;
        }

        try {
          logger.info(`Running migration: ${migration.name}`);
          await migration.up();
          await this.setCurrentVersion(v);
          logger.info(`Migration ${v} completed successfully`);
        } catch (e) {
          logger.error(`Migration ${v} failed`, e as Error, {
            migration: migration.name,
          });
          throw e;
        }
      }

      logger.info("All migrations completed successfully");
    } catch (e) {
      logger.error("Migration process failed", e as Error);
      throw e;
    }
  }

  /**
   * Rollback to previous version
   */
  async rollback() {
    try {
      const currentVersion = await this.getCurrentVersion();

      if (currentVersion === 1) {
        throw new Error("Cannot rollback from version 1");
      }

      const migration = this.migrations.get(currentVersion);
      if (!migration || !migration.down) {
        throw new Error(`Rollback not supported for migration v${currentVersion}`);
      }

      logger.info(`Rolling back from version ${currentVersion}`);
      await migration.down();
      await this.setCurrentVersion(currentVersion - 1);
      logger.info("Rollback completed");
    } catch (e) {
      logger.error("Rollback failed", e as Error);
      throw e;
    }
  }

  /**
   * Get migration history
   */
  async getMigrationHistory() {
    try {
      const currentVersion = await this.getCurrentVersion();
      const migrations = Array.from(this.migrations.values())
        .sort((a, b) => a.version - b.version)
        .map((m) => ({
          version: m.version,
          name: m.name,
          status: m.version <= currentVersion ? "completed" : "pending",
        }));

      return migrations;
    } catch (e) {
      logger.error("Failed to get migration history", e as Error);
      throw e;
    }
  }
}

