/**
 * Printer Offline Queue System
 * Store print jobs when printer is unavailable and retry on reconnect
 */

import { db as pouchDb } from "../db/pouch";
import { logger } from "../utils/logger";

export interface PrintJob {
  _id: string;
  type: "print-job";
  printerName: string;
  jobType: "receipt" | "kot" | "label";
  content: string | any;
  createdAt: number;
  retryCount: number;
  maxRetries: number;
  lastRetryAt?: number;
  status: "pending" | "completed" | "failed";
  error?: string;
}

export class PrinterOfflineQueue {
  private static readonly MAX_QUEUE_SIZE = 500;
  private static readonly MAX_RETRIES = 3;
  private static readonly RETRY_DELAY_MS = 5000;

  /**
   * Add a print job to queue
   */
  static async addPrintJob(
    printerName: string,
    jobType: PrintJob["jobType"],
    content: string | any,
    maxRetries: number = this.MAX_RETRIES,
  ): Promise<PrintJob> {
    try {
      const job: PrintJob = {
        _id: `print-job:${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        type: "print-job",
        printerName,
        jobType,
        content,
        createdAt: Date.now(),
        retryCount: 0,
        maxRetries,
        status: "pending",
      };

      await (pouchDb as any).put(job);

      logger.info("Print job queued", {
        jobId: job._id,
        printerName,
        jobType,
      });

      return job;
    } catch (e) {
      logger.error("Failed to queue print job", e as Error, {
        printerName,
        jobType,
      });
      throw e;
    }
  }

  /**
   * Get all pending print jobs
   */
  static async getPendingJobs(): Promise<PrintJob[]> {
    try {
      const all = await (pouchDb as any).allDocs({ include_docs: true });
      const jobs = (all.rows || [])
        .map((r: any) => r.doc)
        .filter((d: any) => d && d.type === "print-job" && d.status === "pending")
        .sort((a: any, b: any) => a.createdAt - b.createdAt);

      return jobs;
    } catch (e) {
      logger.error("Failed to get pending print jobs", e as Error);
      return [];
    }
  }

  /**
   * Get pending jobs for specific printer
   */
  static async getPendingJobsForPrinter(printerName: string): Promise<PrintJob[]> {
    try {
      const all = await (pouchDb as any).allDocs({ include_docs: true });
      const jobs = (all.rows || [])
        .map((r: any) => r.doc)
        .filter(
          (d: any) =>
            d && d.type === "print-job" && d.status === "pending" && d.printerName === printerName,
        )
        .sort((a: any, b: any) => a.createdAt - b.createdAt);

      return jobs;
    } catch (e) {
      logger.error("Failed to get printer jobs", e as Error, { printerName });
      return [];
    }
  }

  /**
   * Mark job as completed
   */
  static async markJobCompleted(jobId: string) {
    try {
      const job = await (pouchDb as any).get(jobId);
      if (job && job.type === "print-job") {
        job.status = "completed";
        job.completedAt = Date.now();
        await (pouchDb as any).put(job);

        logger.info("Print job completed", { jobId });
      }
    } catch (e) {
      logger.error("Failed to mark job completed", e as Error, { jobId });
    }
  }

  /**
   * Retry failed print job
   */
  static async retryPrintJob(jobId: string): Promise<boolean> {
    try {
      const job = await (pouchDb as any).get(jobId);

      if (!job || job.type !== "print-job" || job.retryCount >= job.maxRetries) {
        return false;
      }

      job.retryCount += 1;
      job.lastRetryAt = Date.now();

      if (job.retryCount >= job.maxRetries) {
        job.status = "failed";
        job.error = "Max retries exceeded";
      }

      await (pouchDb as any).put(job);

      logger.info("Print job retry queued", {
        jobId,
        retryCount: job.retryCount,
      });

      return job.status !== "failed";
    } catch (e) {
      logger.error("Failed to retry print job", e as Error, { jobId });
      return false;
    }
  }

  /**
   * Get queue statistics
   */
  static async getQueueStats(): Promise<{
    totalPending: number;
    totalCompleted: number;
    totalFailed: number;
    oldestPendingAge: number | null;
  }> {
    try {
      const all = await (pouchDb as any).allDocs({ include_docs: true });
      const jobs = (all.rows || [])
        .map((r: any) => r.doc)
        .filter((d: any) => d && d.type === "print-job");

      const pending = jobs.filter((j: any) => j.status === "pending");
      const completed = jobs.filter((j: any) => j.status === "completed");
      const failed = jobs.filter((j: any) => j.status === "failed");

      const oldestPending =
        pending.length > 0 ? Math.min(...pending.map((j: any) => j.createdAt)) : null;
      const oldestPendingAge = oldestPending ? Date.now() - oldestPending : null;

      return {
        totalPending: pending.length,
        totalCompleted: completed.length,
        totalFailed: failed.length,
        oldestPendingAge,
      };
    } catch (e) {
      logger.error("Failed to get queue stats", e as Error);
      return {
        totalPending: 0,
        totalCompleted: 0,
        totalFailed: 0,
        oldestPendingAge: null,
      };
    }
  }

  /**
   * Clear old completed jobs (older than 24 hours)
   */
  static async clearOldCompletedJobs(ageHours: number = 24) {
    try {
      const cutoffTime = Date.now() - ageHours * 60 * 60 * 1000;

      const all = await (pouchDb as any).allDocs({ include_docs: true });
      const oldJobs = (all.rows || [])
        .map((r: any) => r.doc)
        .filter(
          (d: any) =>
            d &&
            d.type === "print-job" &&
            (d.status === "completed" || d.status === "failed") &&
            d.createdAt < cutoffTime,
        );

      for (const job of oldJobs) {
        await (pouchDb as any).remove(job);
      }

      logger.info("Cleared old print jobs", {
        deletedCount: oldJobs.length,
        ageHours,
      });

      return oldJobs.length;
    } catch (e) {
      logger.error("Failed to clear old print jobs", e as Error);
      throw e;
    }
  }

  /**
   * Export queue as JSON for debugging
   */
  static async exportQueue(): Promise<PrintJob[]> {
    try {
      const all = await (pouchDb as any).allDocs({ include_docs: true });
      return (all.rows || [])
        .map((r: any) => r.doc)
        .filter((d: any) => d && d.type === "print-job");
    } catch (e) {
      logger.error("Failed to export queue", e as Error);
      return [];
    }
  }
}

