                borderRadius: 10,
                padding: "6px 14px",
                marginRight: 16,
              }}
            >
              <span style={{ fontSize: 18, lineHeight: 1 }}>≡ƒòÉ</span>
              <div style={{ lineHeight: 1 }}>
                <div
                  style={{
                    fontSize: 14,
                    fontWeight: 800,
                    color: "#111827",
                    letterSpacing: 0.3,
                  }}
