                    background: "linear-gradient(135deg,#b45309,#f59e0b)",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    color: "#fff",
                    fontWeight: 900,
                    fontSize: 13,
                    flexShrink: 0,
                    boxShadow: "0 2px 6px rgba(180,83,9,0.22)",
                  }}
                >
                  {(auth.session.displayName || auth.session.username)
                    .charAt(0)
                    .toUpperCase()}
                </div>
                <div style={{ lineHeight: 1, textAlign: "left" }}>
                  <div
                    style={{ fontSize: 13, fontWeight: 700, color: "#111827" }}
                  >
                    {auth.session.displayName || auth.session.username}
                  </div>
                  <div
                    style={{
                      fontSize: 11,
                      color: "#9ca3af",
                      marginTop: 2,
                      textTransform: "capitalize",
                    }}
                  >
                    {auth.session.role}
                  </div>
                </div>
                <div style={{ marginLeft: 6, color: "#9ca3af", fontSize: 12 }}>
                  Γû╛
                </div>
              </button>

              {userMenuOpen && (
                <div
                  role="menu"
                  style={{
                    position: "absolute",
                    right: 0,
                    marginTop: 8,
                    minWidth: 180,
                    background: "#fff",
                    boxShadow: "0 12px 40px rgba(0,0,0,0.12)",
                    borderRadius: 8,
                    overflow: "hidden",
                    zIndex: 2000,
                  }}
                >
                  <button
                    role="menuitem"
                    onClick={() => {
                      setUserMenuOpen(false);
