                    }}
                    style={{
                      display: "block",
                      width: "100%",
                      padding: "10px 14px",
                      textAlign: "left",
                      border: "none",
                      background: "transparent",
                      cursor: "pointer",
                    }}
                  >
                    Profile
                  </button>
                  <button
                    role="menuitem"
                    onClick={() => {
                      setUserMenuOpen(false);
                      // TODO: switch user flow
                    }}
                    style={{
                      display: "block",
                      width: "100%",
                      padding: "10px 14px",
                      textAlign: "left",
                      border: "none",
                      background: "transparent",
                      cursor: "pointer",
                    }}
                  >
                    Switch User
                  </button>
                  <div style={{ height: 1, background: "#f3f4f6" }} />
                  <button
                    role="menuitem"
                    onClick={() => auth.logout()}
                    style={{
                      display: "block",
                      width: "100%",
                      padding: "10px 14px",
                      textAlign: "left",
                      border: "none",
                      background: "transparent",
                      color: "#dc2626",
                      fontWeight: 700,
                      cursor: "pointer",
                    }}
                  >
                    Logout
                  </button>
                </div>
              )}
            </div>
          </div>

          {/* ΓöÇΓöÇ Nav bar: full-width tab strip ΓöÇΓöÇ */}
          <nav
            id="main-nav"
            aria-label="Main navigation"
            style={{
              display: "flex",
              alignItems: "stretch",
              padding: "0 20px",
              height: 40,
              gap: 2,
              background: "#fff7ed", // warm brand tint
              boxShadow: "inset 0 -1px 0 rgba(0,0,0,0.02)",
            }}
          >
            {navItems
              .filter((n) => allowedPages.includes(n.k))
              .map((it) => {
                const active = page === it.k;
                return (
                  <button
                    key={it.k}
                    type="button"
                    onClick={() => {
                      setPage(it.k as any);
                      window.location.hash = `#${it.k}`;
                    }}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: 6,
                      padding: "0 16px",
                      background: active ? "#fffbeb" : "transparent",
                      border: "none",
                      borderBottom: active
                        ? "3px solid #d97706"
                        : "3px solid transparent",
                      borderTop: "3px solid transparent",
                      color: active ? "#b45309" : "#6b7280",
                      fontWeight: active ? 700 : 500,
                      fontSize: 13,
                      cursor: "pointer",
                      whiteSpace: "nowrap",
                      outline: "none",
                      borderRadius: 0,
                      transition:
                        "color 120ms, background 120ms, border-color 120ms",
                    }}
                    onMouseEnter={(e) => {
                      const btn = e.currentTarget as HTMLButtonElement;
                      if (!active) {
                        btn.style.color = "#374151";
                        btn.style.background = "#f9fafb";
                      }
                    }}
                    onMouseLeave={(e) => {
                      const btn = e.currentTarget as HTMLButtonElement;
                      if (!active) {
                        btn.style.color = "#6b7280";
                        btn.style.background = "transparent";
                      }
                    }}
                  >
                    <span
                      aria-hidden
                      style={{
                        fontSize: 14,
                        lineHeight: 1,
                        color: active ? "#d97706" : "#9ca3af",
                        transition: "color 120ms",
                      }}
                    >
                      {it.icon}
                    </span>
                    {it.t}
                  </button>
                );
              })}
          </nav>
        </header>

        <div
          id="main-content"
          style={{ display: "flex", flex: 1, minHeight: 0 }}
        >
          {inlineLayout ? (
            // Equal 50/50 split when inline billing is active
            <div
              id="split-view"
              style={{ display: "flex", flex: 1, gap: 0, minHeight: 0 }}
            >
              <main
                id="tables-section"
                // split view columns can scroll independently
                style={{
                  flex: 1,
                  padding: 12,
                  overflow: "auto",
                  minHeight: 0,
                }}
              >
                <Tables />
              </main>
              <aside
                id="billing-section"
                style={{
                  flex: 1,
                  borderLeft: "1px solid #eee",
                  background: "#fafaff",
                  overflow: "auto",
                  minHeight: 0,
                }}
              >
                <Billing onClearBill={handleClearBill} />
              </aside>
            </div>
          ) : (
            // Default layout: main content + narrow right rail for one-hand controls
            <>
              <main
                style={{ flex: 1, padding: 12, overflow: "auto", minHeight: 0 }}
              >
                {page === "tables" && <Tables />}
                {page === "billing" && (
                  <Billing onClearBill={handleClearBill} />
                )}
                {page === "kot" && <KOTQueue />}
                {page === "customers" && <Customers />}
                {page === "reports" && <Reports />}
                {page === "history" && <History />}
                {page === "menu" && <ItemsEditor />}
                {page === "settings" && <Settings />}
                {page === "audit" && auth.session.role === "admin" && (
                  <AuditViewer />
                )}
              </main>
              {/* <aside
            style={{
              width: 420,
              borderLeft: "1px solid #eee",
              background: "#fafaff",
              overflow: "auto",
            }}
          >
            <OneHandControls
              onAddItem={handleAddItem}
              onSendKOT={handleSendKOT}
              onPay={handlePay}
              onCancel={handleCancel}
            />
          </aside> */}
            </>
          )}
        </div>

        <PaymentsModal
          open={paymentsOpen}
          onClose={() => setPaymentsOpen(false)}
          amount={0}
        />
      </div>
    );
  };

  return (
    <AuthProvider>
      <MainContent />
    </AuthProvider>
  );
}

import React from "react";
import { getAudits } from "../../../app/db/pouch";

export default function AuditViewer() {
  const [items, setItems] = React.useState<any[]>([]);
  const [loading, setLoading] = React.useState(false);
  const [filter, setFilter] = React.useState<string>("");
  const [dateFrom, setDateFrom] = React.useState<string>("");
  const [dateTo, setDateTo] = React.useState<string>("");
  const [page, setPage] = React.useState<number>(1);
  const [pageSize, setPageSize] = React.useState<number>(25);

  const load = async () => {
    setLoading(true);
    try {
      // prefer the indexed query helper
      const fromTs = dateFrom
        ? new Date(dateFrom).setHours(0, 0, 0, 0)
        : undefined;
      const toTs = dateTo
        ? new Date(dateTo).setHours(23, 59, 59, 999)
        : undefined;
      const docs = await getAudits({ from: fromTs, to: toTs, limit: 100000 });
      const audits = (docs || [])
        .filter((d: any) => d && d.type === "audit")
        .sort((a: any, b: any) => (b.timestamp || 0) - (a.timestamp || 0));
      setItems(audits);
    } catch (e) {
      console.error("Failed to load audits:", e);
      setItems([]);
    }
    setLoading(false);
  };

  React.useEffect(() => {
    load();
  }, []);

  const filtered = items.filter((it) => {
    if (!filter && !dateFrom && !dateTo) {
return true;
}
    const q = (filter || "").toLowerCase();
    if (filter) {
      const matches =
        String(it.action || "")
          .toLowerCase()
          .includes(q) ||
        String(it.orderId || "")
          .toLowerCase()
          .includes(q) ||
        String(it.user || "")
          .toLowerCase()
          .includes(q) ||
        JSON.stringify(it.detail || {})
          .toLowerCase()
          .includes(q);
      if (!matches) {
return false;
}
    }
    // date filtering (inclusive)
    const ts = Number(it.timestamp) || 0;
    if (dateFrom) {
      const fromTs = new Date(dateFrom).setHours(0, 0, 0, 0);
      if (ts < fromTs) {
return false;
}
    }
    if (dateTo) {
      const toTs = new Date(dateTo).setHours(23, 59, 59, 999);
      if (ts > toTs) {
return false;
}
    }
    return true;
  });

  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const pageItems = filtered.slice((page - 1) * pageSize, page * pageSize);

  React.useEffect(() => {
    // clamp page when filters change
    if (page > totalPages) {
setPage(totalPages);
}
  }, [filtered.length, pageSize, totalPages]);

  // CSV helpers
  const toCSV = (rows: any[]) => {
    const header = ["timestamp", "action", "orderId", "user", "detail"];
    const esc = (s: any) => {
      if (s === null || s === undefined) {
return "";
}
      const str = typeof s === "string" ? s : JSON.stringify(s);
      if (str.includes(",") || str.includes("\n") || str.includes('"')) {
        return '"' + str.replace(/"/g, '""') + '"';
      }
      return str;
    };
    const lines = [header.join(",")];
    for (const r of rows) {
      lines.push(
        [
          new Date(r.timestamp || 0).toISOString(),
          esc(r.action),
          esc(r.orderId),
          esc(r.user),
          esc(r.detail || ""),
        ].join(","),
      );
    }
    return lines.join("\n");
  };

  const downloadCSV = (rows: any[]) => {
    const csv = toCSV(rows);
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `audit-${new Date()
      .toISOString()
      .slice(0, 19)
      .replace(/[:T]/g, "-")}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  };

  // Action color mapping
  const getActionColor = (action: string) => {
    if (action.includes("created")) {
return { bg: "#f0fdf4", color: "#16a34a", icon: "Γ£ô" };
}
    if (action.includes("paid")) {
return { bg: "#dcfce7", color: "#22c55e", icon: "≡ƒÆ░" };
}
    if (action.includes("cancelled")) {
return { bg: "#fee2e2", color: "#dc2626", icon: "Γ£ò" };
}
    if (action.includes("added")) {
return { bg: "#fef3c7", color: "#d97706", icon: "+" };
}
    if (action.includes("updated")) {
return { bg: "#e0f2fe", color: "#0284c7", icon: "Γ£Ä" };
}
    return { bg: "#f3f4f6", color: "#6b7280", icon: "ΓÇó" };
  };

  return (
    <div
      style={{
        padding: "12px 16px",
        maxWidth: 1400,
        margin: "0 auto",
      }}
    >
      {/* Header */}
      <div style={{ marginBottom: 20 }}>
        <h2
          style={{
            margin: 0,
            fontSize: 22,
            fontWeight: 800,
            color: "#111827",
          }}
        >
          Audit Log
        </h2>
        <p style={{ margin: "3px 0 0", fontSize: 13, color: "#9ca3af" }}>
          Track all system activities and transactions
        </p>
      </div>

      {/* Filter Controls */}
      <div
        style={{
          background: "#fff",
          border: "1px solid #e5e7eb",
          borderRadius: 12,
          padding: "16px",
          marginBottom: 20,
        }}
      >
        {/* Filter inputs row */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(140px, 1fr))",
            gap: 12,
            marginBottom: 14,
          }}
        >
          <div>
            <label
              style={{
                display: "block",
                fontSize: 12,
                fontWeight: 600,
                color: "#374151",
                marginBottom: 6,
                textTransform: "uppercase",
                letterSpacing: "0.05em",
              }}
            >
              Search
            </label>
            <input
              placeholder="Filter by action/order/user"
              value={filter}
              onChange={(e) => {
                setFilter(e.target.value);
                setPage(1);
              }}
              style={{
                width: "100%",
                padding: "10px 12px",
                borderRadius: 8,
                border: "1px solid #d1d5db",
                fontSize: 14,
                boxSizing: "border-box",
              }}
            />
          </div>

          <div>
            <label
              style={{
                display: "block",
                fontSize: 12,
                fontWeight: 600,
                color: "#374151",
                marginBottom: 6,
                textTransform: "uppercase",
                letterSpacing: "0.05em",
              }}
            >
              From
            </label>
            <input
              type="date"
              value={dateFrom}
              onChange={(e) => {
                setDateFrom(e.target.value);
                setPage(1);
              }}
              style={{
                width: "100%",
                padding: "10px 12px",
                borderRadius: 8,
                border: "1px solid #d1d5db",
                fontSize: 14,
                boxSizing: "border-box",
              }}
            />
          </div>

          <div>
            <label
              style={{
                display: "block",
                fontSize: 12,
                fontWeight: 600,
                color: "#374151",
                marginBottom: 6,
                textTransform: "uppercase",
                letterSpacing: "0.05em",
              }}
            >
              To
            </label>
            <input
              type="date"
              value={dateTo}
              onChange={(e) => {
                setDateTo(e.target.value);
                setPage(1);
              }}
              style={{
                width: "100%",
                padding: "10px 12px",
                borderRadius: 8,
                border: "1px solid #d1d5db",
                fontSize: 14,
                boxSizing: "border-box",
              }}
            />
          </div>

          <div>
            <label
              style={{
                display: "block",
                fontSize: 12,
                fontWeight: 600,
                color: "#374151",
                marginBottom: 6,
                textTransform: "uppercase",
                letterSpacing: "0.05em",
              }}
            >
              Per Page
            </label>
            <select
              value={pageSize}
              onChange={(e) => {
                setPageSize(Number(e.target.value));
                setPage(1);
              }}
              style={{
                width: "100%",
                padding: "10px 12px",
                borderRadius: 8,
                border: "1px solid #d1d5db",
                fontSize: 14,
                boxSizing: "border-box",
              }}
            >
              <option value={10}>10</option>
              <option value={25}>25</option>
              <option value={50}>50</option>
              <option value={100}>100</option>
            </select>
          </div>
        </div>

        {/* Action buttons row */}
        <div
          style={{
            display: "flex",
            gap: 10,
            flexWrap: "wrap",
            alignItems: "center",
            paddingTop: 12,
            borderTop: "1px solid #e5e7eb",
          }}
        >
          <button
            onClick={load}
            disabled={loading}
            style={{
              padding: "10px 16px",
              borderRadius: 8,
              border: "1px solid #3b82f6",
              background: "#eff6ff",
              color: "#0c4a6e",
              fontWeight: 600,
              fontSize: 14,
              cursor: loading ? "not-allowed" : "pointer",
              opacity: loading ? 0.7 : 1,
              transition: "all 120ms",
              whiteSpace: "nowrap",
            }}
            onMouseEnter={(e) => {
              if (!loading) {
                (e.currentTarget as HTMLButtonElement).style.background =
                  "#bfdbfe";
              }
            }}
            onMouseLeave={(e) => {
              (e.currentTarget as HTMLButtonElement).style.background =
                "#eff6ff";
            }}
          >
            {loading ? "Loading..." : "≡ƒöä Refresh"}
          </button>

          <button
            onClick={() => downloadCSV(filtered)}
            disabled={filtered.length === 0}
            style={{
              padding: "10px 16px",
              borderRadius: 8,
              border: "1px solid #10b981",
              background: "#f0fdf4",
              color: "#065f46",
              fontWeight: 600,
              fontSize: 14,
              cursor: filtered.length > 0 ? "pointer" : "not-allowed",
              opacity: filtered.length > 0 ? 1 : 0.5,
              transition: "all 120ms",
              whiteSpace: "nowrap",
            }}
            onMouseEnter={(e) => {
              if (filtered.length > 0) {
                (e.currentTarget as HTMLButtonElement).style.background =
                  "#bbf7d0";
              }
            }}
            onMouseLeave={(e) => {
              (e.currentTarget as HTMLButtonElement).style.background =
                "#f0fdf4";
            }}
          >
            Γ¼ç∩╕Å Export CSV
          </button>

          <div
            style={{
              marginLeft: "auto",
              fontSize: 13,
              color: "#6b7280",
              fontWeight: 500,
            }}
          >
            {filtered.length} result{filtered.length !== 1 ? "s" : ""}
          </div>
        </div>
      </div>

      {/* Audit Entries Table */}
      <div
        style={{
          background: "#fff",
          border: "1px solid #e5e7eb",
          borderRadius: 12,
          overflow: "hidden",
          marginBottom: 16,
        }}
      >
        {pageItems.length === 0 ? (
          <div
            style={{
              padding: "40px",
              textAlign: "center",
              color: "#9ca3af",
            }}
          >
            <div style={{ fontSize: 16, marginBottom: 8 }}>
              ≡ƒô¡ No audit entries
            </div>
            <div style={{ fontSize: 13 }}>
              {filter || dateFrom || dateTo
                ? "No entries match your filters"
                : "No audit logs available yet"}
            </div>
          </div>
        ) : (
          <div style={{ maxHeight: "calc(100vh - 400px)", overflow: "auto" }}>
            {pageItems.map((a, idx) => {
              const actionColor = getActionColor(a.action || "");
              return (
                <div
                  key={a._id}
                  style={{
                    padding: "16px",
                    borderBottom:
                      idx !== pageItems.length - 1
                        ? "1px solid #f3f4f6"
                        : "none",
                    display: "grid",
                    gridTemplateColumns: "auto 1fr auto",
                    gap: 16,
                    alignItems: "start",
                    minHeight: "80px",
                  }}
                >
                  {/* Action Badge */}
                  <div
                    style={{
                      background: actionColor.bg,
                      color: actionColor.color,
                      padding: "8px",
                      borderRadius: 8,
                      textAlign: "center",
                      fontSize: 18,
                      fontWeight: 700,
                      minHeight: "40px",
                      minWidth: "40px",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      flexShrink: 0,
                    }}
                  >
                    {actionColor.icon}
                  </div>

                  {/* Main Content */}
                  <div>
                    <div
                      style={{
                        fontWeight: 700,
                        fontSize: 14,
                        color: "#111827",
                        marginBottom: 8,
                        wordBreak: "break-word",
                      }}
                    >
                      {a.action}
                    </div>
                    <div
                      style={{
                        display: "grid",
                        gridTemplateColumns: "auto 1fr",
                        gap: "12px 16px",
                        fontSize: 13,
                        color: "#6b7280",
                      }}
                    >
                      <span style={{ fontWeight: 600 }}>Order:</span>
                      <span
                        style={{
                          fontFamily: "monospace",
                          wordBreak: "break-all",
                        }}
                      >
                        {a.orderId || "ΓÇö"}
                      </span>
                      <span style={{ fontWeight: 600 }}>User:</span>
                      <span>{a.user || "ΓÇö"}</span>
                    </div>
                    {a.detail && Object.keys(a.detail).length > 0 && (
                      <details style={{ marginTop: 8 }}>
                        <summary
                          style={{
                            cursor: "pointer",
                            color: "#3b82f6",
                            fontSize: 12,
                            fontWeight: 600,
                            userSelect: "none",
                          }}
                        >
                          ≡ƒôï View Details
                        </summary>
                        <pre
                          style={{
                            background: "#f9fafb",
                            padding: "10px",
                            borderRadius: 6,
                            marginTop: 8,
                            fontSize: 11,
                            whiteSpace: "pre-wrap",
                            wordWrap: "break-word",
                            color: "#374151",
                            border: "1px solid #e5e7eb",
                            maxWidth: "100%",
                            overflow: "auto",
                          }}
                        >
                          {JSON.stringify(a.detail || {}, null, 2)}
                        </pre>
                      </details>
                    )}
                  </div>

                  {/* Timestamp */}
                  <div style={{ textAlign: "right", whiteSpace: "nowrap" }}>
                    <div
                      style={{
                        fontSize: 13,
                        fontWeight: 600,
                        color: "#111827",
                      }}
                    >
                      {new Date(a.timestamp || 0).toLocaleDateString("en-IN")}
                    </div>
                    <div
                      style={{
                        fontSize: 12,
                        color: "#9ca3af",
                        marginTop: 4,
                      }}
                    >
                      {new Date(a.timestamp || 0).toLocaleTimeString("en-IN", {
                        hour: "2-digit",
                        minute: "2-digit",
                      })}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div
          style={{
            display: "flex",
            gap: 8,
            alignItems: "center",
            justifyContent: "center",
            flexWrap: "wrap",
            padding: "12px",
            background: "#f9fafb",
            borderRadius: 8,
          }}
        >
          <button
            onClick={() => setPage(Math.max(1, page - 1))}
            disabled={page <= 1}
            style={{
              padding: "8px 12px",
              borderRadius: 6,
              border: "1px solid #d1d5db",
              background: page > 1 ? "#fff" : "#f3f4f6",
              color: page > 1 ? "#374151" : "#9ca3af",
              fontWeight: 600,
              fontSize: 13,
              cursor: page > 1 ? "pointer" : "not-allowed",
              transition: "all 120ms",
              whiteSpace: "nowrap",
            }}
            onMouseEnter={(e) => {
              if (page > 1) {
                (e.currentTarget as HTMLButtonElement).style.background =
                  "#f3f4f6";
              }
            }}
          >
            ΓåÉ Prev
          </button>

          <div
            style={{
              fontSize: 12,
              fontWeight: 600,
              color: "#6b7280",
              textAlign: "center",
            }}
          >
            Page{" "}
            <span style={{ color: "#111827", fontWeight: 700 }}>{page}</span> of{" "}
            <span style={{ color: "#111827", fontWeight: 700 }}>
              {totalPages}
            </span>
          </div>

          <button
            onClick={() => setPage(Math.min(totalPages, page + 1))}
            disabled={page >= totalPages}
            style={{
              padding: "8px 12px",
              borderRadius: 6,
              border: "1px solid #d1d5db",
              background: page < totalPages ? "#fff" : "#f3f4f6",
              color: page < totalPages ? "#374151" : "#9ca3af",
              fontWeight: 600,
              fontSize: 13,
              cursor: page < totalPages ? "pointer" : "not-allowed",
              transition: "all 120ms",
              whiteSpace: "nowrap",
            }}
            onMouseEnter={(e) => {
              if (page < totalPages) {
                (e.currentTarget as HTMLButtonElement).style.background =
                  "#f3f4f6";
              }
            }}
          >
            Next ΓåÆ
          </button>

          <div
            style={{
              fontSize: 12,
              color: "#9ca3af",
              fontWeight: 500,
              width: "100%",
              textAlign: "center",
              order: 10,
            }}
          >
            {filtered.length} total item{filtered.length !== 1 ? "s" : ""}
          </div>
        </div>
      )}
    </div>
  );
}

/* Example: Billing page refactored to use CSS Modules */
import React from "react";
import {
  db as pouchDb,
  getOrderById,
  addItemToOrder,
  getOrCreateOrderForTable,
  getOpenOrderForTable,
  setOrderPaid,
  cancelOrder,
  getItems,
  seedItems,
  updateOrder,
} from "../../../app/db/pouch";
import { printReceipt, printKOT } from "../../../app/services/printer";
import { logger } from "../../../app/utils/logger";
import { CrashRecovery } from "../../../app/utils/crashRecovery";
import styles from "./Billing.module.css";
import OrderList from "./components/OrderList";
import Modal from "./components/Modal";
import TabButton from "./components/TabButton";
import OrderRow from "./components/OrderRow";
import PickButtons from "./components/PickButtons";
import ScrollableList from "./components/ScrollableList";

interface BillingProps {
  onClearBill?: () => void;
}

export default function Billing({ onClearBill }: BillingProps) {
  const [order, setOrder] = React.useState<any>(null);
  const [tableNum, setTableNum] = React.useState<number | null>(null);
  // collapsible tables column for single-page Tables+Billing layout (persisted)
  const [tablesOpen, setTablesOpen] = React.useState<boolean>(() => {
    try {
      if (typeof window === "undefined") {
return false;
}
      return window.localStorage.getItem("tablesOpen") === "1";
    } catch (e) {
      return false;
    }
  });
  const setTablesOpenPersisted = (val: boolean) => {
    setTablesOpen(val);
    try {
      if (typeof window !== "undefined") {
window.localStorage.setItem("tablesOpen", val ? "1" : "0");
}
    } catch (e) {}
  };
  const tableNumbers = React.useMemo(() => Array.from({ length: 12 }, (_, i) => i + 1), []);
  // currency formatter helper (defined early to avoid reference errors)
  const formatCurrency = (v: number) => {
    try {
      return new Intl.NumberFormat("en-IN", {
        style: "currency",
        currency: "INR",
        maximumFractionDigits: 2,
      }).format(v);
    } catch (e) {
      return `Γé╣${Math.round(v * 100) / 100}`;
    }
  };
  const [tableInfos, setTableInfos] = React.useState<
    Record<
      number,
      {
        status?: string;
        count?: number;
        total?: number;
        waiter?: string;
        updatedAt?: string;
      }
    >
  >({});

  // UI view: tables | takeaway | delivery
  const [view, setView] = React.useState<"tables" | "takeaway" | "delivery">("tables");
  const [takeawayOrders, setTakeawayOrders] = React.useState<any[]>([]);
  const [deliveryOrders, setDeliveryOrders] = React.useState<any[]>([]);

  // New order creation modals
  const [newTakeawayOpen, setNewTakeawayOpen] = React.useState(false);
  const [newTakeawayName, setNewTakeawayName] = React.useState("");
  const [newDeliveryOpen, setNewDeliveryOpen] = React.useState(false);
  const [newDeliveryPlatform, setNewDeliveryPlatform] = React.useState("Swiggy");
  const [newDeliveryCode, setNewDeliveryCode] = React.useState("");

  // load non-table queues (takeaway / delivery) from DB (best-effort using allDocs)
  const loadQueues = React.useCallback(async () => {
    try {
      const all = await (pouchDb as any).allDocs({ include_docs: true });
      const docs = (all.rows || []).map((r: any) => r.doc).filter(Boolean);
      // exclude paid orders from active queues
      const orders = docs.filter((d: any) => d && d.type === "order" && d.status !== "paid");
      const takeaway = orders.filter(
        (o: any) => (o.orderType || o.meta?.orderType || "").toLowerCase() === "takeaway",
      );
      const delivery = orders.filter(
        (o: any) =>
          (o.orderType || o.meta?.orderType || "").toLowerCase() === "delivery" ||
          (o.meta &&
            (o.meta.platform || "")
              .toString()
              .toLowerCase()
              .match(/swiggy|zomato|dunzo|zepto/)),
      );
      setTakeawayOrders(takeaway);
      setDeliveryOrders(delivery);
      logger.info("Queues loaded", {
        takeawayCount: takeaway.length,
        deliveryCount: delivery.length,
      });
    } catch (e) {
      logger.error("Billing: failed to load queues", e as Error);
      setTakeawayOrders([]);
      setDeliveryOrders([]);
    }
  }, []);

  // Create a new takeaway order
  const createTakeawayOrder = async () => {
    try {
      const name = newTakeawayName.trim();
      const id = `order:${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
      const now = Date.now();
      const doc = {
        _id: id,
        type: "order",
        tableId: null,
        orderType: "takeaway",
        items: [],
        status: "open",
        createdAt: now,
        updatedAt: now,
        meta: { customerName: name },
      };
      await (pouchDb as any).put(doc);
      const fresh = await getOrderById(id);
      setOrder(fresh);
      setTableNum(null);
      if (typeof window !== "undefined") {
window.localStorage.setItem("currentOrderId", id);
}
      window.localStorage.removeItem("currentTable");
      setNewTakeawayOpen(false);
      setNewTakeawayName("");
      logger.info("Takeaway order created", { orderId: id, customerName: name });
      // Save recovery state
      CrashRecovery.saveState({
        currentOrderId: id,
        cartItems: fresh?.items || [],
        discountPercent: 0,
      });
      window.dispatchEvent(new Event("orders-changed"));
      setTimeout(() => searchRef.current?.focus(), 50);
    } catch (error) {
      logger.error("Failed to create takeaway order", error as Error, {
        customerName: newTakeawayName,
      });
    }
  };

  // Create a new delivery order
  const createDeliveryOrder = async () => {
    try {
      const platform = newDeliveryPlatform.trim() || "Delivery";
      const code = newDeliveryCode.trim();
      const id = `order:${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
      const now = Date.now();
      const doc = {
        _id: id,
        type: "order",
        tableId: null,
        orderType: "delivery",
        items: [],
        status: "open",
        createdAt: now,
        updatedAt: now,
        meta: { platform, code, orderCode: code },
      };
      await (pouchDb as any).put(doc);
      const fresh = await getOrderById(id);
      setOrder(fresh);
      setTableNum(null);
      if (typeof window !== "undefined") {
window.localStorage.setItem("currentOrderId", id);
}
      window.localStorage.removeItem("currentTable");
      setNewDeliveryOpen(false);
      setNewDeliveryCode("");
      logger.info("Delivery order created", { orderId: id, platform, code });
      // Save recovery state
      CrashRecovery.saveState({
        currentOrderId: id,
        cartItems: fresh?.items || [],
        discountPercent: 0,
      });
      window.dispatchEvent(new Event("orders-changed"));
      setTimeout(() => searchRef.current?.focus(), 50);
    } catch (error) {
      logger.error("Failed to create delivery order", error as Error, {
        platform: newDeliveryPlatform,
        code: newDeliveryCode,
      });
    }
  };

  React.useEffect(() => {
    loadQueues();
    const onChanged = () => loadQueues();
    window.addEventListener("orders-changed", onChanged);
    return () => window.removeEventListener("orders-changed", onChanged);
  }, [loadQueues]);

  const loadTableStatuses = React.useCallback(async () => {
    const acc: Record<
      number,
      {
        status?: string;
        count?: number;
        total?: number;
        waiter?: string;
        updatedAt?: string;
      }
    > = {};
    for (const t of tableNumbers) {
      try {
        const o = await getOpenOrderForTable(t);
        if (o) {
          const count = (o.items || []).length;
          const total = (o.items || []).reduce(
            (s: number, it: any) => s + (it.qty || 0) * (it.rate || 0),
            0,
          );
          // try to read waiter/updated metadata if present
          const waiter = (o as any).waiter || (o as any).servedBy || (o as any).meta?.waiter || "";
          const updatedAt =
            (o as any).updatedAt ||
            (o as any).modifiedAt ||
            (o as any).meta?.updatedAt ||
            (o as any)._updatedAt ||
            "";
          acc[t] = {
            status: o.status === "held" ? "held" : "open",
            count,
            total,
            waiter,
            updatedAt,
          };
        } else {
acc[t] = {
            status: "",
            count: 0,
            total: 0,
            waiter: "",
            updatedAt: "",
          };
}
      } catch (e) {
        acc[t] = { status: "", count: 0, total: 0, waiter: "", updatedAt: "" };
      }
    }
    setTableInfos(acc);
  }, [tableNumbers]);

  React.useEffect(() => {
    loadTableStatuses();
    const onChanged = () => loadTableStatuses();
    window.addEventListener("orders-changed", onChanged);
    return () => window.removeEventListener("orders-changed", onChanged);
  }, [loadTableStatuses]);

  const loadTable = async (tn: number) => {
    try {
      const o = await getOrCreateOrderForTable(tn);
      setOrder(o);
      setTableNum(tn);
      if (typeof window !== "undefined") {
        window.localStorage.setItem("currentOrderId", o._id);
        window.localStorage.setItem("currentTable", String(tn));
      }
      logger.info("Table loaded", { tableNumber: tn, orderId: o._id });
      // Save recovery state
      CrashRecovery.saveState({
        currentOrderId: o._id,
        currentTable: tn,
        cartItems: o?.items || [],
        discountPercent: o?.discountPercent || 0,
      });
      // keep search focused for quick adding
      setTimeout(() => searchRef.current?.focus(), 10);
      // refresh table badges after selecting
      setTimeout(() => loadTableStatuses(), 50);
    } catch (error) {
      logger.error("Failed to load table", error as Error, { tableNumber: tn });
    }
  };
  const [items, setItems] = React.useState<any[]>([]);
  const [query, setQuery] = React.useState("");
  const [filtered, setFiltered] = React.useState<any[]>([]);
  const [qty, setQty] = React.useState<number>(1);
  const [highlighted, setHighlighted] = React.useState<number>(-1);
  const [lastAddedId, setLastAddedId] = React.useState<string | null>(null);
  const [confirmPayOpen, setConfirmPayOpen] = React.useState(false);
  const [confirmCancelOpen, setConfirmCancelOpen] = React.useState(false);
  // Discount percent to apply to final bill (0-100)
  const [discountPercent, setDiscountPercent] = React.useState<number>(0);
  // KOT preview modal state
  const [kotPreviewOpen, setKotPreviewOpen] = React.useState(false);
  const [kotPreviewData, setKotPreviewData] = React.useState<any | null>(null);
  // per-line temporary edit values for qty inputs
  const [editingQty, setEditingQty] = React.useState<Record<string, string>>({});
  // per-line temporary edit values for rate inputs
  const [editingRate, setEditingRate] = React.useState<Record<string, string>>({});
  const commitRate = async (id: string) => {
    if (!order) {
return;
}
    const valStr = editingRate[id];
    const parsed = Math.max(0, parseFloat(String(valStr || "0")) || 0);
    const updated = await updateOrder({
      ...order,
      items: order.items.map((l: any) => (l.id === id ? { ...l, rate: parsed } : l)),
    });
    setOrder(updated);
    setEditingRate((prev) => {
      const copy = { ...prev } as Record<string, string>;
      delete copy[id];
      return copy;
    });
    setTimeout(() => searchRef.current?.focus(), 10);
  };
  const commitQty = async (id: string) => {
    if (!order) {
return;
}
    const valStr = editingQty[id];
    const parsed = Math.max(1, parseInt(String(valStr || "1"), 10) || 1);
    const updated = await updateOrder({
      ...order,
      items: order.items.map((l: any) => (l.id === id ? { ...l, qty: parsed } : l)),
    });
    setOrder(updated);
    setEditingQty((prev) => {
      const copy = { ...prev } as Record<string, string>;
      delete copy[id];
      return copy;
    });
    setTimeout(() => searchRef.current?.focus(), 10);
  };
  const searchRef = React.useRef<HTMLInputElement | null>(null);

  React.useEffect(() => {
    (async () => {
      const tableStr =
        typeof window !== "undefined" ? window.localStorage.getItem("currentTable") : null;
      const orderId =
        typeof window !== "undefined" ? window.localStorage.getItem("currentOrderId") : null;
      if (orderId) {
        const o = await getOrderById(orderId);
        setOrder(o);
        if (tableStr) {
setTableNum(parseInt(tableStr, 10));
}
      } else if (tableStr) {
        const tableNum = parseInt(tableStr, 10);
        const o = await getOrCreateOrderForTable(tableNum);
        setOrder(o);
        setTableNum(tableNum);
        if (typeof window !== "undefined") {
window.localStorage.setItem("currentOrderId", o._id);
}
      }

      // load menu items, seed if empty
      await seedItems();
      const all = await getItems();
      setItems(all);
    })();
  }, []);

  // quick fuzzy matching (keeps previous computeMatchData behavior)
  const computeMatchData = (it: any, q: string) => {
    const hayName = (it.name || "").toLowerCase();
    const haySku = (it.sku || "").toLowerCase();
    const tokens = q.toLowerCase().trim().split(/\s+/).filter(Boolean);

    if (tokens.length === 0) {
return null;
}

    let score = 0;
    const matches: { start: number; end: number }[] = [];

    for (const t of tokens) {
      const idxName = hayName.indexOf(t);
      const idxSku = haySku.indexOf(t);
      if (idxName >= 0) {
        score += Math.max(50, 200 - idxName);
        matches.push({ start: idxName, end: idxName + t.length });
      } else if (idxSku >= 0) {
        score += 80;
        matches.push({ start: -1, end: -1 });
      } else {
        return null;
      }
    }

    if (hayName === q.toLowerCase()) {
score += 200;
}

    const merged: { start: number; end: number }[] = [];
    for (const m of matches.filter((m) => m.start >= 0).sort((a, b) => a.start - b.start)) {
      if (!merged.length) {
merged.push({ ...m });
} else {
        const last = merged[merged.length - 1];
        if (m.start <= last.end) {
          last.end = Math.max(last.end, m.end);
        } else {
merged.push({ ...m });
}
      }
    }

    const parts: { text: string; match: boolean }[] = [];
    if (merged.length === 0) {
      parts.push({ text: it.name || "", match: false });
    } else {
      let ptr = 0;
      for (const mm of merged) {
        if (ptr < mm.start) {
parts.push({
            text: (it.name || "").slice(ptr, mm.start),
            match: false,
          });
}
        parts.push({
          text: (it.name || "").slice(mm.start, mm.end),
          match: true,
        });
        ptr = mm.end;
      }
      if (ptr < (it.name || "").length) {
parts.push({ text: (it.name || "").slice(ptr), match: false });
}
    }

    return { score, parts };
  };

  React.useEffect(() => {
    const q = query.toLowerCase().trim();
    if (!q) {
      setFiltered([]);
      setHighlighted(-1);
      return;
    }

    const candidates = items
      .map((it) => {
        const md = computeMatchData(it, q);
        if (!md) {
return null;
}
        return { item: it, score: md.score, parts: md.parts };
      })
      .filter(Boolean) as any[];

    candidates.sort((a, b) => b.score - a.score);
    setFiltered(candidates.slice(0, 10));
    setHighlighted(candidates.length ? 0 : -1);
  }, [query, items]);

  // add item to order and remember last added id for undo
  const addToOrder = async (item: any, quantity = 1) => {
    if (!order) {
      alert("Open or create a table/order first");
      return;
    }
    const res = await addItemToOrder(order._id, {
      name: item.name,
      qty: quantity,
      rate: item.price,
    });
    setOrder(res);
    const last = res.items[res.items.length - 1];
    setLastAddedId(last?.id ?? null);
    setTimeout(() => searchRef.current?.focus(), 10);
  };

  const onSelectItem = async (wrapped: any) => {
    const item = wrapped?.item ? wrapped.item : wrapped;
    await addToOrder(item, qty);
    // reset search and qty, keep focus
    setQuery("");
    setFiltered([]);
    setHighlighted(-1);
    setQty(1);
    setTimeout(() => searchRef.current?.focus(), 10);
  };

  const computeTotals = (ord: any) => {
    const subtotal = (ord?.items || []).reduce(
      (s: any, it: any) => s + (it.qty || 0) * (it.rate || 0),
      0,
    );
    const gstTotal = +(subtotal * 0.18).toFixed(2);
    const cgst = +(gstTotal / 2).toFixed(2);
    const sgst = +(gstTotal / 2).toFixed(2);
    const total = +(subtotal + cgst + sgst).toFixed(2);
    return { subtotal, cgst, sgst, gstTotal, total };
  };

  const removeLine = async (lineId: string) => {
    if (!order) {
return;
}
    const updated = {
      ...order,
      items: (order.items || []).filter((l: any) => l.id !== lineId),
    };
    await updateOrder(updated);
    const fresh = await getOrderById(order._id);
    setOrder(fresh);
  };

  const undoLast = async () => {
    if (!order || !lastAddedId) {
return;
}
    await removeLine(lastAddedId);
    setLastAddedId(null);
  };

  // Build structured ESC/POS receipt directives for the bill print
  const buildReceiptLines = (ord: any, tn: number | null, discPct: number): string[] => {
    const { subtotal, cgst, sgst, gstTotal, total } = computeTotals(ord);
    const discAmt = +((total * discPct) / 100).toFixed(2);
    const grandTotal = Math.max(0, +(total - discAmt).toFixed(2));

    const now = new Date();
    const pad2 = (n: number) => String(n).padStart(2, "0");
    const dateStr = `${pad2(now.getDate())}-${pad2(now.getMonth() + 1)}-${now.getFullYear()}`;
    const timeStr = now.toLocaleTimeString([], {
      hour: "2-digit",
      minute: "2-digit",
    });
    const dateTimeStr = `${dateStr} ${timeStr}`;

    // Auto-increment order number stored per session (or use last 6 of id)
    const orderNum = ord?._id ? parseInt(ord._id.replace(/\D/g, "").slice(-6), 10) || 1 : 1;

    const meta = ord?.meta || {};
    const orderType = ord?.orderType || (tn ? "dine-in" : "takeaway");
    const orderTypeLabel =
      orderType === "delivery" ? "DELIVERY" : orderType === "takeaway" ? "TAKEAWAY" : "DINE-IN";

    // Font A on 80mm printer = 42 chars/line total.
    // We reserve 1 space left + 1 space right = 40 usable chars for content.
    // All content lines are prefixed with a single space for left padding;
    // right padding is implicit (printer stops at paper edge).
    //
    // Column layout (40 usable chars):
    //   Item: 20  Qty: 4  Rate: 8  Amt: 8  ΓåÆ total 40
    const PAD = "  "; // 2-space left margin applied to every content line
    const WIDTH = 40; // usable chars per line (42 total ΓêÆ 1 left ΓêÆ 1 right)
    const COL_ITEM = 20;
    const COL_QTY = 4;
    const COL_RATE = 8;
    const COL_AMT = 8;

    const rpad = (s: string, w: number) => (s.length >= w ? s.slice(0, w) : s.padEnd(w));
    const lpad = (s: string, w: number) => (s.length >= w ? s.slice(0, w) : s.padStart(w));

    const fmtAmt = (n: number) => `${Math.round(n * 100) / 100}`;

    const lines: string[] = [
      // ΓöÇΓöÇ Header ΓÇö Font A double-height bold (hotel name) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      "BIGBOLD:HOTEL GURUKRUPA",
      // Font A normal centered (contact lines)
      "CENTER:Mob: 9876543211",
      "CENTER:HotelGurukrupa@gmail.com",
      "SEP",
      // ΓöÇΓöÇ Order type ΓÇö Font A bold centered ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      `SUBHEADER:${orderTypeLabel}`,
      ...(tn ? [`CENTER:Table No: ${tn}`] : []),
      ...(orderType === "delivery"
        ? [
            `CENTER:Platform: ${meta.platform || "Delivery"}`,
            ...(meta.code ? [`CENTER:Order Code: #${meta.code}`] : []),
          ]
        : []),
      ...(orderType === "takeaway" && (meta.customerName || meta.parcelName)
        ? [`CENTER:Customer: ${meta.customerName || meta.parcelName}`]
        : []),
      "SEP",
      // ΓöÇΓöÇ Order meta ΓÇö Font A normal, 1-space left padding ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      `LEFT:${PAD}Order No: ${orderNum}   Date: ${dateTimeStr}`,
      `LEFT:${PAD}Captain Name:`,
      "SEP",
      // ΓöÇΓöÇ Column header ΓÇö 1-space left padding ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      `LEFT:${PAD}${rpad("Item", COL_ITEM)}${lpad("Qty", COL_QTY)}${lpad("Rate", COL_RATE)}${lpad(
        "Amt",
        COL_AMT,
      )}`,
      "SEP",
      // ΓöÇΓöÇ Item rows ΓÇö 1-space left padding ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      ...(ord?.items || []).map((it: any) => {
        const name = rpad(String(it.name || ""), COL_ITEM);
        const qty = lpad(String(it.qty || 1), COL_QTY);
        const rate = lpad(fmtAmt(it.rate || 0), COL_RATE);
        const amt = lpad(fmtAmt((it.qty || 1) * (it.rate || 0)), COL_AMT);
        return `LEFTB:${PAD}${name}${qty}${rate}${amt}`;
      }),
      "SEP",
      // ΓöÇΓöÇ Totals ΓÇö 1-space left padding ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      `LEFTB:${PAD}${rpad("Sub Total", COL_ITEM + COL_QTY + COL_RATE)}${lpad(
        `Rs ${fmtAmt(subtotal)}`,
        COL_AMT,
      )}`,
      `LEFTB:${PAD}${rpad("CGST (9%)", COL_ITEM + COL_QTY + COL_RATE)}${lpad(
        `Rs ${fmtAmt(cgst)}`,
        COL_AMT,
      )}`,
      `LEFTB:${PAD}${rpad("SGST (9%)", COL_ITEM + COL_QTY + COL_RATE)}${lpad(
        `Rs ${fmtAmt(sgst)}`,
        COL_AMT,
      )}`,
      ...(discAmt > 0
        ? [
            `LEFTB:${PAD}${rpad(`Discount ${discPct}%`, COL_ITEM + COL_QTY + COL_RATE)}${lpad(
              `-Rs ${fmtAmt(discAmt)}`,
              COL_AMT,
            )}`,
          ]
        : []),
      "SEP",
      // ΓöÇΓöÇ Grand Total ΓÇö Font A bold, amount right-aligned to Amt column ΓöÇΓöÇΓöÇΓöÇ
      `BOLDLEFT:${PAD}${rpad("Grand Total", COL_ITEM + COL_QTY + COL_RATE)}${lpad(
        `Rs ${fmtAmt(grandTotal)}`,
        COL_AMT,
      )}`,
      "SEP",
      // ΓöÇΓöÇ Footer ΓÇö 1-space left padding ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      `LEFTB:${PAD}Printed by: Admin`,
      `LEFTB:${PAD}Printed On: ${dateTimeStr}`,
      "BLANK",
      "CENTERB:Thank you! Visit again.",
      "CUT",
    ];

    return lines;
  };

  const handleConfirmPay = async () => {
    if (!order) {
return;
}
    const { total } = computeTotals(order);
    const discountAmt = +((total * (discountPercent || 0)) / 100).toFixed(2);
    const finalAmount = Math.max(0, +(total - discountAmt).toFixed(2));
    await setOrderPaid(order._id, { amount: finalAmount, method: "cash" });

    // print receipt using structured ESC/POS bill format
    try {
      const receiptLines = buildReceiptLines(order, tableNum, discountPercent || 0);
      console.log("Printing bill via printReceipt (no explicit printer provided)");
      // Do not pass a top-level printer name unless the caller explicitly chose one.
      // Let the main process use configured printer (KITCHEN_PRINTER_USB_NAME) or USB path.
      await printReceipt({ lines: receiptLines });
    } catch (e) {
      console.warn("Print failed", e);
    }

    // notify tables and clear
    window.dispatchEvent(new Event("orders-changed"));
    if (typeof window !== "undefined") {
      window.localStorage.removeItem("currentOrderId");
      window.localStorage.removeItem("currentTable");
    }
    setConfirmPayOpen(false);
    setOrder(null);
    window.location.hash = "#tables";
  };

  const handleConfirmCancel = async () => {
    if (!order) {
return;
}
    try {
      console.log("Confirm Cancel clicked for order", order._id);
      // Try to clear items and mark held; if updateOrder fails (rev conflict), fallback
      let updated: any;
      try {
        updated = await updateOrder({ ...order, items: [], status: "held" });
      } catch (e) {
        console.warn("updateOrder failed during cancel, falling back to cancelOrder", e);
        // first mark cancelled/held via cancelOrder
        await cancelOrder(order._id);
        // then fetch fresh copy and clear items
        const fresh = await getOrderById(order._id);
        if (!fresh) {
throw new Error("order-not-found-after-cancel");
}
        updated = await updateOrder({ ...fresh, items: [], status: "held" });
      }

      // notify other views (tables badges etc.)
      window.dispatchEvent(new Event("orders-changed"));

      // Keep currentOrderId/currentTable so Billing remains focused on this order
      // Close the modal and update the local order state to show an empty bill
      setConfirmCancelOpen(false);
      setOrder(updated);

      // don't call onClearBill() here and don't navigate away; stay on Billing page
    } catch (e) {
      console.error("Cancel failed", e);
      try {
        alert("Cancel failed: " + ((e as any)?.message || String(e)));
      } catch (_) {}
    }
  };

  // replace onPay and onCancel triggers to open modals
  const onPay = async () => {
    if (!order) {
return;
}
    setConfirmPayOpen(true);
  };

  const onCancel = async () => {
    if (!order) {
return;
}
    const hasItems = (order.items || []).length > 0;
    if (!hasItems) {
return;
} // nothing to cancel
    setConfirmCancelOpen(true);
  };

  React.useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.target as HTMLElement)?.tagName === "INPUT") {
return;
} // ignore while typing
      const key = e.key.toLowerCase();
      if (key === "t") {
        e.preventDefault();
        setTablesOpenPersisted(!tablesOpen);
        // if opening, focus search for immediate add
        setTimeout(() => searchRef.current?.focus(), 50);
        return;
      }
      if (key === "k") {
        e.preventDefault();
        sendKOT();
        return;
      }
      if (key === "p") {
        e.preventDefault();
        onPay();
      } else if (key === "c") {
        e.preventDefault();
        onCancel();
      } else if (key === "u" || (e.ctrlKey && key === "z")) {
        e.preventDefault();
        undoLast();
      } else if (/^[1-6]$/.test(key)) {
        const idx = Number(key) - 1;
        const fav = (items || []).filter((it) => it.available !== false)[idx];
        if (fav) {
          e.preventDefault();
          addToOrder(fav, qty);
        }
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [items, order, qty, lastAddedId]);

  const DEFAULT_KOT_PRINTER = "USB001";

  const buildKotLines = (previewData: any, orderData: any): string[] => {
    // KOT structured directives ΓÇö same ESC/POS pipeline as the bill receipt.
    // Font A on 80mm = 42 chars. 1-space left pad ΓåÆ 40 usable chars.
    // Item rows use LEFTDH (double-height bold) ΓÇö same height as hotel name but no width doubling.
    // Full 42-char width is still available for item rows.
    const PAD = "  ";
    // Normal (meta/header) columns
    const COL_ITEM = 32;
    const COL_QTY = 8;
    // Item row columns ΓÇö same as normal since no double-width
    const DW_ITEM = 32;
    const DW_QTY = 8;

    const rpad = (s: string, w: number) => (s.length >= w ? s.slice(0, w) : s.padEnd(w));
    const lpad = (s: string, w: number) => (s.length >= w ? s.slice(0, w) : s.padStart(w));

    const now = new Date();
    const pad2 = (n: number) => String(n).padStart(2, "0");
    const dateStr = `${pad2(now.getDate())}-${pad2(now.getMonth() + 1)}-${now.getFullYear()}`;
    const timeStr = now.toLocaleTimeString([], {
      hour: "2-digit",
      minute: "2-digit",
    });

    // Extract a short numeric KOT number from the kotId string
    const kotId = previewData.kotId || "-";
    const kotNumMatch = kotId.match(/(\d+)/g);
    const kotNum = kotNumMatch ? kotNumMatch[kotNumMatch.length - 1] : kotId;

    const lines: string[] = [
      // ΓöÇΓöÇ Header: hotel name (double-height bold centered) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      "BIGBOLD:HOTEL GURUKRUPA",
      // ΓöÇΓöÇ KOT label (bold centered) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      "SUBHEADER:---------KOT---------",
      // ΓöÇΓöÇ Order meta (left aligned, 1-space pad) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      `LEFT:${PAD}KOT No: ${kotNum}`,
      `LEFT:${PAD}Date: ${dateStr}  Time: ${timeStr}`,
      ...(previewData.orderType === "table"
        ? [`LEFT:${PAD}Table No: ${previewData.tableNum || tableNum || "-"}`]
        : []),
      ...(previewData.orderType === "delivery"
        ? [
            `LEFT:${PAD}Type: ${previewData.platform || "Delivery"}`,
            ...(previewData.platformCode ? [`LEFT:${PAD}Code: ${previewData.platformCode}`] : []),
          ]
        : []),
      ...(previewData.orderType === "takeaway" && previewData.customerName
        ? [`LEFT:${PAD}Customer: ${previewData.customerName}`]
        : []),
      "SEP",
      // ΓöÇΓöÇ Column header (normal size) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      `LEFT:${PAD}${rpad("Item", COL_ITEM)}${lpad("Qty", COL_QTY)}`,
      "SEP",
      // ΓöÇΓöÇ Item rows (double-width + double-height Γëê 2├ù bigger font) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
      ...(orderData.items || []).map((it: any) => {
        const name = rpad(String(it.name || "").trim(), DW_ITEM);
        const qty = lpad(String(it.qty != null ? it.qty : 1), DW_QTY);
        return `LEFTDH:${PAD}${name}${qty}`;
      }),
      ...(orderData.notes ? [`SEP`, `LEFT:${PAD}Note: ${orderData.notes}`] : []),
      "BLANK",
      "CUT",
    ];

    return lines;
  };

  const printKotForOrder = async (
    previewData: any,
    orderData: any,
    printerName = DEFAULT_KOT_PRINTER,
  ) => {
    const lines = buildKotLines(previewData, orderData);
    await printKOT({ lines, printer: printerName });
  };

  const markKotAsPrinted = async (existingOrder: any) => {
    if (!existingOrder || !existingOrder._id) {
return;
}

    for (let attempt = 0; attempt < 2; attempt += 1) {
      try {
        const currentOrder = await getOrderById(existingOrder._id);
        if (!currentOrder) {
return;
}

        const updatedOrder = await updateOrder({
          ...currentOrder,
          kotSent: true,
          kotPrinted: true,
          updatedAt: Date.now(),
        });

        setOrder(updatedOrder);
        window.dispatchEvent(new Event("orders-changed"));
        return updatedOrder;
      } catch (e: any) {
        if (e?.status === 409 && attempt === 0) {
          // conflict, force one retry with fresh revision
          continue;
        }
        throw e;
      }
    }
  };

  // Clicking the KOT button now prints immediately (with optional preview data stored for audit)
  const sendKOT = async () => {
    if (!order) {
return alert("Open an order/table first");
}

    const kotId = `KOT-${String(Date.now()).slice(-6)}-${Math.random()
      .toString(36)
      .slice(2, 6)
      .toUpperCase()}`;

    const meta = (order && (order.meta || {})) || {};
    const platformRaw = (meta.platform || meta.orderSource || meta.source || "").toString();
    const platform = platformRaw.toLowerCase();

    const orderType = (
      order.orderType ||
      (tableNum
        ? "table"
        : meta.parcelName || meta.customerName
        ? "takeaway"
        : platform.includes("swiggy") || platform.includes("zomato")
        ? "delivery"
        : "takeaway")
    )
      .toString()
      .toLowerCase();

    const preview = {
      kotId,
      orderType,
      platform: platformRaw || "",
      platformCode: meta.code || meta.orderCode || meta.reference || "",
      customerName: meta.parcelName || meta.customerName || "",
      items: (order.items || []).map((it: any) => ({
        name: it.name,
        qty: it.qty,
      })),
      tableNum,
    } as any;

    setKotPreviewData(preview);
    setKotPreviewOpen(false); // no forced modal step before printing

    try {
      await printKotForOrder(preview, order, DEFAULT_KOT_PRINTER);
      await markKotAsPrinted(order);
      console.log("KOT printed");
    } catch (e) {
      console.warn("KOT print failed", e);
      try {
        alert("KOT print failed");
      } catch (_) {}
    }
  };

  const onConfirmPrintKOT = async () => {
    if (!kotPreviewData || !order) {
      setKotPreviewOpen(false);
      return;
    }

    try {
      await printKotForOrder(kotPreviewData, order, DEFAULT_KOT_PRINTER);
      await markKotAsPrinted(order);
      console.log("KOT printed");
    } catch (e) {
      console.warn("KOT print failed", e);
      try {
        alert("KOT print failed");
      } catch (_) {}
    }

    setKotPreviewOpen(false);
  };

  const { subtotal, cgst, sgst, gstTotal, total } = computeTotals(order);

  // discount calculation applied to total
  const discountAmt = +((total * (discountPercent || 0)) / 100).toFixed(2);
  const finalTotal = Math.max(0, +(total - discountAmt).toFixed(2));

  const favorites = (items || []).filter((it) => it.available !== false).slice(0, 6);

  // whether Cancel action is enabled (order present with at least one item)
  const canCancel = Boolean(order && (order.items || []).length > 0);

  // ΓöÇΓöÇ Quick-action helpers for takeaway / delivery orders ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  // Derive orderType for the active order
  const activeOrderType: "table" | "takeaway" | "delivery" = (() => {
    if (!order) {
return "table";
}
    if (order.orderType) {
return order.orderType as any;
}
    const meta = order.meta || {};
    const p = (meta.platform || meta.orderSource || meta.source || "").toString().toLowerCase();
    if (p.includes("swiggy") || p.includes("zomato")) {
return "delivery";
}
    if (tableNum) {
return "table";
}
    return "takeaway";
  })();

  // Mark the active order as ready (status = "ready"), persist to DB
  const markReady = async () => {
    if (!order) {
return;
}
    try {
      const updated = await updateOrder({ ...order, status: "ready" });
      setOrder(updated);
      window.dispatchEvent(new Event("orders-changed"));
    } catch (e) {
      console.warn("markReady failed", e);
      alert("Could not mark as ready: " + ((e as any)?.message || String(e)));
    }
  };

  // Assign rider modal state
  const [assignRiderOpen, setAssignRiderOpen] = React.useState(false);
  const [riderName, setRiderName] = React.useState("");
  const [riderPhone, setRiderPhone] = React.useState("");

  const confirmAssignRider = async () => {
    if (!order) {
return;
}
    try {
      const updated = await updateOrder({
        ...order,
        status: "assigned",
        meta: {
          ...(order.meta || {}),
          rider: { name: riderName.trim(), phone: riderPhone.trim() },
        },
      });
      setOrder(updated);
      setAssignRiderOpen(false);
      setRiderName("");
      setRiderPhone("");
      window.dispatchEvent(new Event("orders-changed"));
    } catch (e) {
      console.warn("assignRider failed", e);
      alert("Could not assign rider: " + ((e as any)?.message || String(e)));
    }
  };

  // Print an aggregator-style receipt for the active delivery order
  const printAggregatorReceipt = async () => {
    if (!order) {
return;
}
    try {
      const meta = order.meta || {};
      const platform = (meta.platform || meta.orderSource || "Delivery").toString();
      const code = meta.code || meta.orderCode || meta.reference || order._id || "";
      const rider = meta.rider
        ? `Rider: ${meta.rider.name || ""} ${meta.rider.phone || ""}`.trim()
        : "";
      const { subtotal: s, cgst: c, sgst: sg, total: t } = computeTotals(order);
      const disc = +((t * (discountPercent || 0)) / 100).toFixed(2);
      const finalAmt = Math.max(0, +(t - disc).toFixed(2));
      const lines = [
        `=== ${platform} ORDER ===`,
        `Order Code: ${code}`,
        rider,
        `Status: ${order.status || "open"}`,
        ``,
        ...(order.items || []).map(
          (it: any) => `${it.qty} x ${it.name}  Γé╣${(it.qty || 0) * (it.rate || 0)}`,
        ),
        ``,
        `Subtotal: Γé╣${s}`,
        `CGST (9%): Γé╣${c}`,
        `SGST (9%): Γé╣${sg}`,
        ...(disc > 0 ? [`Discount: -Γé╣${disc}`] : []),
        `Total: Γé╣${finalAmt}`,
        ``,
        `Thank you!`,
      ].filter((l) => l !== undefined);
      await printReceipt({ text: lines.join("\n") });
    } catch (e) {
      console.warn("printAggregatorReceipt failed", e);
      alert("Print failed: " + ((e as any)?.message || String(e)));
    }
  };

  const updateOrderQty = async (id: string, delta: number) => {
    if (!order) {
return;
}
    const updated = await updateOrder({
      ...order,
      items: order.items.map((l: any) =>
        l.id === id ? { ...l, qty: Math.max(1, l.qty + delta) } : l,
      ),
    });
    setOrder(updated);
    setTimeout(() => searchRef.current?.focus(), 10);
  };

  return (
    <>
      <div className={styles.page}>
        {/* Billing top bar */}
        <div className={styles.headerBar}>
          <div className={styles.headerLeft}>
            <button
              onClick={() => setTablesOpenPersisted(!tablesOpen)}
              aria-label="Toggle tables"
              title="Toggle tables (T)"
              className={styles.toggleBtn}
            >
              Γÿ░
            </button>
            <div>
              <div className={styles.headerTitle}>
                {tableNum
                  ? `Table ${tableNum}`
                  : order && activeOrderType === "delivery"
                  ? `≡ƒÜÜ ${(
                      order.meta?.platform ||
                      order.meta?.orderSource ||
                      "Delivery"
                    ).toString()}${order.meta?.code ? ` #${order.meta.code}` : ""}`
                  : order && activeOrderType === "takeaway"
                  ? `≡ƒ¢ì∩╕Å ${order.meta?.parcelName || order.meta?.customerName || "Takeaway"}`
                  : "Billing"}
              </div>
              {order && (
                <div className={styles.headerMeta}>
                  {(order.items || []).length} item
                  {(order.items || []).length !== 1 ? "s" : ""}
                  {order.status && order.status !== "open" && (
                    <span
                      style={{
                        marginLeft: 8,
                        fontWeight: 700,
                        color:
                          order.status === "ready"
                            ? "#0ea5e9"
                            : order.status === "assigned"
                            ? "#7c3aed"
