}

import React from "react";
import styles from "../Billing.module.css";

interface ModalProps {
  size?: "small" | "medium" | "large" | "default";
  onClose?: () => void;
  children?: React.ReactNode;
}

export default function Modal({
  size = "default",
  onClose,
  children,
}: ModalProps) {
  const cls =
    size === "small"
      ? styles.modalDialogSmall
      : size === "medium"
      ? styles.modalDialogMedium
      : size === "large"
      ? styles.modalDialogLarge
      : styles.modalDialog;
  return (
    <div className={styles.modalOverlay}>
      <div className={cls}>{children}</div>
    </div>
  );
}

import React from "react";
import styles from "../Billing.module.css";

interface Props {
  it: any;
  editingQty: Record<string, string>;
  editingRate: Record<string, string>;
  setEditingQty: (v: any) => void;
  setEditingRate: (v: any) => void;
  commitQty: (id: string) => Promise<void>;
  commitRate: (id: string) => Promise<void>;
  removeLine: (id: string) => Promise<void>;
  updateOrderQty: (id: string, delta: number) => Promise<void>;
}

export default function OrderItem({
  it,
  editingQty,
  editingRate,
