import React from "react";

interface Customer {
  id: string;
  name: string;
  phone: string;
  createdAt: string;
}

const STORAGE_KEY = "rp_customers_v1";

export default function Customers() {
  const [customers, setCustomers] = React.useState<Customer[]>(() => {
    try {
      const raw =
        typeof window !== "undefined"
          ? window.localStorage.getItem(STORAGE_KEY)
          : null;
      return raw ? JSON.parse(raw) : [];
    } catch (e) {
      return [];
    }
  });

  const [name, setName] = React.useState("");
  const [phone, setPhone] = React.useState("");
  const [nameError, setNameError] = React.useState<string | null>(null);
  const [phoneError, setPhoneError] = React.useState<string | null>(null);
  const [toast, setToast] = React.useState<string | null>(null);

  React.useEffect(() => {
    try {
      window.localStorage.setItem(STORAGE_KEY, JSON.stringify(customers));
    } catch (e) {}
  }, [customers]);

  const showToast = (t: string) => {
    setToast(t);
    setTimeout(() => setToast(null), 2500);
  };

  const validatePhone = (p: string) => {
    const cleaned = (p || "").replace(/[^0-9]/g, "");
    // Strict India: exactly 10 digits and starts with 6-9
    return /^[6-9][0-9]{9}$/.test(cleaned);
  };

  const addCustomer = () => {
    // clear previous errors
    setNameError(null);
    setPhoneError(null);

    const trimmedName = name.trim();
    if (trimmedName.length < 2) {
      setNameError("Name must be at least 2 characters");
      return;
    }

    const cleaned = phone.replace(/[^0-9]/g, "");
    if (!validatePhone(cleaned)) {
      setPhoneError(
        "Please enter a valid 10-digit Indian mobile number (starts with 6-9)",
      );
      return;
    }

    // check duplicate phone
    if (customers.some((c) => c.phone === cleaned)) {
      setPhoneError("This phone number is already added");
      return;
    }
    const c: Customer = {
      id: `c_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      name: name.trim(),
      phone: cleaned,
      createdAt: new Date().toISOString(),
    };
    setCustomers((s) => [c, ...s]);
    setName("");
    setPhone("");
    showToast("Customer added");
  };

  const removeCustomer = (id: string) => {
    setCustomers((s) => s.filter((c) => c.id !== id));
    showToast("Customer removed");
  };

  return (
    <div style={{ padding: 20 }}>
      <h2
        style={{ margin: 0, fontSize: 22, fontWeight: 800, color: "#111827" }}
      >
        Customers
      </h2>
      <p style={{ margin: "3px 0 0", fontSize: 13, color: "#9ca3af" }}>
        Collect customer name & phone for promotions
      </p>

      <div
        style={{
          marginTop: 14,
          display: "flex",
          gap: 8,
          alignItems: "flex-start",
        }}
      >
        <div style={{ flex: 1 }}>
          <input
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              if (nameError) {
setNameError(null);
}
            }}
            placeholder="Customer name"
            style={{
              padding: "10px 12px",
              borderRadius: 10,
              border: `1px solid ${nameError ? "#ef4444" : "#e5e7eb"}`,
              width: "100%",
              boxSizing: "border-box",
            }}
          />
          {nameError && (
            <div style={{ color: "#ef4444", fontSize: 12, marginTop: 6 }}>
              {nameError}
            </div>
          )}
        </div>

        <div style={{ width: 200 }}>
          <input
            value={phone}
            onChange={(e) => {
              setPhone(e.target.value);
              if (phoneError) {
setPhoneError(null);
}
            }}
            placeholder="Phone number (10 digits)"
            style={{
              padding: "10px 12px",
              borderRadius: 10,
              border: `1px solid ${phoneError ? "#ef4444" : "#e5e7eb"}`,
              width: "100%",
              boxSizing: "border-box",
            }}
          />
          {phoneError && (
            <div style={{ color: "#ef4444", fontSize: 12, marginTop: 6 }}>
              {phoneError}
            </div>
          )}
        </div>

        <div style={{ display: "flex", alignItems: "center" }}>
          <button
            onClick={addCustomer}
            disabled={
              !name.trim() ||
              !validatePhone(phone) ||
              Boolean(nameError) ||
              Boolean(phoneError)
            }
            style={{
              padding: "10px 14px",
              borderRadius: 10,
              background:
                !name.trim() || !validatePhone(phone) || nameError || phoneError
                  ? "#f3f4f6"
                  : "#ff9f00",
              color:
                !name.trim() || !validatePhone(phone) || nameError || phoneError
                  ? "#9ca3af"
                  : "#fff",
              border: "none",
              fontWeight: 700,
              cursor:
                !name.trim() || !validatePhone(phone) || nameError || phoneError
                  ? "not-allowed"
                  : "pointer",
            }}
          >
            Add
          </button>
        </div>
      </div>

      <div style={{ marginTop: 18 }}>
        {customers.length === 0 ? (
          <div style={{ color: "#9ca3af" }}>No customers yet.</div>
        ) : (
          <div style={{ display: "grid", gap: 10 }}>
            {customers.map((c) => (
              <div
                key={c.id}
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  background: "#fff",
                  padding: 12,
                  borderRadius: 10,
                  border: "1px solid #f3f4f6",
                }}
              >
                <div>
                  <div style={{ fontWeight: 700 }}>{c.name}</div>
                  <div style={{ color: "#6b7280", fontSize: 13 }}>
                    {c.phone}
                  </div>
                </div>
                <div style={{ display: "flex", gap: 8 }}>
                  <button
                    onClick={() => {
                      // copy phone to clipboard for quick use
                      try {
                        navigator.clipboard?.writeText(c.phone);
                        showToast("Phone copied");
                      } catch (e) {
                        showToast("Copied");
                      }
                    }}
                    style={{
                      padding: "8px 10px",
                      borderRadius: 8,
                      border: "1px solid #e5e7eb",
                      background: "#fff",
                    }}
                  >
                    Copy
                  </button>
                  <button
                    onClick={() => removeCustomer(c.id)}
                    style={{
                      padding: "8px 10px",
                      borderRadius: 8,
                      border: "none",
                      background: "#ef4444",
                      color: "#fff",
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {toast && (
        <div
          style={{
            position: "fixed",
            right: 20,
            bottom: 20,
            background: "#111827",
            color: "#fff",
            padding: "10px 14px",
            borderRadius: 8,
          }}
        >
          {toast}
        </div>
      )}
    </div>
  );
}

import React from "react";
import { db as pouchDb, getOrderById } from "../../../app/db/pouch";
import { printReceipt } from "../../../app/services/printer";

type UIOrder = {
  uid: string;
  displayId: number;
  table: number | null;
  total: number;
  items: number;
  method: string;
  time: number;
  _id?: string;
  _rev?: string;
};

const samples = Array.from({ length: 8 }).map((_, i) => ({
  id: i + 1,
  table: (i % 6) + 1,
  total: Math.round(200 + i * 137),
  items: 2 + (i % 5),
  method: i % 3 === 0 ? "UPI" : "Cash",
  time: Date.now() - i * 3600000,
}));

export default function History() {
  const [search, setSearch] = React.useState("");
  // selection state (uid strings)
  const [selected, setSelected] = React.useState<string[]>([]);
  const [confirmSelectedOpen, setConfirmSelectedOpen] = React.useState(false);
  const [confirmDeleteAllOpen, setConfirmDeleteAllOpen] = React.useState(false);
  const [lastDeleted, setLastDeleted] = React.useState<any[] | null>(null);
  const [undoToastVisible, setUndoToastVisible] = React.useState(false);
  // page size state (used by paging functions)
  const [pageSize, setPageSize] = React.useState(10);
  // cap the number of cached pages to avoid unbounded memory growth
  const MAX_PAGES = 5;
  // whether more results are available from the DB
  const [hasMore, setHasMore] = React.useState(true);
  // page-cache for cursor-backed pagination. Each entry is an array of UIOrder for that page.
  const [pages, setPages] = React.useState<UIOrder[][]>([
    samples.map((s) => ({
      uid: `sample:${s.id}`,
      displayId: s.id,
      table: s.table,
      total: s.total,
      items: s.items,
      method: s.method,
      time: s.time,
    })),
  ]);
  const [currentPageIndex, setCurrentPageIndex] = React.useState(0);
  const [loadingPage, setLoadingPage] = React.useState(false);

  // whether pouchdb-find is available
  const hasFind = React.useMemo(
    () => typeof (pouchDb as any).find === "function",
    [],
  );

  // sentinel for infinite scroll
  const sentinelRef = React.useRef<HTMLDivElement | null>(null);

  // small helper to convert DB docs to UIOrder
  const docsToUI = (docs: any[]) =>
    docs.map((d: any, idx: number) => {
      const total = (d.items || []).reduce(
        (acc: number, it: any) => acc + (it.qty || 0) * (it.rate || 0),
        0,
      );
      return {
        uid: d._id || d.id || String(Math.random()),
        _id: d._id,
        _rev: d._rev,
        displayId: idx + 1,
        table: d.tableId ?? (d as any).table ?? null,
        total,
        items: (d.items || []).length,
        method:
          (d.payments && d.payments.length && d.payments[0].method) || "Cash",
        time: d.updatedAt || d.createdAt || Date.now(),
      } as UIOrder;
    });

  // helper to safely build a regex for Mango $regex
  const escapeForRegex = (s: string) =>
    s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

  const buildSelector = (searchTerm?: string) => {
    if (!searchTerm || !String(searchTerm).trim()) {
return { type: "order" };
}
    const s = String(searchTerm).trim();
    const isNumber = /^\d+$/.test(s);
    const regex = escapeForRegex(s);
    const or: any[] = [];
    if (isNumber) {
or.push({ tableId: Number(s) });
}
    // search by _id (order id) or method (UPI/Cash)
    or.push({ _id: { $regex: regex } });
    or.push({ method: { $regex: regex } });
    return { type: "order", $or: or };
  };

  // Fallback query: when pouchdb-find cannot plan a query (no index),
  // perform an in-memory query using allDocs and simple filtering/sorting.
  const fallbackQuery = async (
    pageSizeLocal: number,
    searchTerm?: string,
    lastCreated?: number,
    lastId?: string,
  ) => {
    const all = (await pouchDb.allDocs({ include_docs: true })) as any;
    let docs = (all.rows || []).map((r: any) => r.doc).filter(Boolean);
    docs = docs.filter((d: any) => d && d.type === "order");
    if (searchTerm && String(searchTerm).trim()) {
      const s = String(searchTerm).trim();
      const isNumber = /^\d+$/.test(s);
      docs = docs.filter((d: any) => {
        if (isNumber && d.tableId !== undefined && d.tableId !== null) {
          if (Number(d.tableId) === Number(s)) {
return true;
}
        }
        const idMatch = String(d._id || "").includes(s);
        const method =
          (d.payments && d.payments[0] && d.payments[0].method) ||
          d.method ||
          "";
        const methodMatch = String(method)
          .toLowerCase()
          .includes(s.toLowerCase());
        return idMatch || methodMatch;
      });
    }
    // sort by createdAt desc, then _id desc
    docs.sort((a: any, b: any) => {
      const ta = a.updatedAt || a.createdAt || 0;
      const tb = b.updatedAt || b.createdAt || 0;
      if (ta !== tb) {
return tb - ta;
}
      const ida = a._id || "";
      const idb = b._id || "";
      return idb.localeCompare(ida);
    });
    if (lastCreated !== undefined && lastId !== undefined) {
      docs = docs.filter((d: any) => {
        const t = d.updatedAt || d.createdAt || 0;
        const id = d._id || "";
        if (t < lastCreated) {
return true;
}
        if (t === lastCreated && id < lastId) {
return true;
}
        return false;
      });
    }
    const slice = docs.slice(0, pageSizeLocal || pageSize);
    return { docs: slice };
  };

  // helper to load the first page (most recent orders)
  const loadFirstPage = async (
    pageSizeLocal = pageSize,
    searchTerm?: string,
  ) => {
    setLoadingPage(true);
    try {
      // ensure index on createdAt/_id for efficient paging
      try {
        if ((pouchDb as any).createIndex) {
          await (pouchDb as any).createIndex({
            index: {
              fields: ["type", "createdAt", "_id", "tableId", "method"],
            },
          });
        }
      } catch (e) {
        // non-fatal if index creation fails
        console.warn("History: createIndex failed", e);
      }

      const selector = buildSelector(searchTerm);
      let res: any;
      if (hasFind) {
        try {
          res = (await (pouchDb as any).find({
            selector,
            sort: [{ createdAt: "desc" }, { _id: "desc" }],
            limit: pageSizeLocal,
          })) as any;
        } catch (err: any) {
          console.warn(
            "History: pouch find failed, falling back to allDocs:",
            err?.message || err,
          );
          res = await fallbackQuery(pageSizeLocal, searchTerm);
        }
      } else {
        // plugin not present; use fallback
        res = await fallbackQuery(pageSizeLocal, searchTerm);
      }
      const ui = docsToUI(res.docs || []);
      setPages([ui]);
      setCurrentPageIndex(0);
      // if fewer than requested, there are no more results
      setHasMore(((res.docs || []) as any[]).length === pageSizeLocal);
    } catch (e) {
      console.warn("History: failed to load first page", e);
    } finally {
      setLoadingPage(false);
    }
  };

  const loadNextPage = async (
    pageSizeLocal = pageSize,
    searchTerm?: string,
  ) => {
    // if we already have the next page cached, just advance index
    if (currentPageIndex < pages.length - 1) {
      setCurrentPageIndex((i) => i + 1);
      return;
    }
    const cur = pages[currentPageIndex] || [];
    if (cur.length === 0) {
return;
}
    const last = cur[cur.length - 1];
    const lastCreated = last.time;
    const lastId = last._id || last.uid;
    setLoadingPage(true);
    try {
      const baseSelector = buildSelector(searchTerm);
      // merge baseSelector with paging conditions
      const selector: any = { type: "order" };
      // start with search selector if present
      if (baseSelector.$or) {
        selector.$and = [{ $or: baseSelector.$or }];
      }
      // add paging range condition
      selector.$and = selector.$and || [];
      selector.$and.push({
        $or: [
          { createdAt: { $lt: lastCreated } },
          { createdAt: { $eq: lastCreated }, _id: { $lt: lastId } },
        ],
      });
      let res: any;
      if (hasFind) {
        try {
          res = (await (pouchDb as any).find({
            selector,
            sort: [{ createdAt: "desc" }, { _id: "desc" }],
            limit: pageSizeLocal,
          })) as any;
        } catch (err: any) {
          console.warn(
            "History: pouch find failed for next page, falling back to allDocs:",
            err?.message || err,
          );
          res = await fallbackQuery(
            pageSizeLocal,
            searchTerm,
            lastCreated,
            lastId,
          );
        }
      } else {
        res = await fallbackQuery(
          pageSizeLocal,
          searchTerm,
          lastCreated,
          lastId,
        );
      }
      let resToUse = res;
      try {
        // if find returned normally use it, else fall back
        if (!resToUse || !Array.isArray(resToUse.docs)) {
          resToUse = await fallbackQuery(
            pageSizeLocal,
            searchTerm,
            lastCreated,
            lastId,
          );
        }
      } catch (e) {
        console.warn("History: fallbackQuery failed for next page", e);
        resToUse = { docs: [] };
      }
      const ui = docsToUI(resToUse.docs || []);
      if (ui.length) {
        // append new page but cap total cached pages
        const prevLen = pages.length;
        const newLen = Math.min(prevLen + 1, MAX_PAGES);
        const newIndex = newLen - 1;
        setPages((prev) => {
          const copy = prev.slice();
          copy.push(ui);
          while (copy.length > MAX_PAGES) {
copy.shift();
}
          return copy;
        });
        setCurrentPageIndex(newIndex);
        setHasMore(ui.length === pageSizeLocal);
      }
    } catch (e) {
      console.warn("History: failed to load next page", e);
    } finally {
      setLoadingPage(false);
    }
  };

  // load more (incremental append) ΓÇö fetch next batch and append into current page (useful for infinite scroll)
  const loadMore = async (pageSizeLocal = pageSize, searchTerm?: string) => {
    const cur = pages[currentPageIndex] || [];
    if (cur.length === 0) {
return;
}
    const last = cur[cur.length - 1];
    const lastCreated = last.time;
    const lastId = last._id || last.uid;
    setLoadingPage(true);
    try {
      const baseSelector = buildSelector(searchTerm);
      const selector: any = { type: "order" };
      if (baseSelector.$or) {
        selector.$and = [{ $or: baseSelector.$or }];
      }
      selector.$and = selector.$and || [];
      selector.$and.push({
        $or: [
          { createdAt: { $lt: lastCreated } },
          { createdAt: { $eq: lastCreated }, _id: { $lt: lastId } },
        ],
      });
      let res: any;
      if (hasFind) {
        try {
          res = (await (pouchDb as any).find({
            selector,
            sort: [{ createdAt: "desc" }, { _id: "desc" }],
            limit: pageSizeLocal,
          })) as any;
        } catch (err: any) {
          console.warn(
            "History: pouch find failed for loadMore, falling back to allDocs:",
            err?.message || err,
          );
          res = await fallbackQuery(
            pageSizeLocal,
            searchTerm,
            lastCreated,
            lastId,
          );
        }
      } else {
        res = await fallbackQuery(
          pageSizeLocal,
          searchTerm,
          lastCreated,
          lastId,
        );
      }
      let resToUse = res;
      try {
        if (!resToUse || !Array.isArray(resToUse.docs)) {
          resToUse = await fallbackQuery(
            pageSizeLocal,
            searchTerm,
            lastCreated,
            lastId,
          );
        }
      } catch (e) {
        console.warn("History: fallbackQuery failed for loadMore", e);
        resToUse = { docs: [] };
      }
      const ui = docsToUI(resToUse.docs || []);
      if (ui.length) {
        setPages((prev) => {
          const copy = prev.slice();
          copy[currentPageIndex] = (copy[currentPageIndex] || []).concat(ui);
          return copy;
        });
        setHasMore(ui.length === pageSizeLocal);
      }
    } catch (e) {
      console.warn("History: failed to load more", e);
    } finally {
      setLoadingPage(false);
    }
  };

  const loadPrevPage = () => {
    if (currentPageIndex > 0) {
setCurrentPageIndex((i) => i - 1);
}
  };

  // load first page on mount
  React.useEffect(() => {
    let mounted = true;
    (async () => {
      if (!mounted) {
return;
}
      await loadFirstPage(pageSize);
    })();
    return () => {
      mounted = false;
    };
  }, []);

  // create explicit indexes on app startup (best-effort)
  React.useEffect(() => {
    (async () => {
      try {
        if ((pouchDb as any).createIndex) {
          await (pouchDb as any).createIndex({
            index: {
              fields: ["type", "createdAt", "_id", "tableId", "method"],
            },
          });
          await (pouchDb as any).createIndex({
            index: { fields: ["type", "method"] },
          });
        }
      } catch (e) {
        console.warn("History: index create on startup failed", e);
      }
    })();
  }, []);

  // derived current page items
  const pageItems = pages[currentPageIndex] || [];
  const page = currentPageIndex + 1;
  const pageCount = Math.max(1, pages.length);

  const toggleSelect = (uid: string) => {
    setSelected((prev) =>
      prev.includes(uid) ? prev.filter((x) => x !== uid) : [...prev, uid],
    );
  };

  const selectAllVisible = () => {
    // operate on current page items only
    const visibleUids = pageItems.map((v) => v.uid);
    const allSelected =
      visibleUids.length > 0 &&
      visibleUids.every((id) => selected.includes(id));
    if (allSelected) {
setSelected((prev) => prev.filter((id) => !visibleUids.includes(id)));
} else {
setSelected((prev) => Array.from(new Set([...prev, ...visibleUids])));
}
  };

  const deleteSelected = async () => {
    if (selected.length === 0) {
return;
}
    const toDelete = pageItems.filter((o) => selected.includes(o.uid));
    const remainingInPage = pageItems.filter((o) => !selected.includes(o.uid));
    // attempt to remove from DB for docs that have _id/_rev
    const dbRemovals: any[] = [];
    for (const d of toDelete) {
      if (d._id && d._rev) {
        dbRemovals.push({ _id: d._id, _rev: d._rev, _deleted: true });
      }
    }
    try {
      if (dbRemovals.length) {
await pouchDb.bulkDocs(dbRemovals as any);
}
    } catch (e) {
      console.warn("History: failed to delete from DB", e);
    }
    setLastDeleted(toDelete);
    // replace current page with remaining entries
    setPages((prev) => {
      const copy = prev.slice();
      copy[currentPageIndex] = remainingInPage;
      return copy;
    });
    setSelected([]);
    setConfirmSelectedOpen(false);
    setUndoToastVisible(true);
    // hide undo after 6s
    setTimeout(() => setUndoToastVisible(false), 6000);
  };

  const deleteAll = async () => {
    // delete all orders from DB (and clear cache)
    // fetch all order docs to delete
    let allDocs: any[] = [];
    try {
      const res = (await (pouchDb as any).find({
        selector: { type: "order" },
        fields: ["_id", "_rev"],
      })) as any;
      allDocs = res.docs || [];
    } catch (e) {
      console.warn("History: failed to list all orders for delete", e);
    }
    if (allDocs.length === 0 && pages.flat().length === 0) {
return;
}
    const toDelete = allDocs.length ? allDocs : pages.flat();
    const dbRemovals = (toDelete as any[])
      .filter((d) => d._id && d._rev)
      .map((d) => ({ _id: d._id, _rev: d._rev, _deleted: true }));
    try {
      if (dbRemovals.length) {
await pouchDb.bulkDocs(dbRemovals as any);
}
    } catch (e) {
      console.warn("History: failed to delete all from DB", e);
    }
    setLastDeleted(toDelete as any[]);
    setPages([[]]);
    setCurrentPageIndex(0);
    setSelected([]);
    setConfirmDeleteAllOpen(false);
    setUndoToastVisible(true);
    setTimeout(() => setUndoToastVisible(false), 6000);
  };

  const undoDelete = async () => {
    if (!lastDeleted) {
return;
}
    // re-insert DB docs (remove rev/_deleted flags) and update UI
    const toReinsert = lastDeleted
      .map((d) => {
        if (d._id) {
          const copy = { ...d } as any;
          delete copy._rev;
          delete copy._deleted;
          return copy;
        }
        return null;
      })
      .filter(Boolean) as any[];
    try {
      if (toReinsert.length) {
await pouchDb.bulkDocs(toReinsert);
}
    } catch (e) {
      console.warn("History: failed to undo DB deletions", e);
    }
    // prepend the restored items into the first page cache and reset to first page
    setPages((prev) => [docsToUI(toReinsert), ...prev.slice(1)]);
    setCurrentPageIndex(0);
    setLastDeleted(null);
    setUndoToastVisible(false);
  };

  // preview modal state
  const [previewOpen, setPreviewOpen] = React.useState(false);
  const [previewLoading, setPreviewLoading] = React.useState(false);
  const [previewFull, setPreviewFull] = React.useState<any | null>(null);
  // control for simple enter/exit animation
  const [modalVisible, setModalVisible] = React.useState(false);

  // when modal mounts, trigger visibility for animation and attach Escape key handler
  React.useEffect(() => {
    let startTimer: any = null;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        // animate-close
        closePreview();
      }
    };
    if (previewOpen) {
      // start hidden -> then visible to allow CSS transition
      setModalVisible(false);
      startTimer = setTimeout(() => setModalVisible(true), 10);
      window.addEventListener("keydown", onKey);
    }
    return () => {
      if (startTimer) {
clearTimeout(startTimer);
}
      window.removeEventListener("keydown", onKey);
    };
  }, [previewOpen]);

  const closePreview = () => {
    // animate hide, then unmount after transition
    setModalVisible(false);
    setTimeout(() => {
      setPreviewOpen(false);
      setPreviewFull(null);
      setPreviewLoading(false);
    }, 220);
  };

  const openOrder = async (o: UIOrder) => {
    // Open a read-only preview modal for the selected history row
    setPreviewLoading(true);
    setPreviewFull(null);
    setPreviewOpen(true);
    try {
      if ((o as any)._id) {
        const full = await getOrderById((o as any)._id);
        if (full) {
setPreviewFull(full);
} else {
setPreviewFull({
            _id: (o as any)._id,
            items: [],
            tableId: o.table,
            createdAt: o.time,
          });
}
      } else {
        // synthetic preview for sample rows
        setPreviewFull({
          _id: o.uid,
          items: [],
          tableId: o.table,
          createdAt: o.time,
        });
      }
    } catch (e) {
      console.error("openOrder failed", e);
      setPreviewFull({
        _id: o.uid,
        items: [],
        tableId: o.table,
        createdAt: o.time,
      });
    } finally {
      setPreviewLoading(false);
    }
  };

  const reprintOrder = async (o: UIOrder | any) => {
    try {
      const id = (o && ((o as any)._id || (o as any).uid)) as
        | string
        | undefined;
      if (id) {
        const full = await getOrderById(id);
        if (full) {
          const total = (full.items || []).reduce(
            (acc: number, it: any) => acc + (it.qty || 0) * (it.rate || 0),
            0,
          );
          const lines = [
            `Receipt`,
            `Order: ${full._id || id}`,
            `Table: ${full.tableId ?? ""}`,
            ...(full.items || []).map(
              (it: any) =>
                `${it.qty}x ${it.name || it.title || "Item"} @ Γé╣${it.rate}`,
            ),
            `Total: Γé╣${total}`,
            `Thank you!`,
          ];
          await printReceipt({ text: lines.join("\n") });
          return;
        }
      }
      // fallback to UI info
      await printReceipt({
        text: `Receipt\nOrder: ${o.displayId || o.uid}\nTable: ${
          o.table || ""
        }\nTotal: Γé╣${o.total || 0}\nThank you!`,
      });
    } catch (e) {
      console.warn("Reprint failed", e);
      try {
        const msg =
          typeof e === "object" && e && (e as any).message
            ? (e as any).message
            : String(e);
        alert("Reprint failed: " + msg);
      } catch (_) {}
    }
  };

  // helper to compute subtotal / gst / total for a preview order with CGST and SGST split
  const computeTotals = (ord: any) => {
    const subtotal = (ord?.items || []).reduce(
      (s: number, it: any) => s + (it.qty || 0) * (it.rate || 0),
      0,
    );
    const gstTotal = +(subtotal * 0.18).toFixed(2);
    const cgst = +(gstTotal / 2).toFixed(2);
    const sgst = +(gstTotal / 2).toFixed(2);
    const total = +(subtotal + cgst + sgst).toFixed(2);
    return { subtotal, cgst, sgst, gstTotal, total };
  };

  return (
    <div style={{ padding: "20px 24px", maxWidth: 900, margin: "0 auto" }}>
      {/* Header */}
      <div
        style={{
          display: "flex",
          alignItems: "flex-start",
          justifyContent: "space-between",
          marginBottom: 20,
          flexWrap: "wrap",
          gap: 10,
        }}
      >
        <div>
          <h2
            style={{
              margin: 0,
              fontSize: 22,
              fontWeight: 800,
              color: "#111827",
            }}
          >
            Order History
          </h2>
          <p style={{ margin: "3px 0 0", fontSize: 13, color: "#9ca3af" }}>
            {pages.flat().length} recent orders
          </p>
        </div>
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          <input
            placeholder="Search table, order, methodΓÇª"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
loadFirstPage(pageSize, search);
}
            }}
            style={{
              padding: "9px 12px",
              borderRadius: 8,
              border: "1px solid #d1d5db",
              fontSize: 13,
              width: 180,
            }}
          />
          <button
            onClick={() => loadFirstPage(pageSize, search)}
            style={{ padding: "8px 10px", borderRadius: 8 }}
            title="Search"
          >
            Search
          </button>
          <button
            onClick={() => setConfirmDeleteAllOpen(true)}
            title="Delete all history"
            style={{
              padding: "8px 10px",
              background: "#ef4444",
              color: "#fff",
              border: "none",
              borderRadius: 8,
            }}
          >
            Delete all
          </button>
        </div>
      </div>

      {/* Column header */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "40px 60px 80px 1fr 80px 80px 120px 100px",
          padding: "7px 16px",
          borderRadius: 8,
          background: "#f3f4f6",
          fontSize: 11,
          fontWeight: 700,
          color: "#6b7280",
          letterSpacing: "0.06em",
          textTransform: "uppercase",
          marginBottom: 8,
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <input
            type="checkbox"
            aria-label="Select all"
            onChange={selectAllVisible}
            checked={
              pageItems.length > 0 &&
              pageItems.every((v) => selected.includes(v.uid))
            }
          />
        </div>
        <span>#</span>
        <span>Table</span>
        <span>Time</span>
        <span style={{ textAlign: "center" }}>Items</span>
        <span style={{ textAlign: "center" }}>Method</span>
        <span style={{ textAlign: "center" }}>Actions</span>
        <span style={{ textAlign: "right" }}>Total</span>
      </div>

      {/* Rows */}
      <div style={{ display: "grid", gap: 6 }}>
        {pageItems.length === 0 && (
          <div
            style={{ textAlign: "center", padding: "32px 0", color: "#9ca3af" }}
          >
            No orders found
          </div>
        )}
        {pageItems.map((s) => (
          <div
            key={s.uid}
            style={{
              display: "grid",
              gridTemplateColumns: "40px 60px 80px 1fr 80px 80px 120px 100px",
              alignItems: "center",
              padding: "13px 16px",
              borderRadius: 12,
              background: "#fff",
              border: "1px solid #f3f4f6",
              boxShadow: "0 1px 3px rgba(0,0,0,0.04)",
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <input
                type="checkbox"
                checked={selected.includes(s.uid)}
                onChange={() => toggleSelect(s.uid)}
              />
            </div>
            <span
              style={{
                fontSize: 13,
                color: "#9ca3af",
                fontFamily: "monospace",
              }}
            >
              #{s.displayId}
            </span>
            <span style={{ fontWeight: 700, fontSize: 14, color: "#111827" }}>
              Table {s.table}
            </span>
            <span style={{ fontSize: 13, color: "#6b7280" }}>
              {new Date(s.time).toLocaleString("en-IN", {
                day: "numeric",
                month: "short",
                hour: "2-digit",
                minute: "2-digit",
              })}
            </span>
            <span
              style={{
                textAlign: "center",
                fontSize: 13,
                color: "#374151",
                fontWeight: 600,
              }}
            >
              {s.items}
            </span>
            <div style={{ textAlign: "center" }}>
              <span
                style={{
                  fontSize: 11,
                  fontWeight: 700,
                  padding: "3px 8px",
                  borderRadius: 20,
                  background: s.method === "UPI" ? "#ede9fe" : "#f0fdf4",
                  color: s.method === "UPI" ? "#7c3aed" : "#16a34a",
                }}
              >
                {s.method}
              </span>
            </div>
            <div style={{ display: "flex", gap: 8, justifyContent: "center" }}>
              <button
                onClick={() => openOrder(s)}
                style={{
                  padding: "6px 8px",
                  borderRadius: 8,
                  border: "1px solid #e5e7eb",
                  background: "#fff",
                }}
              >
                Preview
              </button>
              <button
                onClick={() => reprintOrder(s)}
                style={{
                  padding: "6px 8px",
                  borderRadius: 8,
                  border: "none",
                  background: "#f3f4f6",
                }}
              >
                Reprint
              </button>
            </div>
            <span
              style={{
                textAlign: "right",
                fontWeight: 900,
                fontSize: 16,
                color: "#111827",
              }}
            >
              Γé╣{s.total}
            </span>
          </div>
        ))}
      </div>

      {/* Total row */}
      {pageItems.length > 0 && (
        <div
          style={{
            marginTop: 12,
            padding: "12px 16px",
            borderRadius: 12,
            background: "#fff7ed",
            border: "1.5px solid #fde68a",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
            <span style={{ fontWeight: 700, fontSize: 14, color: "#92400e" }}>
              {pageItems.length} orders
            </span>
            {selected.length > 0 && (
              <button
                onClick={() => setConfirmSelectedOpen(true)}
                style={{
                  padding: "8px 10px",
                  background: "#ef4444",
                  color: "#fff",
                  border: "none",
                  borderRadius: 8,
                }}
              >
                Delete selected ({selected.length})
              </button>
            )}
          </div>
          <span style={{ fontWeight: 900, fontSize: 18, color: "#92400e" }}>
            Γé╣
            {pageItems.reduce((s, o) => s + o.total, 0).toLocaleString("en-IN")}
          </span>
        </div>
      )}

      {/* Pagination controls */}
      {pageItems.length > 0 && (
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            margin: "8px 0 12px",
          }}
        >
          <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
            <button
              onClick={() => loadPrevPage()}
              disabled={currentPageIndex === 0}
              style={{ padding: "6px 8px", borderRadius: 8 }}
            >
              Prev
            </button>
            <button
              onClick={() => loadNextPage(undefined, search)}
              disabled={loadingPage}
              style={{ padding: "6px 8px", borderRadius: 8 }}
            >
              Next
            </button>
            {/* infinite scroll sentinel (Load more replaced by automatic fetch) */}
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <div ref={sentinelRef as any} style={{ width: 1, height: 1 }} />
              {loadingPage && (
                <div
                  aria-live="polite"
                  style={{
                    color: "#6b7280",
                    fontSize: 13,
                    padding: "6px 8px",
                    borderRadius: 6,
                  }}
                >
                  LoadingΓÇª
                </div>
              )}
            </div>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            {/* Minimal status + explicit Load more fallback for environments without IntersectionObserver */}
            <div style={{ color: "#6b7280", fontSize: 13 }}>
              {loadingPage ? (
                <span aria-live="polite">LoadingΓÇª</span>
              ) : !hasMore ? (
                <span>No more results</span>
              ) : (
                <span>Showing {pages.flat().length} orders</span>
              )}
            </div>
            <button
              onClick={() => loadMore(pageSize, search)}
              disabled={loadingPage || !hasMore}
              style={{ padding: "6px 8px", borderRadius: 8 }}
              title={"Load more"}
            >
              Load more
            </button>
          </div>
        </div>
      )}

      {/* Confirm delete selected modal */}
      {confirmSelectedOpen && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            zIndex: 99999,
            background: "rgba(0,0,0,0.45)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              background: "#fff",
              borderRadius: 12,
              padding: 20,
              width: 420,
              boxShadow: "0 12px 48px rgba(0,0,0,0.18)",
            }}
          >
            <h3
              style={{
                margin: 0,
                fontSize: 18,
                fontWeight: 800,
              }}
            >
              Delete selected orders?
            </h3>
            <p style={{ marginTop: 8, color: "#6b7280" }}>
              This will permanently delete {selected.length} selected order(s).
            </p>
            <div
              style={{
                display: "flex",
                gap: 8,
                justifyContent: "flex-end",
                marginTop: 12,
              }}
            >
              <button
                onClick={() => setConfirmSelectedOpen(false)}
                style={{
                  padding: "8px 12px",
                  borderRadius: 8,
                  border: "1px solid #e5e7eb",
                  background: "#fff",
                }}
              >
                Cancel
              </button>
              <button
                onClick={deleteSelected}
                style={{
                  padding: "8px 12px",
                  borderRadius: 8,
                  border: "none",
                  background: "#ef4444",
                  color: "#fff",
                }}
              >
                Delete
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Confirm delete all modal */}
      {confirmDeleteAllOpen && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            zIndex: 99999,
            background: "rgba(0,0,0,0.45)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              background: "#fff",
              borderRadius: 12,
              padding: 20,
              width: 420,
              boxShadow: "0 12px 48px rgba(0,0,0,0.18)",
            }}
          >
            <h3
              style={{
                margin: 0,
                fontSize: 18,
                fontWeight: 800,
              }}
            >
              Delete all history?
            </h3>
            <p style={{ marginTop: 8, color: "#6b7280" }}>
              This will permanently delete all {pages.flat().length} orders.
              This action cannot be undone.
            </p>
            <div
              style={{
                display: "flex",
                gap: 8,
                justifyContent: "flex-end",
                marginTop: 12,
              }}
            >
              <button
                onClick={() => setConfirmDeleteAllOpen(false)}
                style={{
                  padding: "8px 12px",
                  borderRadius: 8,
                  border: "1px solid #e5e7eb",
                  background: "#fff",
                }}
              >
                Cancel
              </button>
              <button
                onClick={deleteAll}
                style={{
                  padding: "8px 12px",
                  borderRadius: 8,
                  border: "none",
                  background: "#ef4444",
                  color: "#fff",
                }}
              >
                Delete all
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Undo toast */}
      {undoToastVisible && (
        <div
          style={{
            position: "fixed",
            right: 20,
            bottom: 20,
            background: "#111827",
            color: "#fff",
            padding: "10px 14px",
            borderRadius: 8,
            display: "flex",
            gap: 12,
            alignItems: "center",
          }}
        >
          <div>
            {lastDeleted ? `${lastDeleted.length} order(s) deleted` : "Deleted"}
          </div>
          <button
            onClick={undoDelete}
            style={{
              background: "transparent",
              color: "#ffd28a",
              border: "none",
              cursor: "pointer",
              fontWeight: 700,
            }}
          >
            Undo
          </button>
        </div>
      )}

      {/* Preview modal */}
      {previewOpen && (
        // backdrop: clicking it closes the modal
        <div
          onClick={closePreview}
          style={{
            position: "fixed",
            inset: 0,
            zIndex: 99999,
            background: "rgba(0,0,0,0.45)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            opacity: modalVisible ? 1 : 0,
            transition: "opacity 180ms ease",
          }}
        >
          {/* inner dialog: stop propagation so clicks inside don't close the modal */}
          <div
            onClick={(e) => e.stopPropagation()}
            style={{
              width: 640,
              maxHeight: "80vh",
              overflow: "auto",
              background: "#fff",
              borderRadius: 12,
              padding: 18,
              boxShadow: "0 12px 48px rgba(0,0,0,0.18)",
              transform: modalVisible
                ? "translateY(0) scale(1)"
                : "translateY(8px) scale(0.98)",
              opacity: modalVisible ? 1 : 0,
              transition: "opacity 180ms ease, transform 180ms ease",
            }}
          >
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <h3 style={{ margin: 0, fontSize: 18 }}>Order Preview</h3>
              <div style={{ display: "flex", gap: 8 }}>
                <button
                  onClick={() => {
                    if (previewFull) {
reprintOrder({
                        displayId: previewFull._id || previewFull.uid,
                        uid: previewFull._id || previewFull.uid,
                        table: previewFull.tableId || previewFull.table,
                        total: (previewFull.items || []).reduce(
                          (a: any, i: any) => a + (i.qty || 0) * (i.rate || 0),
                          0,
                        ),
                      });
}
                  }}
                  style={{
                    padding: "8px 10px",
                    borderRadius: 8,
                    border: "1px solid #e5e7eb",
                    background: "#fff",
                  }}
                >
                  Reprint
                </button>
                <button
                  onClick={closePreview}
                  style={{
                    padding: "8px 10px",
                    borderRadius: 8,
                    border: "1px solid #e5e7eb",
                    background: "#fff",
                  }}
                >
                  Close
                </button>
              </div>
            </div>
            <div style={{ marginTop: 12 }}>
              {previewLoading && (
                <div style={{ color: "#6b7280" }}>LoadingΓÇª</div>
              )}
              {!previewLoading && previewFull && (
                <div>
                  <div style={{ marginBottom: 8, color: "#6b7280" }}>
                    Order id:{" "}
                    {(() => {
                      const raw = previewFull?._id || previewFull?.uid || "";
                      const s = String(raw);
                      return s.includes(":") ? s.split(":").pop() : s;
                    })()}
                  </div>
                  <div style={{ marginBottom: 12 }}>
                    <strong>Table:</strong> {previewFull?.tableId ?? "-"} &nbsp;
                    ΓÇó &nbsp; <strong>Items:</strong>{" "}
                    {(previewFull?.items || []).length} &nbsp; ΓÇó &nbsp;{" "}
                    <strong>Time:</strong>{" "}
                    {new Date(
                      previewFull?.createdAt ||
                        previewFull?.updatedAt ||
                        previewFull?.time ||
                        Date.now(),
                    ).toLocaleString("en-IN")}
                  </div>
                  <div
                    style={{ borderTop: "1px solid #f3f4f6", paddingTop: 8 }}
                  >
                    {(previewFull?.items || []).length === 0 && (
                      <div style={{ color: "#9ca3af" }}>
                        No line items to display.
                      </div>
                    )}
                    {(previewFull?.items || []).map((it: any, idx: number) => (
                      <div
                        key={idx}
                        style={{
                          display: "flex",
                          justifyContent: "space-between",
                          padding: "8px 0",
                          borderBottom: "1px dashed #f3f4f6",
                        }}
                      >
                        <div>
                          <div style={{ fontWeight: 700 }}>
                            {it.name || it.title || "Item"}
                          </div>
                          <div style={{ fontSize: 12, color: "#6b7280" }}>
                            Qty: {it.qty} ├ù Rate: Γé╣{it.rate}
                          </div>
                        </div>
                        <div style={{ fontWeight: 800 }}>
                          Γé╣
                          {((it.qty || 0) * (it.rate || 0)).toLocaleString(
                            "en-IN",
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                  <div
                    style={{
                      marginTop: 12,
                      textAlign: "right",
                      fontWeight: 800,
                    }}
                  >
                    {(() => {
                      const t = computeTotals(previewFull);
                      const discountPercent = previewFull?.discountPercent;
                      const discountAmount = previewFull?.discountAmount;
                      let discountLine: string | null = null;
                      let finalTotal = t.total;
                      if (typeof discountAmount === "number") {
                        finalTotal = Math.max(
                          0,
                          +(finalTotal - discountAmount).toFixed(2),
                        );
                        discountLine = `-Γé╣${discountAmount.toLocaleString(
                          "en-IN",
                        )}`;
                      } else if (typeof discountPercent === "number") {
                        const amt = +(
                          (finalTotal * (discountPercent || 0)) /
                          100
                        ).toFixed(2);
                        finalTotal = Math.max(
                          0,
                          +(finalTotal - amt).toFixed(2),
                        );
                        discountLine = `${discountPercent}% (-Γé╣${amt.toLocaleString(
                          "en-IN",
                        )})`;
                      }

                      // use raw payments array ΓÇö show each recorded payment line separately
                      const paymentsArr = (previewFull?.payments ||
                        []) as any[];

                      return (
                        <div style={{ textAlign: "right" }}>
                          <div style={{ fontWeight: 700 }}>
                            Subtotal: Γé╣{t.subtotal.toLocaleString("en-IN")}
                          </div>
                          <div style={{ color: "#6b7280" }}>
                            CGST (9%): Γé╣{t.cgst.toLocaleString("en-IN")} + SGST
                            (9%): Γé╣{t.sgst.toLocaleString("en-IN")}
                          </div>
                          {discountLine && (
                            <div style={{ color: "#6b7280" }}>
                              Discount: {discountLine}
                            </div>
                          )}
                          <div
                            style={{
                              marginTop: 6,
                              fontWeight: 900,
                              fontSize: 16,
                            }}
                          >
                            Total: Γé╣{finalTotal.toLocaleString("en-IN")}
                          </div>
                          {/* payments: render each payment record individually */}
                          <div style={{ marginTop: 10, textAlign: "left" }}>
                            <div style={{ fontWeight: 800, marginBottom: 6 }}>
                              Payments
                            </div>
                            {((previewFull?.payments || []) as any[]).length ===
                            0 ? (
                              <div style={{ color: "#9ca3af" }}>
                                No payments recorded.
                              </div>
                            ) : (
                              (previewFull!.payments || []).map(
                                (p: any, idx: number) => {
                                  const amt = +(p?.amount || 0);
                                  return (
                                    <div
                                      key={idx}
                                      style={{
                                        display: "flex",
                                        justifyContent: "space-between",
                                        padding: "6px 0",
                                        borderBottom: "1px dashed #f3f4f6",
                                      }}
                                    >
                                      <div
                                        style={{
                                          color: "#374151",
                                          fontWeight: 700,
                                        }}
                                      >
                                        {p?.method || p?.type || "Payment"}
                                      </div>
                                      <div
                                        style={{
                                          color: "#111827",
                                          fontWeight: 800,
                                        }}
                                      >
                                        Γé╣{amt.toLocaleString("en-IN")}
                                      </div>
                                    </div>
                                  );
                                },
                              )
                            )}
                          </div>
                        </div>
                      );
                    })()}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React from "react";
import {
  getItems,
  seedItems,
  createItem,
  addItemToOrder,
  updateItem,
} from "../../../app/db/pouch";

export default function ItemsEditor() {
  const [items, setItems] = React.useState<any[]>([]);
  const [query, setQuery] = React.useState("");
  // Quick-add and modal states (modal-first workflow)
  const [quickAddOpen, setQuickAddOpen] = React.useState(false);
  const [modalOpen, setModalOpen] = React.useState(false);
  const [modalName, setModalName] = React.useState("");
  const [modalSku, setModalSku] = React.useState("");
  const [modalPrice, setModalPrice] = React.useState<number>(100);
  const [modalCategory, setModalCategory] = React.useState("");
  const [modalAvailable, setModalAvailable] = React.useState(true);
  const [modalSaving, setModalSaving] = React.useState(false);
  // Quick-add form
  const [qaName, setQaName] = React.useState("");
  const [qaSku, setQaSku] = React.useState("");
  const [qaPrice, setQaPrice] = React.useState<number>(100);
  // Inline edit map: itemId -> { name?, price?, category?, available? }
  const [editMap, setEditMap] = React.useState<
    Record<
      string,
      { price?: number; name?: string; category?: string; available?: boolean }
    >
  >({});
  const [saveAllLoading, setSaveAllLoading] = React.useState(false);
  const [toast, setToast] = React.useState<{
    msg: string;
    kind: "ok" | "err";
  } | null>(null);

  const showToast = (msg: string, kind: "ok" | "err" = "ok") => {
    setToast({ msg, kind });
    setTimeout(() => setToast(null), 2800);
  };

  React.useEffect(() => {
    (async () => {
      await seedItems();
      const all = await getItems();
      setItems(all);
    })();
  }, []);

  const filtered = items.filter(
    (it) =>
      (it.name || "").toLowerCase().includes(query.toLowerCase()) ||
      (it.sku || "").toLowerCase().includes(query.toLowerCase()),
  );

  const hasEdits = Object.keys(editMap).length > 0;

  const onAddToOrder = async (item: any) => {
    const orderId =
      typeof window !== "undefined"
        ? window.localStorage.getItem("currentOrderId")
        : null;
    if (!orderId) {
      showToast("Open or create a table/order first", "err");
      return;
    }
    await addItemToOrder(orderId, {
      name: item.name,
      qty: 1,
      rate: item.price,
    });
    showToast(`Added ${item.name} to order`);
  };

  const closeModal = () => {
    setModalOpen(false);
    setModalName("");
    setModalSku("");
    setModalPrice(100);
    setModalCategory("");
    setModalAvailable(true);
  };

  const onModalSave = async () => {
    if (!modalName.trim()) {
      showToast("Name is required", "err");
      return;
    }
    if (modalPrice <= 0) {
      showToast("Price must be greater than zero", "err");
      return;
    }
    const sku = modalSku.trim();
    if (
      sku &&
      items.some((it) => (it.sku || "").toLowerCase() === sku.toLowerCase())
    ) {
      if (!confirm("An item with this SKU already exists. Create anyway?")) {
return;
}
    }
    setModalSaving(true);
    try {
      await createItem({
        name: modalName.trim(),
        price: modalPrice,
        sku: sku || undefined,
        category: modalCategory.trim() || undefined,
      });
      const all = await getItems();
      setItems(all);
      showToast(`"${modalName.trim()}" added`);
      closeModal();
    } catch (e) {
      showToast("Failed to create item", "err");
    } finally {
      setModalSaving(false);
    }
  };

  const onQuickAdd = async () => {
    if (!qaName.trim()) {
      showToast("Name is required", "err");
      return;
    }
    if (qaPrice <= 0) {
      showToast("Price must be > 0", "err");
      return;
    }
    await createItem({
      name: qaName.trim(),
      price: qaPrice,
      sku: qaSku.trim() || undefined,
    });
    const all = await getItems();
    setItems(all);
    setQaName("");
    setQaSku("");
    setQaPrice(100);
    showToast(`"${qaName.trim()}" added`);
  };

  const onSaveAll = async () => {
    if (!hasEdits) {
return;
}
    setSaveAllLoading(true);
    try {
      const promises = Object.entries(editMap).map(([id, edits]) => {
        const base = items.find((it) => it._id === id);
        if (!base) {
return Promise.resolve();
}
        return updateItem({ ...base, ...edits });
      });
      await Promise.all(promises);
      const all = await getItems();
      setItems(all);
      setEditMap({});
      showToast(`${Object.keys(editMap).length} item(s) saved`);
    } catch (e) {
      showToast("Failed to save some items", "err");
    } finally {
      setSaveAllLoading(false);
    }
  };

  return (
    <div
      style={{
        padding: "20px 24px",
        maxWidth: 1100,
        margin: "0 auto",
        fontFamily: "inherit",
      }}
    >
      {/* Toast */}
      {toast && (
        <div
          role="status"
          aria-live="polite"
          style={{
            position: "fixed",
            top: 20,
            right: 24,
            zIndex: 99999,
            padding: "10px 20px",
            borderRadius: 10,
            fontWeight: 600,
            fontSize: 13,
            background: toast.kind === "ok" ? "#16a34a" : "#ef4444",
            color: "#fff",
            boxShadow: "0 4px 18px rgba(0,0,0,0.16)",
            transition: "opacity 200ms",
          }}
        >
          {toast.msg}
        </div>
      )}

      {/* Page header */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          marginBottom: 20,
        }}
      >
        <div>
          <h2
            style={{
              margin: 0,
              fontSize: 22,
              fontWeight: 800,
              color: "#111827",
            }}
          >
            Menu
          </h2>
          <p style={{ margin: "2px 0 0", fontSize: 12, color: "#9ca3af" }}>
            {items.length} item{items.length !== 1 ? "s" : ""} &nbsp;┬╖&nbsp;
            edit prices inline, then Save All
          </p>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <button
            onClick={() => setQuickAddOpen((s) => !s)}
            style={{
              padding: "9px 16px",
              borderRadius: 8,
              border: "1px solid #e5e7eb",
              background: quickAddOpen ? "#f3f4f6" : "#fff",
              color: "#374151",
              fontWeight: 600,
              fontSize: 13,
              cursor: "pointer",
            }}
          >
            {quickAddOpen ? "Γû▓ Quick Add" : "Γû╝ Quick Add"}
          </button>
          <button
            onClick={() => setModalOpen(true)}
            style={{
              padding: "9px 18px",
              borderRadius: 8,
              border: "none",
              background: "linear-gradient(135deg,#d97706,#f59e0b)",
              color: "#fff",
              fontWeight: 700,
              fontSize: 13,
              cursor: "pointer",
              boxShadow: "0 2px 8px rgba(217,119,6,0.25)",
            }}
          >
            + New Item
          </button>
        </div>
      </div>

      {/* Quick Add collapsible */}
      {quickAddOpen && (
        <div
          style={{
            background: "#fff",
            border: "1px solid #e5e7eb",
            borderRadius: 12,
            padding: "14px 16px",
            marginBottom: 16,
            boxShadow: "0 1px 6px rgba(0,0,0,0.05)",
          }}
        >
          <p
            style={{
              margin: "0 0 10px",
              fontWeight: 700,
              fontSize: 13,
              color: "#374151",
            }}
          >
            Quick Add
          </p>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            <input
              placeholder="Name *"
              value={qaName}
              onChange={(e) => setQaName(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && onQuickAdd()}
              style={{
                flex: "1 1 160px",
                padding: "8px 10px",
                borderRadius: 8,
                border: "1px solid #d1d5db",
                fontSize: 13,
              }}
            />
            <input
              placeholder="SKU / ID"
              value={qaSku}
              onChange={(e) => setQaSku(e.target.value)}
              style={{
                width: 130,
                padding: "8px 10px",
                borderRadius: 8,
                border: "1px solid #d1d5db",
                fontSize: 13,
              }}
            />
            <div
              style={{
                display: "flex",
                alignItems: "center",
                border: "1px solid #d1d5db",
                borderRadius: 8,
                overflow: "hidden",
              }}
            >
              <span
                style={{ padding: "0 8px", color: "#6b7280", fontSize: 13 }}
              >
                Γé╣
              </span>
              <input
                type="number"
                placeholder="Price"
                value={qaPrice}
                onChange={(e) => setQaPrice(Number(e.target.value))}
                style={{
                  width: 90,
                  padding: "8px 6px",
                  border: "none",
                  fontSize: 13,
                  outline: "none",
                }}
              />
            </div>
            <button
              onClick={onQuickAdd}
              style={{
                padding: "8px 18px",
                borderRadius: 8,
                border: "none",
                background: "#111827",
                color: "#fff",
                fontWeight: 700,
                fontSize: 13,
                cursor: "pointer",
              }}
            >
              Add
            </button>
          </div>
        </div>
      )}

      {/* Search bar */}
      <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
        <div style={{ flex: 1, position: "relative" }}>
          <span
            style={{
              position: "absolute",
              left: 10,
              top: "50%",
              transform: "translateY(-50%)",
              color: "#9ca3af",
              fontSize: 15,
            }}
          >
            ≡ƒöì
          </span>
          <input
            placeholder="Search by name or SKUΓÇª"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            style={{
              width: "100%",
              padding: "9px 10px 9px 32px",
              borderRadius: 8,
              border: "1px solid #d1d5db",
              fontSize: 13,
              boxSizing: "border-box",
            }}
          />
        </div>
        {query && (
          <button
            onClick={() => setQuery("")}
            style={{
              padding: "9px 14px",
              borderRadius: 8,
              border: "1px solid #e5e7eb",
              background: "#f9fafb",
              color: "#6b7280",
              fontSize: 13,
              cursor: "pointer",
            }}
          >
            Clear
          </button>
        )}
      </div>

      {/* Column headers */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 140px 140px 80px 80px",
          padding: "6px 14px",
          borderRadius: 6,
          background: "#f3f4f6",
          fontSize: 11,
          fontWeight: 700,
          color: "#6b7280",
          letterSpacing: "0.06em",
          textTransform: "uppercase",
          marginBottom: 6,
        }}
      >
        <span>Name / SKU</span>
        <span>Category</span>
        <span style={{ textAlign: "right" }}>Price (Γé╣)</span>
        <span style={{ textAlign: "center" }}>Status</span>
        <span style={{ textAlign: "right" }}>Action</span>
      </div>

      {/* Item rows */}
      <div style={{ display: "grid", gap: 4 }}>
        {filtered.length === 0 && (
          <div
            style={{
              textAlign: "center",
              padding: "40px 0",
              color: "#9ca3af",
              fontSize: 14,
            }}
          >
            No items found
          </div>
        )}
        {filtered.map((it) => {
          const edited = editMap[it._id] !== undefined;
          const currentPrice = editMap[it._id]?.price ?? it.price;
          return (
            <div
              key={it._id}
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 140px 140px 80px 80px",
                alignItems: "center",
                padding: "10px 14px",
                borderRadius: 10,
                background: edited ? "#fffbeb" : "#fff",
                border: edited ? "1.5px solid #fde68a" : "1px solid #f3f4f6",
                boxShadow: "0 1px 3px rgba(0,0,0,0.04)",
                transition: "border-color 120ms, background 120ms",
              }}
            >
              {/* Name + SKU */}
              <div>
                <div
                  style={{ fontWeight: 700, fontSize: 14, color: "#111827" }}
                >
                  {it.name}
                </div>
                {it.sku && (
                  <div
                    style={{
                      fontSize: 11,
                      color: "#9ca3af",
                      marginTop: 1,
                      fontFamily: "monospace",
                    }}
                  >
                    #{it.sku}
                  </div>
                )}
              </div>

              {/* Category */}
              <div style={{ fontSize: 12, color: "#6b7280" }}>
                {it.category || <span style={{ color: "#d1d5db" }}>ΓÇö</span>}
              </div>

              {/* Editable price */}
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "flex-end",
                  gap: 2,
                }}
              >
                <span style={{ fontSize: 12, color: "#6b7280" }}>Γé╣</span>
                <input
                  type="number"
                  value={currentPrice}
                  onChange={(e) =>
                    setEditMap((m) => ({
                      ...m,
                      [it._id]: { ...m[it._id], price: Number(e.target.value) },
                    }))
                  }
                  style={{
                    width: 90,
                    padding: "6px 8px",
                    borderRadius: 7,
                    border: edited
                      ? "1.5px solid #f59e0b"
                      : "1px solid #e5e7eb",
                    fontSize: 13,
                    textAlign: "right",
                    background: edited ? "#fffbeb" : "#fff",
                    outline: "none",
                  }}
                />
              </div>

              {/* Available badge */}
              <div style={{ textAlign: "center" }}>
                <span
                  style={{
                    display: "inline-block",
                    padding: "2px 8px",
                    borderRadius: 20,
                    fontSize: 11,
                    fontWeight: 600,
                    background: it.available !== false ? "#dcfce7" : "#fee2e2",
                    color: it.available !== false ? "#16a34a" : "#dc2626",
                  }}
                >
                  {it.available !== false ? "On" : "Off"}
                </span>
              </div>

              {/* Add to order */}
              <div style={{ textAlign: "right" }}>
                <button
                  onClick={() => onAddToOrder(it)}
                  title="Add to current order"
                  style={{
                    padding: "6px 12px",
                    borderRadius: 7,
                    border: "1px solid #e5e7eb",
                    background: "#fff",
                    color: "#374151",
                    fontSize: 12,
                    fontWeight: 600,
                    cursor: "pointer",
                  }}
                >
                  + Add
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* Save All footer */}
      <div
        style={{
          marginTop: 20,
          paddingTop: 16,
          borderTop: "1px solid #f3f4f6",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        <span style={{ fontSize: 12, color: "#9ca3af" }}>
          {hasEdits
            ? `${Object.keys(editMap).length} unsaved change${
                Object.keys(editMap).length !== 1 ? "s" : ""
              }`
            : "No unsaved changes"}
        </span>
        <div style={{ display: "flex", gap: 8 }}>
          {hasEdits && (
            <button
              onClick={() => setEditMap({})}
              style={{
                padding: "10px 18px",
                borderRadius: 8,
                border: "1px solid #e5e7eb",
                background: "#fff",
                color: "#6b7280",
                fontWeight: 600,
                fontSize: 13,
                cursor: "pointer",
              }}
            >
              Discard
            </button>
          )}
          <button
            onClick={onSaveAll}
            disabled={!hasEdits || saveAllLoading}
