import React from "react";
import {
  getOpenOrders,
  updateOrder,
  type OrderDoc,
} from "../../../app/db/pouch";

type KOTItem = {
  orderId: string;
  table: number;
  items: { name: string; qty: number }[];
  time: number;
  done: boolean;
};

export default function KOTQueue() {
  const [kotList, setKotList] = React.useState<KOTItem[]>([]);
  const [, tick] = React.useReducer((x: number) => x + 1, 0);

  // Load KOT items from database
  const loadKOTs = React.useCallback(async () => {
    try {
      const orders = await getOpenOrders();
      const kots: KOTItem[] = orders
        .filter((o) => o.kotSent && !o.kotPrinted)
        .map((o) => ({
          orderId: o._id,
          table: o.tableId ?? 0,
          items: o.items.map((it) => ({ name: it.name, qty: it.qty })),
          time: o.updatedAt || o.createdAt,
          done: false,
        }));
      setKotList(kots);
    } catch (e) {
      console.error("Failed to load KOTs:", e);
    }
  }, []);

  // Initial load
  React.useEffect(() => {
    loadKOTs();
  }, [loadKOTs]);

  // Listen for order changes
  React.useEffect(() => {
    const handleOrdersChanged = () => {
      loadKOTs();
    };
    window.addEventListener("orders-changed", handleOrdersChanged);
    return () =>
      window.removeEventListener("orders-changed", handleOrdersChanged);
  }, [loadKOTs]);

  // Refresh every 30 seconds
  React.useEffect(() => {
    const id = setInterval(() => tick(), 30000);
    return () => clearInterval(id);
  }, []);

  const markDone = async (orderId: string) => {
    try {
      // Find the order and mark it as kotPrinted
      const orders = await getOpenOrders();
      const order = orders.find((o) => o._id === orderId);
      if (!order) {
return;
}

      const updated = await updateOrder({
        ...order,
        kotPrinted: true,
        updatedAt: Date.now(),
      });

      // Remove from local list
      setKotList((list) => list.filter((k) => k.orderId !== orderId));

      // Notify other components
      window.dispatchEvent(new Event("orders-changed"));
    } catch (e) {
      console.error("Failed to mark KOT as done:", e);
      alert("Failed to mark KOT as done");
    }
  };

  // Since we're loading from DB, all items are "pending" until manually marked done
  // The "done" concept is handled at the order level (kotPrinted flag)
  const pending = kotList;
  const done: KOTItem[] = [];

  const ageColor = (ms: number) => {
    const mins = Math.round(ms / 60000);
    if (mins < 5) {
return "#16a34a";
}
    if (mins < 15) {
return "#d97706";
}
    return "#dc2626";
  };

  return (
    <div style={{ padding: "20px 24px", maxWidth: 1000, margin: "0 auto" }}>
      {/* Header */}
      <div
        style={{
          display: "flex",
          alignItems: "flex-start",
          justifyContent: "space-between",
          marginBottom: 20,
        }}
      >
        <div>
          <h2
            style={{
              margin: 0,
              fontSize: 22,
              fontWeight: 800,
              color: "#111827",
            }}
          >
            KOT Queue
          </h2>
          <p style={{ margin: "3px 0 0", fontSize: 13, color: "#9ca3af" }}>
            <span style={{ color: "#d97706", fontWeight: 700 }}>
              {pending.length}
            </span>{" "}
            pending &nbsp;┬╖&nbsp;
            <span style={{ color: "#16a34a", fontWeight: 700 }}>
              {done.length}
            </span>{" "}
            done
          </p>
        </div>
        {done.length > 0 && (
          <button
            onClick={() => {
              // Completed KOTs are no longer shown in the pending list once kotPrinted=true
              // This button is kept for UI consistency but won't be visible
            }}
            style={{
              padding: "9px 16px",
              borderRadius: 8,
              border: "1px solid #e5e7eb",
              background: "#fff",
              color: "#6b7280",
              fontWeight: 600,
              fontSize: 13,
              cursor: "pointer",
            }}
          >
            Clear Done
          </button>
        )}
      </div>

      {/* Pending KOTs */}
      {pending.length === 0 && (
        <div
          style={{
            textAlign: "center",
            padding: "48px 0",
            color: "#9ca3af",
            fontSize: 15,
          }}
        >
          ≡ƒÄë No pending KOTs
        </div>
      )}
      <div
        style={{
          display: "grid",
          gap: 12,
          gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
        }}
      >
        {pending.map((k) => {
          const ageMins = Math.round((Date.now() - k.time) / 60000);
          return (
            <div
              key={k.orderId}
              style={{
                padding: "16px 18px",
                borderRadius: 14,
                background: "#fff",
                border: "1.5px solid #e5e7eb",
                boxShadow: "0 2px 8px rgba(0,0,0,0.05)",
              }}
            >
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  marginBottom: 12,
                }}
              >
                <div
                  style={{ fontSize: 18, fontWeight: 900, color: "#111827" }}
                >
                  Table {k.table || "ΓÇö"}
                </div>
                <span
                  style={{
                    padding: "4px 10px",
                    borderRadius: 20,
                    fontSize: 12,
                    fontWeight: 700,
                    background:
                      ageMins < 5
                        ? "#dcfce7"
                        : ageMins < 15
                        ? "#fef3c7"
                        : "#fee2e2",
                    color: ageColor(Date.now() - k.time),
                  }}
                >
                  {ageMins}m ago
                </span>
              </div>
              <div style={{ display: "grid", gap: 4, marginBottom: 14 }}>
                {k.items.map((it) => (
                  <div
                    key={it.name}
                    style={{
                      fontSize: 14,
                      color: "#374151",
                      fontWeight: 600,
                      display: "flex",
                      alignItems: "center",
                      gap: 8,
                    }}
                  >
                    <span style={{ color: "#d97706", fontSize: 12 }}>Γû╕</span>
                    {it.name}{" "}
                    <span style={{ color: "#9ca3af", fontSize: 12 }}>
                      x{it.qty}
                    </span>
                  </div>
                ))}
              </div>
              <div style={{ display: "flex", gap: 8 }}>
                <button
                  onClick={() => markDone(k.orderId)}
                  style={{
                    flex: 1,
                    padding: "10px 0",
                    borderRadius: 9,
                    border: "none",
                    background: "#16a34a",
                    color: "#fff",
                    fontWeight: 700,
                    fontSize: 14,
                    cursor: "pointer",
                  }}
                >
                  Γ£ô Mark Done
                </button>
                <button
                  style={{
                    padding: "10px 14px",
                    borderRadius: 9,
                    border: "1px solid #e5e7eb",
                    background: "#fff",
                    color: "#374151",
                    fontWeight: 600,
                    fontSize: 14,
                    cursor: "pointer",
                  }}
                >
                  Reprint
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* Done section - not used since completed KOTs are stored in database */}
      {false && done.length > 0 && (
        <div style={{ marginTop: 28 }}>
          <p
            style={{
              fontSize: 12,
              fontWeight: 700,
              color: "#9ca3af",
              textTransform: "uppercase",
              letterSpacing: "0.06em",
              marginBottom: 10,
            }}
          >
            Completed
          </p>
          <div style={{ display: "grid", gap: 8 }}>
            {done.map((k) => (
              <div
                key={k.orderId}
                style={{
                  padding: "12px 16px",
                  borderRadius: 10,
                  background: "#f9fafb",
                  border: "1px solid #f3f4f6",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  opacity: 0.7,
                }}
              >
                <div>
                  <span
                    style={{ fontWeight: 700, fontSize: 14, color: "#374151" }}
                  >
                    Table {k.table}
                  </span>
                  <span
                    style={{ color: "#9ca3af", fontSize: 13, marginLeft: 10 }}
                  >
                    {k.items.map((it) => it.name).join(", ")}
                  </span>
                </div>
                <span
                  style={{
                    fontSize: 11,
                    fontWeight: 700,
                    color: "#16a34a",
                    background: "#dcfce7",
                    padding: "3px 8px",
                    borderRadius: 20,
                  }}
                >
                  Done
                </span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

import React from "react";
import { AuthContext } from "../../context/AuthContext";

export default function LoginScreen() {
  const auth = React.useContext(AuthContext);
  const [username, setUsername] = React.useState("");
  const [password, setPassword] = React.useState("");
  const [error, setError] = React.useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!auth) {
return;
}
    const ok = await auth.login(username.trim(), password);
    if (!ok) {
setError("Invalid credentials");
} else {
      // redirect to tables after successful login
      try {
        window.location.hash = "#tables";
      } catch (e) {}
    }
  };

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        height: "100%",
      }}
    >
      <form
        onSubmit={handleSubmit}
        style={{
          width: 380,
          padding: 24,
          borderRadius: 8,
          boxShadow: "0 2px 10px rgba(0,0,0,0.08)",
          background: "#fff",
        }}
      >
        <h2 style={{ marginTop: 0 }}>Sign in</h2>
        <label style={{ display: "block", marginBottom: 8 }}>
          Username
          <input
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            style={{ width: "100%", padding: 8, marginTop: 6 }}
          />
        </label>
        <label style={{ display: "block", marginBottom: 8 }}>
          Password
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={{ width: "100%", padding: 8, marginTop: 6 }}
          />
        </label>
        {error && (
          <div style={{ color: "crimson", marginBottom: 8 }}>{error}</div>
        )}
        <div style={{ display: "flex", gap: 8, justifyContent: "flex-end" }}>
          <button
            type="submit"
            style={{
              padding: "8px 12px",
              background: "#d97706",
              color: "#fff",
              border: "none",
              borderRadius: 6,
            }}
          >
            Sign in
          </button>
        </div>
      </form>
    </div>
  );
}

import React from "react";
import {
  getOpenOrders,
  getSalesSummary,
  getPaymentBreakdown,
  type OrderDoc,
} from "../../../app/db/pouch";

export default function Reports() {
  const [sales, setSales] = React.useState(0);
  const [orders, setOrders] = React.useState(0);
  const [gst, setGst] = React.useState(0);
  const [cashAmount, setCashAmount] = React.useState(0);
  const [upiAmount, setUpiAmount] = React.useState(0);
  const [loading, setLoading] = React.useState(true);

  const formatCurrency = (v: number) => {
    try {
      return new Intl.NumberFormat("en-IN", {
        style: "currency",
        currency: "INR",
        maximumFractionDigits: 2,
      }).format(v);
    } catch (e) {
      return `Γé╣${Math.round(v * 100) / 100}`;
    }
  };

  React.useEffect(() => {
    (async () => {
      try {
        setLoading(true);
        const startOfDay = new Date();
        startOfDay.setHours(0, 0, 0, 0);
        const endOfDay = new Date();
        endOfDay.setHours(23, 59, 59, 999);

        const summary = await getSalesSummary({
          from: startOfDay.getTime(),
          to: endOfDay.getTime(),
        });

        const breakdown = await getPaymentBreakdown({
          from: startOfDay.getTime(),
          to: endOfDay.getTime(),
        });

        // Calculate totals
        const totalSales = summary.total || 0;
        const ordersCount = summary.orders || 0;
        const gstAmount = +(totalSales * 0.18).toFixed(2);
        const cash = breakdown.cash || 0;
        const upi = breakdown.upi || 0;

        setSales(totalSales);
        setOrders(ordersCount);
        setGst(gstAmount);
        setCashAmount(cash);
        setUpiAmount(upi);
      } catch (e) {
        console.error("Failed to load reports:", e);
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  const cashPercent = sales > 0 ? Math.round((cashAmount / sales) * 100) : 0;
  const upiPercent = sales > 0 ? Math.round((upiAmount / sales) * 100) : 0;

  const kpi = [
    {
      label: "Sales Today",
      value: formatCurrency(sales),
      sub: loading ? "Loading..." : `${orders} orders`,
      color: "#d97706",
      bg: "#fff7ed",
    },
    {
      label: "Orders",
      value: orders,
      sub: loading
        ? "Loading..."
        : sales > 0
        ? `Avg: ${formatCurrency(sales / Math.max(1, orders))}`
        : "No sales",
      color: "#7c3aed",
      bg: "#f5f3ff",
    },
    {
      label: "Cash / UPI",
      value: `${formatCurrency(cashAmount)} / ${formatCurrency(upiAmount)}`,
      sub: `${cashPercent}% cash ┬╖ ${upiPercent}% UPI`,
      color: "#0369a1",
      bg: "#f0f9ff",
    },
    {
      label: "GST Collected",
      value: formatCurrency(gst),
      sub: `CGST: ${formatCurrency(gst / 2)} + SGST: ${formatCurrency(
        gst / 2,
      )}`,
      color: "#16a34a",
      bg: "#f0fdf4",
    },
  ];

  const cgst = +(gst / 2).toFixed(2);
  const sgst = +(gst / 2).toFixed(2);

  return (
    <div style={{ padding: "20px 24px", maxWidth: 1000, margin: "0 auto" }}>
      {/* Header */}
      <div
        style={{
          display: "flex",
          alignItems: "flex-start",
          justifyContent: "space-between",
          marginBottom: 20,
          flexWrap: "wrap",
          gap: 10,
        }}
      >
        <div>
          <h2
            style={{
              margin: 0,
              fontSize: 22,
              fontWeight: 800,
              color: "#111827",
            }}
          >
            Reports
          </h2>
          <p style={{ margin: "3px 0 0", fontSize: 13, color: "#9ca3af" }}>
            Today ┬╖{" "}
            {new Date().toLocaleDateString("en-IN", {
              weekday: "long",
              day: "numeric",
              month: "long",
            })}
          </p>
        </div>
        <button
          style={{
            padding: "9px 18px",
            borderRadius: 8,
            border: "1px solid #e5e7eb",
            background: "#fff",
            color: "#374151",
            fontWeight: 600,
            fontSize: 13,
            cursor: "pointer",
          }}
        >
          Export / Print
        </button>
      </div>

      {/* KPI cards */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
          gap: 14,
          marginBottom: 28,
        }}
      >
        {kpi.map((k) => (
          <div
            key={k.label}
            style={{
              padding: "20px 18px",
              borderRadius: 14,
              background: k.bg,
              border: `1.5px solid ${k.color}22`,
            }}
          >
            <div
              style={{
                fontSize: 12,
                fontWeight: 700,
                color: k.color,
                textTransform: "uppercase",
                letterSpacing: "0.06em",
                marginBottom: 8,
              }}
            >
              {k.label}
            </div>
            <div
              style={{
                fontSize: 24,
                fontWeight: 900,
                color: "#111827",
                lineHeight: 1,
              }}
            >
              {k.value}
            </div>
            <div style={{ fontSize: 12, color: "#9ca3af", marginTop: 6 }}>
              {k.sub}
            </div>
          </div>
        ))}
      </div>

      {/* GST breakdown */}
      <div
        style={{
          background: "#fff",
          border: "1px solid #f3f4f6",
          borderRadius: 14,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            padding: "14px 18px",
            borderBottom: "1px solid #f3f4f6",
            fontWeight: 800,
            fontSize: 15,
            color: "#111827",
          }}
        >
          GST Breakdown
        </div>
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr style={{ background: "#f9fafb" }}>
              {["Tax Type", "Rate", "Taxable Amount", "Tax Amount"].map((h) => (
                <th
                  key={h}
                  style={{
                    padding: "10px 18px",
