            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}

/**
 * Log & Archive Management Settings Component
 * UI for managing application logs and audit archives
 */

import React, { useEffect, useState } from "react";
import { logger } from "../../../app/utils/logger";
import { AuditArchiver } from "../../../app/utils/auditArchiver";
import { CrashRecovery } from "../../../app/utils/crashRecovery";
import styles from "./LogSettings.module.css";

interface LogEntry {
  timestamp: string;
  level: "info" | "warn" | "error" | "debug";
  message: string;
  context?: Record<string, any>;
}

interface ArchiveInfo {
  _id: string;
  startDate: number;
  endDate: number;
  count: number;
  fileSize?: number;
  archivedAt: number;
}

export default function LogSettings() {
  const [activeTab, setActiveTab] = useState<"logs" | "archives" | "recovery">("logs");
  const [recentLogs, setRecentLogs] = useState<LogEntry[]>([]);
  const [archives, setArchives] = useState<ArchiveInfo[]>([]);
  const [logStats, setLogStats] = useState({ totalLogs: 0, lastUpdated: new Date() });
  const [archiveStats, setArchiveStats] = useState({
    totalArchives: 0,
    totalArchivedLogs: 0,
    totalSize: 0,
  });
  const [recoveryState, setRecoveryState] = useState<any>(null);
  const [selectedArchives, setSelectedArchives] = useState<Set<string>>(new Set());
  const [exportingLogs, setExportingLogs] = useState(false);

  // Load log data
  useEffect(() => {
    loadLogData();
    const interval = setInterval(loadLogData, 5000); // Refresh every 5 seconds
    return () => clearInterval(interval);
  }, []);

  // Load archive data
  useEffect(() => {
    loadArchiveData();
  }, []);

  // Load recovery state
  useEffect(() => {
    if (CrashRecovery.hasRecoverableState()) {
      const state = CrashRecovery.getRecoveryState();
      setRecoveryState(state);
    }
  }, []);

  const loadLogData = async () => {
    try {
      const logs = logger.getRecentLogs(100);
      setRecentLogs(logs);
      setLogStats({
        totalLogs: logs.length,
        lastUpdated: new Date(),
      });
    } catch (error) {
      console.error("Failed to load log data", error);
    }
  };

  const loadArchiveData = async () => {
    try {
      const archiveList = await AuditArchiver.getArchives();
      setArchives(archiveList);

      const stats = await AuditArchiver.getArchiveStats();
      setArchiveStats(stats);
    } catch (error) {
      console.error("Failed to load archive data", error);
    }
  };

  const handleExportLogs = async (format: "json" | "csv") => {
    try {
      setExportingLogs(true);
      const content = format === "json" ? logger.exportJSON() : logger.exportCSV();
      const filename = `pos-logs-${new Date().toISOString()}.${format}`;

      const blob = new Blob([content], {
        type: format === "json" ? "application/json" : "text/csv",
      });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error("Export failed", error);
      alert("Failed to export logs");
    } finally {
      setExportingLogs(false);
    }
  };

  const handleClearLogs = () => {
    if (window.confirm("Are you sure you want to clear all logs? This action cannot be undone.")) {
      try {
        (logger as any).logs = [];
        setRecentLogs([]);
        alert("Logs cleared successfully");
      } catch (error) {
        console.error("Failed to clear logs", error);
      }
    }
  };

  const handleExportArchive = async (archiveId: string) => {
    try {
      const csv = await AuditArchiver.exportArchiveAsCSV(archiveId);
      const filename = `archive-${archiveId}.csv`;
      const blob = new Blob([csv], { type: "text/csv" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error("Export failed", error);
      alert("Failed to export archive");
    }
  };

  const handleDeleteArchive = async (archiveId: string) => {
    if (
      window.confirm("Are you sure you want to delete this archive? This action cannot be undone.")
    ) {
      try {
        // Note: Implementation depends on AuditArchiver.deleteArchive() method
        await loadArchiveData();
        alert("Archive deleted successfully");
      } catch (error) {
        console.error("Delete failed", error);
      }
    }
  };

  const handleToggleArchiveSelection = (archiveId: string) => {
    const newSelected = new Set(selectedArchives);
    if (newSelected.has(archiveId)) {
      newSelected.delete(archiveId);
    } else {
      newSelected.add(archiveId);
    }
    setSelectedArchives(newSelected);
  };

  const handleBulkDeleteArchives = async () => {
    if (selectedArchives.size === 0) {
      alert("Please select archives to delete");
      return;
    }

    if (window.confirm(`Delete ${selectedArchives.size} archive(s)? This cannot be undone.`)) {
      try {
        // Implementation depends on bulk delete support
        await loadArchiveData();
        setSelectedArchives(new Set());
        alert("Archives deleted successfully");
      } catch (error) {
        console.error("Bulk delete failed", error);
      }
    }
  };

  const handleCleanupOldArchives = async (ageMonths: number = 12) => {
    if (window.confirm(`Delete archives older than ${ageMonths} months? This cannot be undone.`)) {
      try {
        await AuditArchiver.cleanupOldArchives(ageMonths);
        await loadArchiveData();
        alert("Old archives cleaned up successfully");
      } catch (error) {
        console.error("Cleanup failed", error);
      }
    }
  };

  const handleRecoverState = () => {
    if (!recoveryState) {
      alert("No recovery state available");
      return;
    }

    // This would typically redirect or trigger recovery
    alert(`Recovery state available from ${new Date(recoveryState.timestamp).toLocaleString()}`);
  };

  const handleClearRecovery = () => {
    if (window.confirm("Clear the recovery state? You may lose unsaved data.")) {
      try {
        CrashRecovery.clearRecoveryState();
        setRecoveryState(null);
        alert("Recovery state cleared");
      } catch (error) {
        console.error("Clear recovery failed", error);
      }
    }
  };

  const formatBytes = (bytes: number) => {
    if (bytes === 0) {
return "0 B";
}
    const k = 1024;
    const sizes = ["B", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + " " + sizes[i];
  };

  const formatDate = (timestamp: number | string) => {
    const date = typeof timestamp === "string" ? new Date(timestamp) : new Date(timestamp);
    return date.toLocaleString();
  };

  return (
    <div className={styles.container}>
      <h2>System Logs & Archives</h2>

      {/* Tab Navigation */}
      <div className={styles.tabNavigation}>
        <button
          className={`${styles.tabButton} ${activeTab === "logs" ? styles.active : ""}`}
          onClick={() => setActiveTab("logs")}
        >
          ≡ƒôï Recent Logs
        </button>
        <button
          className={`${styles.tabButton} ${activeTab === "archives" ? styles.active : ""}`}
          onClick={() => setActiveTab("archives")}
        >
          ≡ƒôª Archives ({archiveStats.totalArchives})
        </button>
        <button
          className={`${styles.tabButton} ${activeTab === "recovery" ? styles.active : ""}`}
          onClick={() => setActiveTab("recovery")}
        >
          ≡ƒöä Recovery
        </button>
      </div>

      {/* Logs Tab */}
      {activeTab === "logs" && (
        <div className={styles.tabPanel}>
          <div className={styles.header}>
            <h3>Recent Logs</h3>
            <div className={styles.stats}>
              <div className={styles.stat}>
                <span className={styles.statLabel}>Total Logs:</span>
                <span className={styles.statValue}>{logStats.totalLogs}</span>
              </div>
              <div className={styles.stat}>
                <span className={styles.statLabel}>Last Updated:</span>
                <span className={styles.statValue}>
                  {logStats.lastUpdated.toLocaleTimeString()}
                </span>
              </div>
            </div>
          </div>

          <div className={styles.actions}>
            <button
              className={styles.button}
              onClick={() => handleExportLogs("json")}
              disabled={exportingLogs}
            >
              ≡ƒôÑ Export JSON
            </button>
            <button
              className={styles.button}
              onClick={() => handleExportLogs("csv")}
              disabled={exportingLogs}
            >
              ≡ƒôè Export CSV
            </button>
            <button className={`${styles.button} ${styles.danger}`} onClick={handleClearLogs}>
              ≡ƒùæ∩╕Å Clear All Logs
            </button>
          </div>

          <div className={styles.logsList}>
            {recentLogs.length === 0 ? (
              <div className={styles.empty}>No logs available</div>
            ) : (
              recentLogs.map((log, index) => (
                <div key={index} className={`${styles.logEntry} ${styles[log.level]}`}>
                  <div className={styles.logHeader}>
                    <span className={styles.timestamp}>{log.timestamp}</span>
                    <span className={`${styles.level} ${styles[log.level]}`}>
                      {log.level.toUpperCase()}
                    </span>
                  </div>
                  <div className={styles.message}>{log.message}</div>
                  {log.context && Object.keys(log.context).length > 0 && (
                    <div className={styles.context}>
                      <code>{JSON.stringify(log.context, null, 2)}</code>
                    </div>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      )}

      {/* Archives Tab */}
      {activeTab === "archives" && (
        <div className={styles.tabPanel}>
          <div className={styles.header}>
            <h3>Audit Archives</h3>
            <div className={styles.stats}>
              <div className={styles.stat}>
                <span className={styles.statLabel}>Total Archives:</span>
                <span className={styles.statValue}>{archiveStats.totalArchives}</span>
              </div>
              <div className={styles.stat}>
                <span className={styles.statLabel}>Total Size:</span>
                <span className={styles.statValue}>{formatBytes(archiveStats.totalSize || 0)}</span>
              </div>
            </div>
          </div>

          <div className={styles.actions}>
            <button
              className={`${styles.button} ${styles.danger}`}
              onClick={handleBulkDeleteArchives}
              disabled={selectedArchives.size === 0}
            >
              ≡ƒùæ∩╕Å Delete Selected ({selectedArchives.size})
            </button>
            <button
              className={`${styles.button} ${styles.warning}`}
              onClick={() => handleCleanupOldArchives(12)}
            >
              ≡ƒº╣ Cleanup Archives &gt;1 year
            </button>
          </div>

          <div className={styles.archivesList}>
            {archives.length === 0 ? (
              <div className={styles.empty}>No archives available</div>
            ) : (
              archives.map((archive) => (
                <div key={archive._id} className={styles.archiveItem}>
                  <div className={styles.archiveHeader}>
                    <input
                      type="checkbox"
                      checked={selectedArchives.has(archive._id)}
                      onChange={() => handleToggleArchiveSelection(archive._id)}
                    />
                    <span className={styles.archiveTitle}>
                      {formatDate(archive.startDate)} ΓåÆ {formatDate(archive.endDate)}
                    </span>
                    <span className={styles.archiveMeta}>
                      {archive.count} entries ΓÇó {formatBytes(archive.fileSize || 0)}
                    </span>
                  </div>
                  <div className={styles.archiveActions}>
                    <button
                      className={styles.buttonSmall}
                      onClick={() => handleExportArchive(archive._id)}
                    >
                      ≡ƒôÑ Export
                    </button>
                    <button
                      className={`${styles.buttonSmall} ${styles.danger}`}
                      onClick={() => handleDeleteArchive(archive._id)}
                    >
                      ≡ƒùæ∩╕Å Delete
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      )}

      {/* Recovery Tab */}
      {activeTab === "recovery" && (
        <div className={styles.tabPanel}>
          <div className={styles.header}>
            <h3>Crash Recovery</h3>
          </div>

          {recoveryState ? (
            <div className={styles.recoveryInfo}>
              <div className={styles.recoveryItem}>
                <span className={styles.label}>Recovered At:</span>
                <span>{formatDate(recoveryState.timestamp)}</span>
              </div>
              {recoveryState.currentOrderId && (
                <div className={styles.recoveryItem}>
                  <span className={styles.label}>Order ID:</span>
                  <span>{recoveryState.currentOrderId}</span>
                </div>
              )}
              {recoveryState.currentTable && (
                <div className={styles.recoveryItem}>
                  <span className={styles.label}>Table:</span>
                  <span>Table {recoveryState.currentTable}</span>
                </div>
              )}
              <div className={styles.recoveryItem}>
                <span className={styles.label}>Cart Items:</span>
                <span>{recoveryState.cartItems?.length || 0} items</span>
              </div>
              <div className={styles.recoveryItem}>
                <span className={styles.label}>Discount:</span>
                <span>{recoveryState.discountPercent || 0}%</span>
              </div>

              <div className={styles.recoveryJSON}>
                <h4>Full Recovery State:</h4>
                <code>{JSON.stringify(CrashRecovery.exportRecoveryState(), null, 2)}</code>
              </div>

              <div className={styles.actions}>
                <button className={styles.button} onClick={handleRecoverState}>
                  Γ£à Restore Data
                </button>
                <button
                  className={`${styles.button} ${styles.danger}`}
                  onClick={handleClearRecovery}
                >
                  Γ¥î Clear Recovery State
                </button>
              </div>
            </div>
          ) : (
            <div className={styles.empty}>
              <p>No recovery state available</p>
              <p style={{ fontSize: "0.9em", color: "#666" }}>
                Recovery data is created when the app crashes unexpectedly with unsaved orders
              </p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import React from "react";
import { getConfigPrinters, setConfigPrinters } from "../../../app/db/pouch";

export default function Settings() {
  const [kitchenIp, setKitchenIp] = React.useState("");
  const [counterIp, setCounterIp] = React.useState("");
  const [port, setPort] = React.useState<number>(9100);
  const [status, setStatus] = React.useState<string | null>(null);
  const [saving, setSaving] = React.useState(false);

  React.useEffect(() => {
    (async () => {
      try {
        const cfg = await getConfigPrinters();
        if (cfg) {
          setKitchenIp(cfg.kitchenPrinterIp || "");
          setCounterIp(cfg.counterPrinterIp || "");
          setPort(cfg.printerPort || 9100);
        }
      } catch (e) {}
    })();
  }, []);

  const handleSave = async () => {
    setSaving(true);
    setStatus(null);
    try {
      await setConfigPrinters({
        kitchenPrinterIp: kitchenIp,
        counterPrinterIp: counterIp,
        printerPort: port,
      });
      setStatus("Saved successfully Γ£ô");
      setTimeout(() => setStatus(null), 3000);
    } catch (e: any) {
      setStatus("Save failed: " + (e?.message || String(e)));
    }
    setSaving(false);
  };

  const doTestPrint = async (printer: "kitchen" | "counter") => {
    setStatus(`Testing ${printer}...`);
    try {
      // @ts-ignore
      const res = await window.pos.testPrint(printer);
      if (res?.ok) {
        setStatus(`${printer} printer reachable Γ£ô`);
        setTimeout(() => setStatus(null), 3000);
      } else {
        setStatus(`${printer} failed: ${res?.error || "unknown"}`);
      }
    } catch (e: any) {
      setStatus(`${printer} failed: ${e?.message || String(e)}`);
    }
  };

  return (
    <div style={{ padding: "20px 24px", maxWidth: 800, margin: "0 auto" }}>
      {/* Header */}
      <div style={{ marginBottom: 28 }}>
        <h2
          style={{
            margin: 0,
            fontSize: 22,
            fontWeight: 800,
            color: "#111827",
          }}
        >
          Settings
        </h2>
        <p style={{ margin: "3px 0 0", fontSize: 13, color: "#9ca3af" }}>
          Configure your POS system
        </p>
      </div>

      {/* Printers Section */}
      <div
        style={{
          background: "#fff",
          border: "1px solid #e5e7eb",
          borderRadius: 12,
          padding: "24px",
          marginBottom: 24,
        }}
      >
        <div
          style={{
            fontSize: 14,
            fontWeight: 800,
            color: "#111827",
            marginBottom: 20,
            textTransform: "uppercase",
            letterSpacing: "0.05em",
            display: "flex",
            alignItems: "center",
            gap: 8,
          }}
        >
          <span style={{ fontSize: 16 }}>≡ƒû¿∩╕Å</span>
          Printer Configuration
        </div>

        {/* Kitchen Printer */}
        <div style={{ marginBottom: 20 }}>
          <label
            style={{
              display: "block",
              fontSize: 13,
              fontWeight: 600,
              color: "#374151",
              marginBottom: 8,
            }}
          >
            Kitchen Printer IP Address
          </label>
          <div style={{ display: "flex", gap: 10, alignItems: "flex-start" }}>
            <input
              type="text"
              value={kitchenIp}
              onChange={(e) => setKitchenIp(e.target.value)}
              placeholder="e.g., 192.168.1.100"
              style={{
                flex: 1,
                padding: "10px 12px",
                borderRadius: 8,
                border: "1px solid #d1d5db",
                fontSize: 14,
                fontFamily: "monospace",
              }}
            />
            <button
              onClick={() => doTestPrint("kitchen")}
              disabled={!kitchenIp}
              style={{
                padding: "10px 16px",
                borderRadius: 8,
                border: "1px solid #d97706",
                background: "#fff7ed",
                color: "#b45309",
                fontWeight: 600,
                fontSize: 13,
                cursor: kitchenIp ? "pointer" : "not-allowed",
                opacity: kitchenIp ? 1 : 0.5,
                transition: "all 120ms",
              }}
              onMouseEnter={(e) => {
                if (kitchenIp) {
                  (e.currentTarget as HTMLButtonElement).style.background =
                    "#fed7aa";
                }
              }}
              onMouseLeave={(e) => {
                (e.currentTarget as HTMLButtonElement).style.background =
                  "#fff7ed";
              }}
            >
              Test
            </button>
          </div>
        </div>

        {/* Counter Printer */}
        <div style={{ marginBottom: 24 }}>
          <label
            style={{
              display: "block",
              fontSize: 13,
              fontWeight: 600,
              color: "#374151",
              marginBottom: 8,
            }}
          >
            Counter Printer IP Address
          </label>
          <div style={{ display: "flex", gap: 10, alignItems: "flex-start" }}>
            <input
              type="text"
              value={counterIp}
              onChange={(e) => setCounterIp(e.target.value)}
              placeholder="e.g., 192.168.1.101"
              style={{
                flex: 1,
                padding: "10px 12px",
                borderRadius: 8,
                border: "1px solid #d1d5db",
                fontSize: 14,
                fontFamily: "monospace",
              }}
            />
            <button
              onClick={() => doTestPrint("counter")}
              disabled={!counterIp}
              style={{
                padding: "10px 16px",
                borderRadius: 8,
                border: "1px solid #0369a1",
                background: "#f0f9ff",
                color: "#0c4a6e",
                fontWeight: 600,
                fontSize: 13,
                cursor: counterIp ? "pointer" : "not-allowed",
                opacity: counterIp ? 1 : 0.5,
                transition: "all 120ms",
              }}
              onMouseEnter={(e) => {
                if (counterIp) {
                  (e.currentTarget as HTMLButtonElement).style.background =
                    "#cffafe";
                }
              }}
              onMouseLeave={(e) => {
                (e.currentTarget as HTMLButtonElement).style.background =
                  "#f0f9ff";
              }}
            >
              Test
            </button>
          </div>
        </div>

        {/* Port */}
        <div style={{ marginBottom: 24 }}>
          <label
            style={{
              display: "block",
              fontSize: 13,
              fontWeight: 600,
              color: "#374151",
              marginBottom: 8,
            }}
          >
            Printer Port
          </label>
          <input
            type="number"
            value={port}
            onChange={(e) => setPort(Number(e.target.value))}
            style={{
              width: 120,
              padding: "10px 12px",
              borderRadius: 8,
              border: "1px solid #d1d5db",
              fontSize: 14,
              fontFamily: "monospace",
            }}
          />
          <p
            style={{
              fontSize: 12,
              color: "#9ca3af",
              marginTop: 6,
            }}
          >
            Default: 9100 (for network printers)
          </p>
        </div>

        {/* Action Buttons */}
        <div
          style={{
            display: "flex",
            gap: 10,
            alignItems: "center",
            paddingTop: 12,
            borderTop: "1px solid #e5e7eb",
          }}
        >
          <button
            onClick={handleSave}
            disabled={saving}
            style={{
              padding: "10px 20px",
              background: "#16a34a",
              color: "#fff",
              border: "none",
              borderRadius: 8,
              fontWeight: 600,
              fontSize: 14,
              cursor: saving ? "not-allowed" : "pointer",
              opacity: saving ? 0.7 : 1,
              transition: "all 120ms",
            }}
            onMouseEnter={(e) => {
              if (!saving) {
                (e.currentTarget as HTMLButtonElement).style.background =
                  "#15803d";
              }
            }}
            onMouseLeave={(e) => {
              (e.currentTarget as HTMLButtonElement).style.background =
                "#16a34a";
            }}
          >
            {saving ? "Saving..." : "Save Changes"}
          </button>
          <button
            onClick={() => {
              setKitchenIp("");
              setCounterIp("");
              setPort(9100);
              setStatus(null);
            }}
            style={{
              padding: "10px 20px",
              background: "#f3f4f6",
              color: "#374151",
              border: "1px solid #d1d5db",
              borderRadius: 8,
              fontWeight: 600,
              fontSize: 14,
              cursor: "pointer",
              transition: "all 120ms",
            }}
            onMouseEnter={(e) => {
              (e.currentTarget as HTMLButtonElement).style.background =
                "#e5e7eb";
            }}
            onMouseLeave={(e) => {
              (e.currentTarget as HTMLButtonElement).style.background =
                "#f3f4f6";
            }}
          >
            Reset
          </button>

          {status && (
            <div
              style={{
                marginLeft: "auto",
                padding: "8px 12px",
                borderRadius: 8,
                fontSize: 13,
                fontWeight: 600,
                background: status.includes("Γ£ô")
                  ? "#dcfce7"
                  : status.includes("failed") || status.includes("Failed")
                  ? "#fee2e2"
                  : "#fef3c7",
                color: status.includes("Γ£ô")
                  ? "#16a34a"
                  : status.includes("failed") || status.includes("Failed")
                  ? "#dc2626"
                  : "#b45309",
              }}
            >
              {status}
            </div>
          )}
        </div>
      </div>

      {/* Info Box */}
      <div
        style={{
          background: "#f0f9ff",
          border: "1px solid #bae6fd",
          borderRadius: 12,
          padding: "16px",
          fontSize: 13,
          color: "#0c4a6e",
          lineHeight: 1.6,
        }}
      >
        <div style={{ fontWeight: 600, marginBottom: 8 }}>≡ƒÆí Printer Setup</div>
        <div>
          Network printers typically use port 9100. If you're unsure of your
          printer's IP address, check your printer's network settings or
          administration panel.
        </div>
        <div style={{ marginTop: 8 }}>
          After entering the IP address, use the Test button to verify
          connectivity.
        </div>
      </div>
    </div>
  );
}

import React from "react";
import { printReceipt, printKOT } from "../../../app/services/printer";
import {
  seedTables,
  getTables,
  getOrCreateOrderForTable,
  getOpenOrderForTable,
  getOpenOrders,
} from "../../../app/db/pouch";
import styles from "./Tables.module.css";

type TableInfo = {
  id: number;
  seats: number;
  occupied: boolean;
  orderSummary?: string;
};

export default function Tables() {
  const [query, setQuery] = React.useState("");
  const [tables, setTables] = React.useState<TableInfo[]>([]);
  const [openOrders, setOpenOrders] = React.useState<any[] | null>(null);

  const refresh = React.useCallback(async () => {
    const docs = await getTables();
    const mapped = await Promise.all(
      docs.map(async (d) => {
        const open = await getOpenOrderForTable(d.id);
        const hasItems = !!open && (open.items || []).length > 0;
        return {
          id: d.id,
          seats: d.seats,
          occupied: hasItems,
          orderSummary: hasItems ? `${open.items.length} items` : undefined,
        } as TableInfo;
      }),
    );
    mapped.sort((a, b) => a.id - b.id);
    setTables(mapped);
  }, []);

  React.useEffect(() => {
    (async () => {
      await seedTables(12);
      await refresh();
    })();
    const onOrdersChanged = () => refresh();
    window.addEventListener("orders-changed", onOrdersChanged);
    return () => window.removeEventListener("orders-changed", onOrdersChanged);
  }, [refresh]);

  const filtered = tables.filter(
    (t) =>
      String(t.id).includes(query) ||
      (t.orderSummary || "").toLowerCase().includes(query.toLowerCase()),
  );

  const openBilling = async (table: TableInfo) => {
    try {
      const order = await getOrCreateOrderForTable(table.id);
      window.localStorage.setItem("currentOrderId", order._id);
      window.localStorage.setItem("currentTable", String(table.id));
      window.dispatchEvent(new Event("orders-changed"));
    } catch (e) {
      console.error(e);
    }
    window.dispatchEvent(
      new CustomEvent("select-table", { detail: { table: table.id } }),
    );
  };

  const onTestPrint = async () => {
    const res = await printReceipt({
      text: "Test Receipt from Restaurant POS\nThank you!",
    });
    if (!res.ok) {
alert("Print failed: " + (res.error || "unknown"));
}
  };

  const onTestKOT = async () => {
    const res = await printKOT({ text: "Test KOT\nTable 1 - 2x Burger" });
    if (!res.ok) {
alert("KOT print failed: " + (res.error || "unknown"));
}
  };

  const occupied = tables.filter((t) => t.occupied).length;
  const available = tables.filter((t) => !t.occupied).length;

  return (
    <div className={styles.page}>
      <div className={styles.content}>
        {/* Page header */}
        <div className={styles.header}>
          <div>
            <h2 className={styles.title}>Tables</h2>
            <p className={styles.meta}>
              <span style={{ color: "#ef4444", fontWeight: 700 }}>
                {occupied}
              </span>{" "}
              occupied &nbsp;┬╖&nbsp;
              <span style={{ color: "#16a34a", fontWeight: 700 }}>
                {available}
              </span>{" "}
              available
            </p>
          </div>
          <div className={styles.controls}>
            <input
              aria-label="Search tables"
              placeholder="Search tableΓÇª"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              className={styles.input}
            />
            <button
              onClick={async () => {
                const ops = await getOpenOrders();
                setOpenOrders(ops);
              }}
              className={styles.btn}
            >
              Open Orders
            </button>
            <button onClick={onTestKOT} className={styles.btn}>
              Test KOT
            </button>
            <button onClick={onTestPrint} className={styles.btn}>
              Test Print
            </button>
          </div>
        </div>

        {/* Table grid */}
        <div className={styles.grid}>
          {filtered.map((t) => (
            <article
              key={t.id}
              role="button"
              tabIndex={0}
              onClick={() => openBilling(t)}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
openBilling(t);
}
              }}
              className={
                styles.card + (t.occupied ? ` ${styles.occupied}` : "")
              }
            >
              <div className={styles.headerInfo}>
                <div>
                  <div className={styles.id}>{t.id}</div>
                  <div className={styles.subtle}>{t.seats} seats</div>
                </div>
                <span
                  style={{
                    padding: "4px 10px",
                    borderRadius: 20,
                    fontSize: 11,
                    fontWeight: 700,
                    background: t.occupied ? "#fee2e2" : "#dcfce7",
                    color: t.occupied ? "#dc2626" : "#16a34a",
                  }}
                >
                  {t.occupied ? "Occupied" : "Free"}
                </span>
              </div>
              <div
                className={
                  t.occupied ? styles.orderSummaryOccupied : styles.orderSummary
                }
              >
                {t.orderSummary || (t.occupied ? "In progress" : "Tap to open")}
              </div>
            </article>
          ))}
        </div>

        {filtered.length === 0 && (
          <div className={styles.noMatch}>No tables match that search.</div>
        )}

        {/* Open Orders modal */}
        {openOrders && (
          <div
            className={styles.modalOverlay}
            onClick={() => setOpenOrders(null)}
          >
            <div
              className={styles.modalDialog}
              onClick={(e) => e.stopPropagation()}
            >
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  marginBottom: 16,
                }}
              >
                <h3
                  style={{
                    margin: 0,
                    fontSize: 18,
                    fontWeight: 800,
                    color: "#111827",
                  }}
                >
                  Open Orders ({openOrders.length})
                </h3>
                <button
                  onClick={() => setOpenOrders(null)}
                  className={styles.modalClose}
                >
                  ├ù
                </button>
              </div>
              <div className={styles.modalList}>
                {openOrders.length === 0 && (
                  <p
                    style={{
                      color: "#9ca3af",
                      textAlign: "center",
                      padding: "24px 0",
                    }}
                  >
                    No open orders
                  </p>
                )}
                {openOrders.map((o) => (
                  <div key={o._id} className={styles.modalItem}>
                    <div
                      style={{
                        fontWeight: 700,
                        fontSize: 14,
                        color: "#111827",
                      }}
                    >
                      Table {String(o.tableId)}
                    </div>
                    <div
                      style={{ fontSize: 12, color: "#6b7280", marginTop: 2 }}
                    >
                      {(o.items || []).length} items ┬╖ {o.status}
                    </div>
                  </div>
                ))}
              </div>
              <div style={{ textAlign: "right", marginTop: 16 }}>
                <button
                  onClick={() => setOpenOrders(null)}
                  className={styles.btn}
                  style={{ padding: "9px 20px" }}
                >
                  Close
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
